awer-body{padding:20px 24px}.jr-legacy .drawer-section{margin-bottom:24px}.jr-legacy .drawer-section h3{margin:0 0 10px;font:600 17px var(--font-mono);color:var(--slate-500);letter-spacing:normal;text-transform:none}.jr-legacy .info-row{display:flex;justify-content:space-between;padding:8px 0;border-bottom:1px solid var(--border);font-size:17px}.jr-legacy .info-row:last-child{border-bottom:0}.jr-legacy .info-row .k{color:var(--slate-500)}.jr-legacy .info-row .v{color:var(--slate-900);font-weight:500}.jr-legacy .doc-list{display:flex;flex-direction:column;gap:8px}.jr-legacy .doc-card{background:var(--slate-50);border:1px solid var(--border);border-radius:6px;padding:10px 12px;display:flex;align-items:center;gap:10px}.jr-legacy .doc-card .ic{width:32px;height:32px;border-radius:6px;background:#FFFFFF;border:1px solid var(--border);display:grid;place-items:center;font:700 17px var(--font-mono);color:var(--slate-600)}.jr-legacy .doc-card .ic.uploaded{background:var(--success-50);color:var(--success-600);border-color:var(--success-50)}.jr-legacy .doc-card .nm{flex:1;font-size:17px;font-weight:500}.jr-legacy .doc-card .pill-mini{font-size:17px;padding:2px 6px}.jr-legacy .upload-zone{border:2px dashed var(--teal-200);background:var(--teal-50);border-radius:6px;padding:16px;text-align:center;cursor:pointer;font-size:17px;color:var(--teal-800);transition:background 120ms ease}.jr-legacy .upload-zone:hover{background:#F4F1E8}.jr-legacy .empty{padding:48px 20px;text-align:center;color:var(--slate-500);font-size:17px}.jr-legacy .empty svg{color:var(--slate-300);margin-bottom:12px}.jr-legacy .toast{position:fixed;bottom:24px;left:50%;transform:translateX(-50%);background:var(--slate-900);color:#FFFFFF;padding:12px 20px;border-radius:6px;font-size:17px;opacity:0;transition:opacity 200ms ease;pointer-events:none;z-index:100}.jr-legacy .toast.show{opacity:1}.jr-legacy .auth-wall{position:fixed;inset:0;background:var(--slate-50);display:none;align-items:center;justify-content:center;z-index:999;padding:20px}.jr-legacy .auth-wall.show{display:flex}.jr-legacy .auth-wall .card{background:#FFFFFF;border:1px solid var(--border);border-radius:6px;padding:32px 28px;max-width:380px;width:100%;box-shadow:none}.jr-legacy .auth-wall h2{margin:0 0 6px;font-size:20px;color:var(--slate-900)}.jr-legacy .auth-wall .sub{font-size:17px;color:var(--slate-500);margin-bottom:18px}.jr-legacy .auth-wall .field{margin-bottom:12px}.jr-legacy .auth-wall label{display:block;font-size:17px;color:var(--slate-600);margin-bottom:4px;font-weight:500}.jr-legacy .auth-wall input{width:100%;padding:9px 12px;border:1px solid var(--border);border-radius:6px;font:400 17px var(--font-sans);box-sizing:border-box}.jr-legacy .auth-wall input:focus{outline:none;border-color:var(--teal-600);box-shadow:none}.jr-legacy .auth-wall .btn-go{width:100%;padding:11px;background:var(--teal-700);color:#FFFFFF;border:0;border-radius:6px;font:600 17px var(--font-sans);cursor:pointer;margin-top:6px}.jr-legacy .auth-wall .btn-go:hover{background:var(--teal-800)}.jr-legacy .auth-wall .err{margin-top:10px;padding:9px 12px;background:#FEE2E2;border:1px solid #991B1B;color:var(--danger-600);border-radius:6px;font-size:17px;display:none}.jr-legacy .auth-wall .err.show{display:block}.jr-legacy .auth-wall .hint{margin-top:16px;padding:10px 12px;background:var(--slate-50);border:1px solid var(--border);border-radius:6px;font-size:17px;color:var(--slate-600)}.jr-legacy .auth-wall .hint code{font:500 17px var(--font-mono);background:#FFFFFF;padding:1px 5px;border-radius:4px;border:1px solid var(--border)}.jr-legacy .auth-wall .switch{margin-top:10px;text-align:center;font-size:17px;color:var(--slate-500)}.jr-legacy .auth-wall .switch a{color:var(--teal-700);font-weight:500}
/* Surcharges design system */

.jr-legacy .layout{background:var(--paper)}
.jr-legacy .sidebar{background:var(--card);border-right:1px solid var(--line);gap:var(--space-5);padding:var(--space-5) var(--space-4)}
.jr-legacy .sidebar .brand{padding:0 var(--space-2);text-decoration:none}
.jr-legacy .total-widget{background:var(--ink);color:var(--paper);border-radius:var(--radius-md);padding:var(--space-4)}
.jr-legacy .total-widget::before{display:none}
.jr-legacy .total-widget .lbl{font:var(--type-label);opacity:1}
.jr-legacy .total-widget .val{font:var(--type-amount);font-size:32px;line-height:36px;color:var(--accent-on-dark);font-variant-numeric:tabular-nums}
.jr-legacy .total-widget .sub{font:var(--type-caption);opacity:1}
.jr-legacy .total-widget .pgrs{background:var(--action)}
.jr-legacy .total-widget .pgrs i{background:var(--accent-on-dark)}
.jr-legacy .nav{display:flex;flex-direction:column;gap:2px}
.jr-legacy .nav-section{font:var(--type-label);color:var(--ink);padding:var(--space-3) var(--space-2) var(--space-1);opacity:1}
.jr-legacy .nav a{display:flex;align-items:center;gap:var(--space-3);min-height:var(--hit-min);padding:0 var(--space-2);border-radius:var(--radius-sm);font:var(--type-body);color:var(--ink);text-decoration:none;background:transparent}
.jr-legacy .nav a:hover{background:var(--paper)}
.jr-legacy .nav a.active{font-weight:700;background:var(--paper-deep);color:var(--ink);text-decoration:underline;text-underline-offset:6px;text-decoration-thickness:2px}
.jr-legacy .nav a .jr-picto{color:var(--ink)}
.jr-legacy .nav a .badge{background:var(--paper-deep);color:var(--ink);border-radius:var(--radius-sm);font:var(--type-label);padding:0 var(--space-2)}
.jr-legacy .me{display:flex;align-items:center;gap:var(--space-3);padding:var(--space-3) var(--space-2);border-top:1px solid var(--line)}
.jr-legacy .me .av{width:40px;height:40px;border-radius:var(--radius-sm);background:var(--ink);color:var(--paper);display:grid;place-items:center;font:var(--type-label)}
.jr-legacy .me .nm{font:var(--type-label)}
.jr-legacy .me .em{font:var(--type-caption)}
@media (max-width:880px){
 .jr-legacy .layout{display:block}
 .jr-legacy .sidebar,.jr-legacy .sidebar:not(.open){display:flex!important;position:static;height:auto;border-right:0;border-bottom:1px solid var(--line)}
 .jr-legacy .sidebar .nav{flex-direction:row;flex-wrap:wrap;gap:var(--space-1) var(--space-2)}
 .jr-legacy .sidebar .nav-section,.jr-legacy .sidebar .exit,.jr-legacy .sidebar .me{display:none}
 .jr-legacy .nav a{border:1px solid var(--line-strong)}
}
.jr-legacy h1{font:var(--type-h1);font-size:clamp(30px,5vw,40px);line-height:1.15;letter-spacing:normal;color:var(--ink)}
.jr-legacy main h2{font-family:var(--font-text)}
.jr-legacy .btn{display:inline-flex;align-items:center;justify-content:center;gap:var(--space-2);min-height:var(--hit-min);padding:0 var(--space-5);border-radius:var(--radius-sm);font:var(--fw-bold) var(--fs-body)/var(--lh-label) var(--font-text);cursor:pointer;text-decoration:none;border:1px solid transparent}
.jr-legacy .btn-primary,.jr-legacy .btn-amber{background:var(--action);color:var(--card)}
.jr-legacy .btn-primary:hover,.jr-legacy .btn-amber:hover{background:var(--action-deep);color:var(--card)}
.jr-legacy .btn-secondary,.jr-legacy .btn-ghost,.jr-legacy .btn-outline{background:var(--card);color:var(--ink);border-color:var(--ink)}
.jr-legacy .btn-secondary:hover,.jr-legacy .btn-ghost:hover,.jr-legacy .btn-outline:hover{background:var(--paper-deep)}
.jr-legacy .btn:disabled,.jr-legacy .btn[disabled]{background:var(--paper-deep)!important;color:var(--ink)!important;border-color:var(--paper-deep)!important;cursor:not-allowed}
.jr-legacy input:not([type=checkbox]):not([type=radio]):not([type=range]),.jr-legacy select,.jr-legacy textarea{min-height:var(--hit-min);font:var(--type-body);border:1px solid var(--line-strong);border-radius:var(--radius-sm);background:var(--card);color:var(--ink)}
.jr-legacy input[type=checkbox],.jr-legacy input[type=radio]{width:22px;height:22px;accent-color:var(--action)}

/* Échelle DPE : couleurs réglementaires A→G (exception documentée au design system — code officiel du diagnostic de performance énergétique). */
.jr-legacy{--dpe-a:#00A651;--dpe-b:#52B847;--dpe-c:#C8D400;--dpe-d:#FFED00;--dpe-e:#FFB400;--dpe-f:#FF6900;--dpe-g:#E20613}
