.jr-legacy .dpe-bar .lvl{height:16px!important}
.jr-legacy .dpe-bar.from{outline:3px dashed var(--ink)!important;outline-offset:2px}
.jr-legacy .dpe-bar.to{outline:3px solid var(--ink)!important;outline-offset:2px}
.jr-legacy .dpe-bar.from .kwh::after{content:" · actuel"!important;font-weight:700}
.jr-legacy .dpe-bar.to .kwh::after{content:" · projeté"!important;font-weight:700}
.jr-legacy .dpe-bar.from.to .kwh::after{content:" · actuel et projeté"!important}
.jr-legacy .dpe-tile.selected .dpe-r::after{content:"Classe actuelle";font:var(--type-label);margin-top:2px}
/* Encart garantie */
.jr-legacy .jr-garantie{display:flex;gap:var(--space-3);align-items:flex-start;padding:var(--space-5);background:var(--card);border:2px solid var(--action);border-radius:var(--radius-md);margin:0 0 var(--space-4)}
.jr-legacy .jr-garantie h3{margin:0 0 var(--space-1);font:var(--type-h3);font-weight:700}
.jr-legacy .jr-garantie p{margin:0;font:var(--type-body)}

