;font-size:17px;color:var(--slate-600);line-height:1.5}@media (max-width:980px){.jr-legacy .mobile-topbar{display:flex}}@media (max-width:880px){.jr-legacy .layout{grid-template-columns:minmax(0,1fr)}.jr-legacy .sidebar:not(.open){display:none}.jr-legacy .layout > main,.jr-legacy .layout > .main{min-width:0;max-width:100%;overflow-x:hidden}.jr-legacy .layout table{display:block;overflow-x:auto;max-width:100%}}@media (prefers-reduced-motion:reduce){.jr-legacy *{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important;scroll-behavior:auto!important}}.jr-legacy :where(input,select,textarea,button,a,[tabindex]):focus-visible{outline:2px solid var(--teal-700)!important;outline-offset:2px!important}.jr-legacy .suggest > *:focus-visible,.jr-legacy .suggest .item:focus-visible,.jr-legacy .suggest li:focus-visible{outline:2px solid var(--teal-700)!important;outline-offset:-2px!important}
/* Surcharges design system */

.jr-legacy .layout{background:var(--paper)}
.jr-legacy .sidebar{background:var(--card);border-right:1px solid var(--line);gap:var(--space-5);padding:var(--space-5) var(--space-4)}
