}
.jr-legacy h1{font:var(--type-h1);font-size:clamp(30px,5vw,40px);line-height:1.15;letter-spacing:normal;color:var(--ink)}
.jr-legacy main h2{font-family:var(--font-text)}
.jr-legacy .btn{display:inline-flex;align-items:center;justify-content:center;gap:var(--space-2);min-height:var(--hit-min);padding:0 var(--space-5);border-radius:var(--radius-sm);font:var(--fw-bold) var(--fs-body)/var(--lh-label) var(--font-text);cursor:pointer;text-decoration:none;border:1px solid transparent}
.jr-legacy .btn-primary,.jr-legacy .btn-amber{background:var(--action);color:var(--card)}
