legacy .signup .legal{display:flex;align-items:flex-start;gap:10px;font-size:17px;color:var(--slate-600);line-height:1.5;margin-bottom:18px}.jr-legacy .signup .legal input{margin-top:3px;flex:0 0 auto;accent-color:var(--teal-700)}.jr-legacy .signup .legal a{color:var(--teal-700);text-decoration:underline}.jr-legacy .signup .pay-row{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.jr-legacy .signup .pay-meta{font-size:17px;color:var(--slate-500);display:flex;align-items:center;gap:8px}.jr-legacy .signup .pay-meta svg{color:var(--success-600,#065F46)}.jr-legacy .signup .field{margin-bottom:0}.jr-legacy .row-3{display:grid;grid-template-columns:1fr 1fr;gap:14px}.jr-legacy .rf-dossier-block .card{max-width:720px;margin:0 auto 32px}.jr-legacy .tunnel-autonomie #rf-mpa-checkout .card[style*="teal"],.jr-legacy .tunnel-autonomie #rf-lhi-checkout .card[style*="teal"]{border-color:#123A2E!important}.jr-legacy .tunnel-autonomie .rf-hero-roi{border-color:#E9E3D3}.jr-legacy .tunnel-autonomie .rf-hero-roi__main{background:#E9E3D3}.jr-legacy .tunnel-autonomie .rf-hero-roi__label,.jr-legacy .tunnel-autonomie .rf-hero-roi__amount{color:#123A2E}.jr-legacy .tunnel-autonomie .rf-dossier__benefit--star{background:#E9E3D3;border-color:#E9E3D3;border-bottom-color:#E9E3D3!important}.jr-legacy .tunnel-autonomie .rf-dossier__benefit--star strong::after{color:#123A2E;border-color:#E9E3D3}.jr-legacy .tunnel-autonomie #mpa-scroll-to-form,.jr-legacy .tunnel-autonomie #lhi-scroll-to-form{background:#123A2E;border-color:#123A2E}.jr-legacy .tunnel-autonomie #mpa-scroll-to-form:hover,.jr-legacy .tunnel-autonomie #lhi-scroll-to-form:hover{background:#123A2E;border-color:#123A2E}@media (prefers-reduced-motion:reduce){.jr-legacy *{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important;scroll-behavior:auto!important}}.jr-legacy :where(input,select,textarea,button,a,[tabindex]):focus-visible{outline:2px solid var(