/* Surcharges design system */

.jr-legacy .layout{background:var(--paper)}
.jr-legacy .sidebar{background:var(--card);border-right:1px solid var(--line);gap:var(--space-5);padding:var(--space-5) var(--space-4)}
.jr-legacy .sidebar .brand{padding:0 var(--space-2);text-decoration:none}
.jr-legacy .total-widget{background:var(--ink);color:var(--paper);border-radius:var(--radius-md);padding:var(--space-4)}
.jr-legacy .total-widget::before{display:none}
.jr-legacy .total-widget .lbl{font:var(--type-label);opacity:1}
.jr-legacy .total-widget .val{font:var(--type-amount);font-size:32px;line-height:36px;color:var(--accent-on-dark);font-variant-numeric:tabular-nums}
.jr-legacy .total-widget .sub{font:var(--type-caption);opacity:1}
.jr-legacy .total-widget .pgrs{background:var(--action)}
.jr-legacy .total-widget .pgrs i{background:var(--accent-on-dark)}
.jr-legacy .nav{display:flex;flex-direction:column;gap:2px}
.jr-legacy .nav-section{font:var(--type-label);color:var(--ink);padding:var(--space-3) var(--space-2) var(--space-1);opacity:1}
.jr-legacy .nav a{display:flex;align-items:center;gap:var(--space-3);min-height:var(--hit-min);padding:0 var(--space-2);border-radius:var(--radius-sm);font:var(--type-body);color:var(--ink);text-decoration:none;background:transparent}
.jr-legacy .nav a:hover{background:var(--paper)}
.jr-legacy .nav a.active{font-weight:700;background:var(--paper-deep);color:var(--ink);text-decoration:underline;text-underline-offset:6px;text-decoration-thickness:2px}
.jr-legacy .nav a .jr-picto{color:var(--ink)}
.jr-legacy .nav a .badge{background:var(--paper-deep);color:var(--ink);border-radius:var(--radius-sm);font:var(--type-label);padding:0 var(--space-2)}
.jr-legacy .me{display:flex;align-items:center;gap:var(--space-3);padding:var(--space-3) var(--space-2);border-top:1px solid var(--line)}
.jr-legacy .me .av{width:40px;height:40px;border-radius:var(--radius-sm);background:var(--ink);color:var(--paper);display:grid;place-items:center;font:var(--type-label)}
.jr-legacy .me .nm{font:var(--type-label)}
.jr-legacy .me .em{font:var(--type-caption)}
@media (max-width:880px){
 .jr-legacy .layout{display:block}
 .jr-legacy .sidebar,.jr-legacy .sidebar:not(.open){display:flex!important;position:static;height:auto;border-right:0;border-bottom:1px solid var(--line)}
 .jr-legacy .sidebar .nav{flex-direction:row;flex-wrap:wrap;gap:var(--space-1) var(--space-2)}
 .jr-legacy .sidebar .nav-section,.jr-legacy .sidebar .exit,.jr-legacy .sidebar .me{display:none}
 .jr-legacy .nav a{border:1px solid var(--line-strong)}
}
.jr-legacy h1{font:var(--type-h1);font-size:clamp(30px,5vw,40px);line-height:1.15;letter-spacing:normal;color:var(--ink)}
.jr-legacy main h2{font-family:var(--font-text)}
.jr-legacy .btn{display:inline-flex;align-items:center;justify-content:center;gap:var(--space-2);min-height:var(--hit-min);padding:0 var(--space-5);border-radius:var(--radius-sm);font:var(--fw-bold) var(--fs-body)/var(--lh-label) var(--font-text);cursor:pointer;text-decoration:none;border:1px solid transparent}
.jr-legacy .btn-primary,.jr-legacy .btn-amber{background:var(--action);color:var(--card)}
.jr-legacy .btn-primary:hover,.jr-legacy .btn-amber:hover{background:var(--action-deep);color:var(--card)}
.jr-legacy .btn-secondary,.jr-legacy .btn-ghost,.jr-legacy .btn-outline{background:var(--card);color:var(--ink);border-color:var(--ink)}
.jr-legacy .btn-secondary:hover,.jr-legacy .btn-ghost:hover,.jr-legacy .btn-outline:hover{background:var(--paper-deep)}
.jr-legacy .btn:disabled,.jr-legacy .btn[disabled]{background:var(--paper-deep)!important;color:var(--ink)!important;border-color:var(--paper-deep)!important;cursor:not-allowed}
.jr-legacy input:not([type=checkbox]):not([type=radio]):not([type=range]),.jr-legacy select,.jr-legacy textarea{min-height:var(--hit-min);font:var(--type-body);border:1px solid var(--line-strong);border-radius:var(--radius-sm);background:var(--card);color:var(--ink)}
.jr-legacy input[type=checkbox],.jr-legacy input[type=radio]{width:22px;height:22px;accent-color:var(--action)}

/* Échelle DPE : couleurs réglementaires A→G (exception documentée au design system — code officiel du diagnostic de performance énergétique). */
.jr-legacy{--dpe-a:#00A651;--dpe-b:#52B847;--dpe-c:#C8D400;--dpe-d:#FFED00;--dpe-e:#FFB400;--dpe-f:#FF6900;--dpe-g:#E20613}
.jr-legacy [data-dpe="A"] .dpe-l,.jr-legacy [data-classe="A"] .dpe-letter,.jr-legacy [data-classe="A"] .lvl{background:var(--dpe-a)!important;color:#123A2E!important}
.jr-legacy [data-dpe="B"] .dpe-l,.jr-legacy [data-classe="B"] .dpe-letter,.jr-legacy [data-classe="B"] .lvl{background:var(--dpe-b)!important;color:#123A2E!important}
.jr-legacy [data-dpe="C"] .dpe-l,.jr-legacy [data-classe="C"] .dpe-letter,.jr-legacy [data-classe="C"] .lvl{background:var(--dpe-c)!important;color:#123A2E!important}
.jr-legacy [data-dpe="D"] .dpe-l,.jr-legacy [data-classe="D"] .dpe-letter,.jr-legacy [data-classe="D"] .lvl{background:var(--dpe-d)!important;color:#123A2E!important}
.jr-legacy [data-dpe="E"] .dpe-l,.jr-legacy [data-classe="E"] .dpe-letter,.jr-legacy [data-classe="E"] .lvl{background:var(--dpe-e)!important;color:#123A2E!important}
.jr-legacy [data-dpe="F"] .dpe-l,.jr-legacy [data-classe="F"] .dpe-letter,.jr-legacy [data-classe="F"] .lvl{background:var(--dpe-f)!important;color:#123A2E!important}
.jr-legacy [data-dpe="G"] .dpe-l,.jr-legacy [data-classe="G"] .dpe-letter,.jr-legacy [data-classe="G"] .lvl{background:var(--dpe-g)!important;color:#FFFFFF!important}
.jr-legacy [data-dpe=""] .dpe-l{background:var(--paper-deep)!important;color:var(--ink)!important}
.jr-legacy .dpe-l,.jr-legacy .dpe-letter{font-weight:800!important;font-size:20px!important}
.jr-legacy .dpe-bar .lvl{height:16px!important}
.jr-legacy .dpe-bar.from{outline:3px dashed var(--ink)!important;outline-offset:2px}
.jr-legacy .dpe-bar.to{outline:3px solid var(--ink)!important;outline-offset:2px}
.jr-legacy .dpe-bar.from .kwh::after{content:" · actuel"!important;font-weight:700}
.jr-legacy .dpe-bar.to .kwh::after{content:" · projeté"!important;font-weight:700}
.jr-legacy .dpe-bar.from.to .kwh::after{content:" · actuel et projeté"!important}
.jr-legacy .dpe-tile.selected .dpe-r::after{content:"Classe actuelle";font:var(--type-label);margin-top:2px}
/* Encart garantie */
.jr-legacy .jr-garantie{display:flex;gap:var(--space-3);align-items:flex-start;padding:var(--space-5);background:var(--card);border:2px solid var(--action);border-radius:var(--radius-md);margin:0 0 var(--space-4)}
.jr-legacy .jr-garantie h3{margin:0 0 var(--space-1);font:var(--type-h3);font-weight:700}
.jr-legacy .jr-garantie p{margin:0;font:var(--type-body)}

/* JungleRenov — habillage des parcours (tunnels, espace, admin).
   Réécrit intégralement sur les tokens du design system : aucune valeur de l'ancien site.
   Ne s'applique qu'à l'intérieur de .jr-legacy (zone dont le comportement vient des scripts métier). */
.jr-legacy{
  --teal-50:var(--paper);--teal-100:var(--paper-deep);--teal-200:var(--paper-deep);--teal-400:var(--action);--teal-600:var(--action);--teal-700:var(--action);--teal-800:var(--ink);--teal-900:var(--ink);
  --amber-50:var(--paper-deep);--amber-100:var(--paper-deep);--amber-300:var(--paper-deep);--amber-500:var(--ink);--amber-600:var(--ink);--amber-700:var(--ink);--amber-800:var(--ink);
  --slate-50:var(--paper);--slate-100:var(--paper-deep);--slate-200:var(--paper-deep);--slate-300:var(--off);--slate-400:var(--off);--slate-500:var(--ink);--slate-600:var(--ink);--slate-700:var(--ink);--slate-800:var(--ink);--slate-900:var(--ink);
  --success-50:var(--ok-wash);--success-100:var(--ok-wash);--success-600:var(--ok);--success-700:var(--ok);--danger-50:var(--ko-wash);--danger-100:var(--ko-wash);--danger-600:var(--ko);--danger-700:var(--ko);
  --info-50:var(--paper-deep);--info-600:var(--ink);--violet-50:var(--paper-deep);--violet-600:var(--ink);--violet-700:var(--ink);
  --bg:var(--paper);--surface:var(--card);--border:var(--line);--text:var(--ink);
  --shadow-xs:none;--shadow-sm:none;--shadow-md:none;--shadow-lg:none;
  --font-sans:var(--font-text);--font-mono:var(--font-text);
  color:var(--ink);font:var(--type-body);
}
.jr-legacy *,.jr-legacy *::before,.jr-legacy *::after{box-sizing:border-box}
.jr-legacy [hidden]{display:none!important}
.jr-legacy a{color:var(--action);text-decoration:underline;text-underline-offset:3px}
.jr-legacy a:hover{color:var(--ink)}
.jr-legacy button{font-family:var(--font-text)}
.jr-legacy :where(input,select,textarea,button,a,summary,[tabindex]):focus-visible{outline:var(--focus-width) solid var(--focus-ring)!important;outline-offset:var(--focus-offset)!important}
.jr-legacy .sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.jr-legacy strong,.jr-legacy b{font-weight:700}
.jr-legacy em{font-style:normal}
.jr-legacy code{font:var(--type-caption);background:var(--paper-deep);padding:0 4px;border-radius:var(--radius-sm)}
.jr-legacy abbr[title]{text-decoration:underline dotted;text-underline-offset:3px;cursor:help}
.jr-legacy p{text-wrap:pretty}

/* Pictogrammes hydratés */
.jr-legacy .jr-picto{display:inline-flex;flex:none;color:currentColor}
.jr-legacy .jr-picto svg{display:block}

/* Gabarit */


.jr-legacy .screen{display:none}
.jr-legacy .screen.active{display:block}
.jr-legacy .step-eyebrow{font:var(--type-label);color:var(--ink)}
.jr-legacy h1.q-title,.jr-legacy .rf-step-title{font:var(--type-h1);font-size:clamp(30px,5vw,40px);line-height:1.15;margin:var(--space-3) 0 var(--space-4);text-wrap:balance;color:var(--ink)}
.jr-legacy .q-sub,.jr-legacy .rf-step-lede{font:var(--type-lead);margin:0 0 var(--space-6);max-width:var(--measure);color:var(--ink)}
.jr-legacy .card{background:var(--card);border:1px solid var(--line);border-radius:var(--radius-md);padding:var(--space-6)}
@media (max-width:640px){.jr-legacy .card{padding:var(--space-5) var(--space-4)}.jr-legacy main{padding:var(--space-6) var(--space-4) 0}}

/* Champs (construction TextField / Select du design system) */
.jr-legacy .field,.jr-legacy .rf-field{display:flex;flex-direction:column;gap:var(--space-2);margin:0 0 var(--space-5)}
.jr-legacy .field-label,.jr-legacy .rf-field>label,.jr-legacy .rf-field>legend,.jr-legacy legend{font:var(--type-label);color:var(--ink);display:block;padding:0}
.jr-legacy .field-help,.jr-legacy .rf-field small,.jr-legacy small{font:var(--type-caption);color:var(--ink)}
.jr-legacy .field-err{margin:0;font:var(--fw-semibold) var(--fs-caption)/var(--lh-caption) var(--font-text);color:var(--ko)}
