el-head h2{margin:0;font-size:17px;font-weight:700}.jr-legacy .panel-body{padding:18px 20px}.jr-legacy table{width:100%;border-collapse:collapse;font-size:17px}.jr-legacy thead th{text-align:left;padding:10px 16px;background:var(--slate-50);font:600 17px var(--font-mono);color:var(--slate-600);letter-spacing:normal;text-transform:none;border-bottom:1px solid var(--border)}.jr-legacy tbody td{padding:12px 16px;border-bottom:1px solid var(--border)}.jr-legacy tbody tr:last-child td{border-bottom:0}.jr-legacy .pill{display:inline-block;padding:3px 9px;border-radius:4px;font:500 17px var(--font-mono);letter-spacing:normal;text-transform:none}.jr-legacy .pill.admin{background:var(--info-50);color:var(--info-600)}.jr-legacy .pill.super{background:var(--purple-500);color:#FFFFFF}.jr-legacy .btn{display:inline-flex;align-items:center;gap:6px;padding:8px 14px;border:1px solid var(--border);background:#FFFFFF;border-radius:6px;font-family:var(--font-text);font-size:17px;font-weight:500;color:var(--slate-800);cursor:pointer;transition:all 120ms ease}.jr-legacy .btn:hover{border-color:var(--slate-400);background:var(--slate-50)}.jr-legacy .btn-primary{background:var(--purple-600);color:#FFFFFF;border-color:var(--purple-600)}.jr-legacy .btn-primary:hover{background:var(--purple-900)}.jr-legacy .btn-danger{color:var(--danger-600);border-color:#991B1B}.jr-legacy .btn-danger:hover{background:var(--danger-50)}.jr-legacy .setting{display:flex;align-items:flex-start;justify-content:space-between;padding:14px 0;border-bottom:1px solid var(--border);gap:16px}.jr-legacy .setting:last-child{border-bottom:0}.jr-legacy .setting .info{flex:1}.jr-legacy .setting .name{font-weight:600;font-size:17px}.jr-legacy .setting .desc{font-size:17px;color:var(--slate-500);margin-top:2px}.jr-legacy .switch{position:relative;width:44px;height:24px;background:var(--slate-300);border-radius:4px;cursor:pointer;transition:background 150ms}.jr-legacy .switch.on{background:var(--purple-600)}.jr-legacy .switch::after{content:"";position:absolute;top:3px;left:3px;width:18px;height:18px;background:#FFFFFF;border-radius:50%;transition:left 150ms}.jr-legacy .switch.on::after{left:23px}.jr-legacy .toast{position:fixed;bottom:24px;left:50%;transform:translateX(-50%);background:var(--slate-900);color:#FFFFFF;padding:12px 20px;border-radius:6px;font-size:17px;opacity:0;transition:opacity 200ms ease;pointer-events:none;z-index:100}.jr-legacy .toast.show{opacity:1}.jr-legacy .modal-bg{position:fixed;inset:0;background:#123A2E;display:none;align-items:center;justify-content:center;z-index:60}.jr-legacy .modal-bg.open{display:flex}.jr-legacy .modal{background:#FFFFFF;border-radius:6px;padding:24px;max-width:420px;width:90%}.jr-legacy .modal h3{margin:0 0 14px}.jr-legacy .modal label{display:block;margin-bottom:12px;font-size:17px}.jr-legacy .modal input,.jr-legacy .modal select{width:100%;padding:9px 12px;border:1px solid var(--border);border-radius:6px;font-family:var(--font-text);font-size:17px;margin-top:4px}.jr-legacy .modal .actions{display:flex;gap:8px;justify-content:flex-end;margin-top:18px}.jr-legacy .auth-wall{position:fixed;inset:0;background:#F4F1E8;display:none;align-items:center;justify-content:center;z-index:999;padding:20px}.jr-legacy .auth-wall.show{display:flex}.jr-legacy .auth-wall .card-aw{background:#FFFFFF;border:1px solid var(--border);border-radius:6px;padding:32px 28px;max-width:380px;width:100%;box-shadow:none}.jr-legacy .auth-wall h2{margin:0 0 6px;font-size:20px;color:var(--slate-900)}.jr-legacy .auth-wall .sub{font-size:17px;color:var(--slate-500);margin-bottom:18px}.jr-legacy .auth-wall .field{margin-bottom:12px}.jr-legacy .auth-wall label{display:block;font-size:17px;color:var(--slate-700);margin-bottom:4px;font-weight:500}.jr-legacy .auth-wall input{width:100%;padding:9px 12px;border:1px solid var(--border);border-radius:6px;font:400 17px sans-serif;box-sizing:border-box}.jr-legacy .auth-wall input:focus{outline:none;border-color:#123A2E;box-shadow:none