    const CAT = { bleus:'Tres modestes (bleus)', jaunes:'Modestes (jaunes)', violets:'Intermediaires (violets)', roses:'Superieurs (roses)' };
    doc.setDrawColor(226, 232, 240); doc.setLineWidth(0.3);
