    doc.text(`Logement : ${p.surface || '-'} m2 | ${p.heat || '-'} | ${p.region || '-'}${p.dept ? ' | dep. ' + p.dept : ''}`, M + 4, y + 20);
    if (p.dpeCurrent) doc.text(`DPE declare : ${p.dpeCurrent}`, M + 4, y + 27);
