      { id: 'combles',                   label: 'Isolation des combles',              section: 'Isolation thermique',    hint: "jusqu'à 25 €/m²" },
      { id: 'toiture_terrasse',          label: 'Isolation de toiture-terrasse',      section: 'Isolation thermique',    hint: "jusqu'à 75 €/m²" },
