  --slate-50:var(--paper);--slate-100:var(--paper-deep);--slate-200:var(--paper-deep);--slate-300:var(--off);--slate-400:var(--off);--slate-500:var(--ink);--slate-600:var(--ink);--slate-700:var(--ink);--slate-800:var(--ink);--slate-900:var(--ink);
  --success-50:var(--ok-wash);--success-100:var(--ok-wash);--success-600:var(--ok);--success-700:var(--ok);--danger-50:var(--ko-wash);--danger-100:var(--ko-wash);--danger-600:var(--ko);--danger-700:var(--ko);
  --info-50:var(--paper-deep);--info-600:var(--ink);--violet-50:var(--paper-deep);--violet-600:var(--ink);--violet-700:var(--ink);
