/* Calcul */
.jr-legacy .loader-wrap{display:flex;flex-direction:column;align-items:flex-start;padding:var(--space-5) 0}
.jr-legacy .loader-circle{width:120px;height:120px;border-radius:50%;background:conic-gradient(var(--action) var(--p,30%),var(--paper-deep) 0);display:grid;place-items:center;margin-bottom:var(--space-5)}
.jr-legacy .loader-circle .inner{width:96px;height:96px;border-radius:50%;background:var(--card);display:grid;place-items:center;font:var(--type-h3);font-weight:700;font-variant-numeric:tabular-nums}
.jr-legacy #loader-title{font:var(--type-label)!important}
.jr-legacy #loader-sub{font:var(--type-caption)!important}
.jr-legacy .loader-checks{margin-top:var(--space-5);width:100%;max-width:520px;display:flex;flex-direction:column;gap:var(--space-2)}
.jr-legacy .lc-item{display:flex;align-items:center;gap:var(--space-3);min-height:var(--hit-min);padding:var(--space-2) var(--space-4);background:var(--card);border:1px solid var(--line);border-radius:var(--radius-sm);font:var(--type-caption)}
.jr-legacy .lc-item .ic{width:24px;height:24px;border-radius:var(--radius-sm);background:var(--paper-deep);display:grid;place-items:center;color:var(--ink);flex:none}
.jr-legacy .lc-item.done .ic{background:var(--ok-wash);color:var(--ok)}
.jr-legacy .lc-item.done::after{content:"Fait";margin-left:auto;font:var(--type-label);color:var(--ok)}
.jr-legacy .lc-item.active{font-weight:600}
.jr-legacy .lc-item.active::after{content:"En cours";margin-left:auto;font:var(--type-label)}
.jr-legacy .spinner{width:16px;height:16px;border:2px solid var(--paper-deep);border-top-color:var(--action);border-radius:50%;animation:jrspin 800ms linear infinite}
@keyframes jrspin{to{transform:rotate(360deg)}}

/* Résultats */
.jr-legacy .results-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,360px),1fr));gap:var(--space-5);margin-bottom:var(--space-5)}
.jr-legacy .total-card{background:var(--ink);color:var(--paper);border-radius:var(--radius-md);padding:var(--space-6)}
.jr-legacy .total-card .lbl{font:var(--type-label)}
.jr-legacy .total-card .val{font:var(--type-amount);font-variant-numeric:tabular-nums;color:var(--accent-on-dark);margin:var(--space-2) 0}
.jr-legacy .total-card .sub{font:var(--type-caption)}
.jr-legacy .total-card .breakdown{display:flex;flex-direction:column;margin-top:var(--space-5)}
.jr-legacy .total-card .br-row{display:flex;justify-content:space-between;gap:var(--space-4);font:var(--type-caption);padding:var(--space-3) 0;border-top:1px solid var(--action)}
.jr-legacy .total-card .br-row>span:last-child{font-weight:700;font-variant-numeric:tabular-nums;white-space:nowrap}
.jr-legacy .total-card .br-row em{opacity:1!important;font-size:var(--fs-caption)!important}
.jr-legacy .blur{filter:none!important;user-select:auto!important}
.jr-legacy .dpe-card{background:var(--card);border:1px solid var(--line);border-radius:var(--radius-md);padding:var(--space-5)}
.jr-legacy .dpe-card .dpe-h{font:var(--type-h3);margin:0 0 var(--space-4)}
.jr-legacy .dpe-bars{display:flex;flex-direction:column;gap:var(--space-2)}
.jr-legacy .dpe-bar{display:grid;grid-template-columns:28px minmax(0,1fr) 112px;gap:var(--space-3);align-items:center;font:var(--type-caption);font-variant-numeric:tabular-nums;padding:2px;border-radius:var(--radius-sm)}
.jr-legacy .dpe-letter{width:28px;height:28px;border-radius:var(--radius-sm);display:grid;place-items:center;font:var(--fw-bold) 17px/1 var(--font-text);background:var(--ink)!important;color:var(--paper)!important}
.jr-legacy .dpe-bar .lvl{height:12px;border-radius:var(--radius-sm);background:var(--paper-deep)!important}
.jr-legacy .dpe-bar .kwh{text-align:right}
.jr-legacy .dpe-bar.from{outline:2px solid var(--ink);outline-offset:2px}
.jr-legacy .dpe-bar.from .lvl{background:var(--ink)!important}
.jr-legacy .dpe-bar.from .kwh::after{content:" · actuel";font-weight:700}
.jr-legacy .dpe-bar.to{outline:2px solid var(--action);outline-offset:2px}
.jr-legacy .dpe-bar.to .lvl{background:var(--action)!important}
.jr-legacy .dpe-bar.to .kwh::after{content:" · projeté";font-weight:700}
.jr-legacy .dpe-arrow{margin:var(--space-4) 0 0}
.jr-legacy .projet-unique{background:var(--card);border:1px solid var(--line);border-radius:var(--radius-md);padding:var(--space-6);margin:var(--space-5) 0}
.jr-legacy .projet-eyebrow{font:var(--type-label);margin-bottom:var(--space-2)}
.jr-legacy .projet-titre{font:var(--type-h2);margin:0 0 var(--space-2)}
.jr-legacy .projet-intro{font:var(--type-body);margin:0 0 var(--space-5)}
.jr-legacy .projet-travaux{margin-bottom:var(--space-5);padding:var(--space-4);background:var(--paper);border-radius:var(--radius-sm)}
.jr-legacy .projet-travaux-titre{font:var(--type-label);margin-bottom:var(--space-3)}
.jr-legacy .projet-travaux ul{list-style:none;padding:0;margin:0;display:flex;flex-wrap:wrap;gap:var(--space-2)}
.jr-legacy .projet-travaux li{padding:var(--space-1) var(--space-3);background:var(--card);border:1px solid var(--line-strong);border-radius:var(--radius-sm);font:var(--type-caption)}
.jr-legacy .projet-chiffres{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:var(--space-3);margin-bottom:var(--space-5)}
@media (max-width:720px){.jr-legacy .projet-chiffres{grid-template-columns:minmax(0,1fr)}.jr-legacy .projet-unique{padding:var(--space-5) var(--space-4)}}
.jr-legacy .projet-chiffre{padding:var(--space-4);background:var(--paper);border-radius:var(--radius-sm);display:flex;flex-direction:column;gap:var(--space-1)}
.jr-legacy .projet-chiffre-label{font:var(--type-label)}
.jr-legacy .projet-chiffre-valeur{font:italic var(--fw-heavy) 32px/36px var(--font-text);font-variant-numeric:tabular-nums}
.jr-legacy .projet-chiffre-sub{font:var(--type-caption)}
.jr-legacy .projet-chiffre-highlight{background:var(--ink);color:var(--paper)}
.jr-legacy .projet-chiffre-highlight .projet-chiffre-valeur{color:var(--accent-on-dark)}
.jr-legacy .projet-dpe{display:flex;align-items:center;gap:var(--space-4);padding:var(--space-4);background:var(--paper);border-radius:var(--radius-sm);flex-wrap:wrap}
.jr-legacy .projet-dpe-avant,.jr-legacy .projet-dpe-apres{display:flex;align-items:center;gap:var(--space-3)}
.jr-legacy .projet-dpe-label{font:var(--type-label)}
.jr-legacy .projet-dpe-badge{display:inline-grid;place-items:center;min-width:44px;min-height:44px;border-radius:var(--radius-sm);font:var(--fw-bold) 22px/1 var(--font-text);color:var(--paper);background:var(--ink)}
.jr-legacy .projet-dpe-badge-apres{background:var(--action);color:var(--card)}
.jr-legacy .projet-dpe-arrow{font:var(--type-h3)}

/* Appel à continuer (sur encre) */
.jr-legacy .rf-cta-scen{margin:var(--space-6) 0 var(--space-5);padding:var(--space-6);background:var(--ink);color:var(--paper);border-radius:var(--radius-md)}
.jr-legacy .rf-cta-scen__eyebrow{font:var(--type-label);color:var(--accent-on-dark);margin:0 0 var(--space-2)}
.jr-legacy .rf-cta-scen__title{font:var(--type-hook);margin:0 0 var(--space-3)}
.jr-legacy .rf-cta-scen__title strong{color:var(--accent-on-dark);font-variant-numeric:tabular-nums}
.jr-legacy .rf-cta-scen__sub{font:var(--type-body);margin:0 0 var(--space-5);max-width:var(--measure)}
.jr-legacy .rf-cta-scen__btn{background:var(--accent-on-dark);color:var(--ink);min-height:56px;font-size:var(--fs-lead)}
.jr-legacy .rf-cta-scen__btn:hover{background:var(--paper)}
.jr-legacy .rf-cta-scen__btn:focus-visible{outline-color:var(--focus-ring-on-dark)!important}
.jr-legacy .rf-cta-scen__reassure{display:flex;flex-wrap:wrap;gap:var(--space-2) var(--space-3);margin:var(--space-4) 0 0;font:var(--type-caption)}
.jr-legacy .lock-cta{display:flex;flex-wrap:wrap;align-items:center;gap:var(--space-4);padding:var(--space-5);background:var(--card);border:1px solid var(--line);border-radius:var(--radius-md);margin-top:var(--space-5)}
.jr-legacy .lock-cta .ic{display:flex;flex:none}
.jr-legacy .lock-cta .txt{flex:1 1 280px}
.jr-legacy .lock-cta .h{font:var(--type-label)}
.jr-legacy .lock-cta .s{font:var(--type-caption)}

/* Réassurance */
.jr-legacy .rf-reassure{margin:var(--space-7) 0 var(--space-5);padding:var(--space-6);background:var(--paper-deep);border-radius:var(--radius-md)}
.jr-legacy .rf-reassure__head{max-width:var(--measure);margin:0 0 var(--space-5)}
.jr-legacy .rf-reassure__title{font:var(--type-h2);margin:0 0 var(--space-2)}
.jr-legacy .rf-reassure__lede{font:var(--type-body);margin:0}
.jr-legacy .rf-reassure__benefits{list-style:none;padding:0;margin:0 0 var(--space-5);display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,200px),1fr));gap:var(--space-3)}
.jr-legacy .rf-reassure__benefit{display:flex;gap:var(--space-3);align-items:flex-start;padding:var(--space-4);background:var(--card);border:1px solid var(--line);border-radius:var(--radius-md)}
.jr-legacy .rf-reassure__benefit-icon{display:flex;flex:none}
.jr-legacy .rf-reassure__benefit>div{display:flex;flex-direction:column;gap:2px}
.jr-legacy .rf-reassure__benefit strong{font:var(--type-label)}
.jr-legacy .rf-reassure__benefit span:not(.rf-reassure__benefit-icon){font:var(--type-caption)}
.jr-legacy .rf-aides,.jr-legacy .rf-reassure__faq,.jr-legacy .rf-compare{background:var(--card);border:1px solid var(--line);border-radius:var(--radius-md);margin-bottom:var(--space-4);overflow:hidden}
.jr-legacy details>summary{cursor:pointer;list-style:none;display:flex;flex-wrap:wrap;align-items:center;gap:var(--space-2);min-height:var(--hit-min);padding:var(--space-3) 120px var(--space-3) var(--space-5);font:var(--type-label);color:var(--ink);position:relative}
.jr-legacy details>summary::-webkit-details-marker{display:none}
.jr-legacy details>summary::after{content:"Afficher";position:absolute;right:var(--space-5);top:50%;transform:translateY(-50%);font:var(--type-label);color:var(--action);text-decoration:underline;text-underline-offset:3px}
.jr-legacy details[open]>summary::after{content:"Masquer"}
.jr-legacy .rf-aides__summary-hint{font:var(--type-caption)}
.jr-legacy .rf-aides__body{padding:0 var(--space-5) var(--space-5);border-top:1px solid var(--line);overflow-x:auto}
.jr-legacy table{width:100%;border-collapse:collapse;font:var(--type-caption)}
.jr-legacy th,.jr-legacy td{padding:var(--space-3);text-align:left;border-bottom:1px solid var(--line);vertical-align:top}
.jr-legacy thead th{font:var(--type-label);background:var(--paper);border-bottom:1px solid var(--line-strong)}
.jr-legacy .rf-aides__row-region td{background:var(--paper-deep);font:var(--type-label)}
.jr-legacy .rf-reassure__faq{padding:0}
.jr-legacy .rf-reassure__faq details{border-bottom:1px solid var(--line)}
.jr-legacy .rf-reassure__faq details:last-child{border-bottom:0}
.jr-legacy .rf-reassure__faq p{margin:0;padding:0 var(--space-5) var(--space-4);font:var(--type-caption)}

/* Transmission */
.jr-legacy .rf-hero-roi{margin:var(--space-5) 0;background:var(--ink);color:var(--paper);border-radius:var(--radius-md);overflow:hidden}
.jr-legacy .rf-hero-roi__main{padding:var(--space-6)}
.jr-legacy .rf-hero-roi__label{font:var(--type-label);margin-bottom:var(--space-2)}
.jr-legacy .rf-hero-roi__amount{font:italic var(--fw-heavy) clamp(44px,8vw,56px)/1.05 var(--font-text);color:var(--accent-on-dark);font-variant-numeric:tabular-nums;margin-bottom:var(--space-2)}
.jr-legacy .rf-hero-roi__sub{font:var(--type-caption)}
.jr-legacy .rf-tx{display:flex;flex-direction:column;gap:var(--space-4)}
.jr-legacy .rf-tx__card,.jr-legacy .signup,.jr-legacy .rf-tx-success{background:var(--card);border:1px solid var(--line);border-radius:var(--radius-md);padding:var(--space-6)}
@media (max-width:640px){.jr-legacy .rf-tx__card,.jr-legacy .signup,.jr-legacy .rf-tx-success{padding:var(--space-5) var(--space-4)}}
.jr-legacy .rf-tx__card h3,.jr-legacy .signup h3,.jr-legacy .rf-tx-success h3{font:var(--type-h2);margin:0 0 var(--space-3)}
.jr-legacy .rf-tx__rows{margin:0;display:flex;flex-direction:column}
.jr-legacy .rf-tx__row{display:grid;grid-template-columns:minmax(120px,200px) minmax(0,1fr);gap:var(--space-4);padding:var(--space-3) 0;border-top:1px solid var(--line)}
