.jr-legacy .rf-tx__free{padding:var(--space-5);background:var(--card);border:2px solid var(--action);border-radius:var(--radius-md);display:flex;flex-direction:column;gap:var(--space-2)}
.jr-legacy .rf-tx__free>strong{font:var(--type-hook)}
.jr-legacy .rf-tx__free p{margin:0;font:var(--type-body)}
.jr-legacy .rf-tx__aval{font:var(--type-caption);margin:0}
.jr-legacy .signup .sub{font:var(--type-body);margin:0 0 var(--space-5)}
.jr-legacy .signup .legal,.jr-legacy .rf-tx__consent{display:flex;align-items:flex-start;gap:var(--space-3);font:var(--type-caption);margin:0 0 var(--space-4);cursor:pointer}
.jr-legacy .rf-tx__submit{width:100%;margin-top:var(--space-2)}
.jr-legacy .rf-tx__foot{font:var(--type-caption);margin:var(--space-3) 0 0}
.jr-legacy .rf-tx-success{display:none;border:2px solid var(--ok)}
