const KEY = 'junglerenov.profile';
const ALT = 'junglerenov.profile';
function getDossier(){
  try {
    const a = JSON.parse(localStorage.getItem(KEY) || 'null');
    const b = JSON.parse(localStorage.getItem(ALT) || 'null');
    return a || b || null;
  } catch { return null; }
}

