});
document.querySelectorAll('.checkbox input').forEach(c => c.addEventListener('change', () => {
  if (!resultsVisible()) return;
  clearTimeout(_distDebounce);
  _distDebounce = setTimeout(fetchArtisansRge, 300);
}));
const addrInput = document.getElementById('client-addr');
if (addrInput){
  let _addrDebounce = null;
  addrInput.addEventListener('input', () => {
    _coordsCacheKey = null; _coordsCache = null;
    if (!resultsVisible()) return;
    clearTimeout(_addrDebounce);
    _addrDebounce = setTimeout(fetchArtisansRge, 600);
  });
}

