/* JungleRenov — rehydratation profil depuis la base clients.
   Si l'utilisateur est connecté en tant que client mais que `junglerenov.profile`
   est vide ou ne contient plus les aides, on reconstitue le profil à partir
   de l'entrée correspondante dans `junglerenov.clients`. Sécurité contre les
   écrasements accidentels de la simulation en local. S'exécute AVANT le bind()
   défensif principal. */
(function(){
  function rehydrate(){
    try {
      const session = JSON.parse(localStorage.getItem('junglerenov.session') || 'null');
      if (!session || session.role !== 'client') return;
      const profile = JSON.parse(localStorage.getItem('junglerenov.profile') || '{}');
      const hasAids = !!(profile.aids && profile.aids.totalAides > 0);
      if (hasAids) return;
      const clients = JSON.parse(localStorage.getItem('junglerenov.clients') || '[]');
      const me = clients.find(c => c.email && session.email && c.email.toLowerCase() === session.email.toLowerCase());
      if (!me || !me.aids || !(me.aids.totalAides > 0)) return;
      const merged = {
        ...profile,
        firstname: profile.firstname || me.firstname,
        lastname:  profile.lastname  || me.lastname,
        email:     profile.email     || me.email,
        tier:      profile.tier      || me.tier,
        address:   profile.address   || me.address,
        logement:  profile.logement  || me.logement,
        situation: profile.situation || me.situation,
        foyer:     profile.foyer     || me.foyer,
        aids:      me.aids,
          diagnostiqueLe: profile.diagnostiqueLe || me.diagnostiqueLe,
      };
      localStorage.setItem('junglerenov.profile', JSON.stringify(merged));
    } catch(e){ console.warn('Rehydrate profile :', e); }
  }
  rehydrate();
})();

