/* JungleRenov — liste des dossiers actifs (multi-dossiers) */
(function(){
  // Retour de transmission : le brouillon déposé pendant le tunnel est consigné.
  var dossierCible = null;
  try {
    var qp = new URLSearchParams(location.search);
    if (window.RFDossiers && qp.get('transmis') === '1'){
      RFDossiers.settleDossierEnAttente({ consentement: true });
    }
    dossierCible = qp.get('dossier');
  } catch(e){}

  /* Confirmation d'arrivée après création d'un dossier. */
  function showToast(msg){
    var t = document.createElement('div');
    t.setAttribute('role', 'status');
    t.style.cssText = 'position:fixed;top:24px;right:24px;z-index:2147483000;max-width:340px;padding:14px 18px;'
      + 'background:var(--teal-800);color:#FFFFFF;border-radius:6px;box-shadow:none;'
      + 'font:600 17px var(--font-sans);line-height:1.45;opacity:0;transform:translateY(-6px);'
      + 'transition:opacity .25s ease,transform .25s ease';
    t.textContent = msg;
    document.body.appendChild(t);
    requestAnimationFrame(function(){ t.style.opacity = '1'; t.style.transform = 'translateY(0)'; });
    setTimeout(function(){ t.style.opacity = '0'; t.style.transform = 'translateY(-6px)'; }, 4200);
    setTimeout(function(){ t.remove(); }, 4700);
  }
  var host  = document.getElementById('dossiers-liste');
  var empty = document.getElementById('dossiers-empty');
  if (!host || !window.RFDossiers) return;
  var dossiers = RFDossiers.getActifs();
  if (!dossiers.length){
    host.hidden = true;
    if (empty) empty.hidden = false;
    return;
  }
  if (empty) empty.hidden = true;
  var TYPE_SHORT = { energetique: 'Énergétique', autonomie: 'MPA', indigne: 'LHI' };
  var escHtml = function(s){ return String(s == null ? '' : s).replace(/[&<>"]/g, function(c){ return ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'})[c]; }); };
  host.innerHTML = dossiers.map(function(dos){
    var m = RFDossiers.meta(dos.type);
    var total = (window.rfTotalDossier && window.rfTotalDossier(dos)) || RFDossiers.totalAides(dos) || 0;
    var tl = RFDossiers.getTimeline(dos);
    var idx = RFDossiers.getCurrentStepIndex ? RFDossiers.getCurrentStepIndex(dos) : 0;
    var step = tl[idx];
    var pct = Math.round((idx / tl.length) * 100);
    var docs = (RFDossiers.getDocumentsAttendus(dos) || []).length;
    var adr = (dos.profile && dos.profile.logement && dos.profile.logement.adresse) || '';
    var adrCourte = adr.length > 60 ? adr.slice(0, 57) + '…' : adr;
    return '<article class="rf-dcard rf-dcard--' + dos.type + '" data-dossier-id="' + escHtml(dos.id) + '">' +
      '<div class="rf-dcard__head">' +
        '<span class="rf-dcard__badge">' + (TYPE_SHORT[dos.type] || m.court) + '</span>' +
        '<span class="rf-dcard__status">' + (window.RFTransmission ? RFTransmission.libelleStatut(dos.statutDossier) : 'Dossier créé') + ' · ' + pct + ' %</span>' +
      '</div>' +
      (adrCourte ? '<div class="rf-dcard__adresse"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M20 10c0 6-8 12-8 12s-8-6-8-12a8 8 0 0 1 16 0Z"/><circle cx="12" cy="10" r="3"/></svg><span>' + escHtml(adrCourte) + '</span></div>' : '') +
      '<div class="rf-dcard__bar"><span style="width:' + pct + '%"></span></div>' +
      '<div class="rf-dcard__bar-meta"><span>' + idx + ' / ' + tl.length + ' étapes</span><span>' + ((dos.partenaire && dos.partenaire.nom) ? escHtml(dos.partenaire.nom) : 'Créé le ' + RFDossiers.fmtDate(dos.transmisLe)) + '</span></div>' +
      (step && idx < tl.length - 1 ? '<div class="rf-dcard__next">' +
        '<div class="rf-dcard__next-label">Prochaine action' + (step.delai ? ' · sous ' + escHtml(step.delai) : '') + '</div>' +
        '<div class="rf-dcard__next-title">' + escHtml(step.libelle) + '</div>' +
      '</div>' : '') +
      '<div class="rf-dcard__stats">' +
        '<div class="rf-dcard__stat"><div class="rf-dcard__stat-label">Aides estimées</div><div class="rf-dcard__stat-value">' + Math.round(total).toLocaleString('fr-FR') + ' €</div></div>' +
        '<div class="rf-dcard__stat"><div class="rf-dcard__stat-label">Documents à fournir</div><div class="rf-dcard__stat-value">' + docs + '</div></div>' +
      '</div>' +
      '<a class="rf-dcard__cta" href="' + m.detail + '?dossier=' + encodeURIComponent(dos.id) + '">Ouvrir mon dossier</a>' +
    '</article>';
  }).join('');

  // Met en avant le dossier tout juste créé
  if (dossierCible){
    var card = host.querySelector('[data-dossier-id="' + dossierCible + '"]');
    if (card){
      card.style.boxShadow = '0 0 0 2px var(--teal-700)';
      showToast('Votre dossier a été créé. Vous le retrouvez ci-dessous, suivi pendant 12 mois.');
    }
  }
})();

