/* Cockpit dashboard — KPI globaux et actions urgentes consolidées sur tous les dossiers. */
(function initDashboardCockpit(){
  'use strict';
  if (!window.RFDossiers) return;
  var esc = function(s){ return String(s == null ? '' : s).replace(/[&<>"]/g, function(c){ return ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'})[c]; }); };
  var setTxt = function(id, v){ var el = document.getElementById(id); if (el) el.textContent = v; };
  var eur = function(n){ return Math.round(Number(n) || 0).toLocaleString('fr-FR') + ' €'; };
  var jours = function(delai){ var mm = /(\d+)/.exec(delai || ''); return mm ? parseInt(mm[1], 10) : null; };

  var greetEl = document.getElementById('rf-dash-greeting');
  if (greetEl && window.RFUser) greetEl.textContent = RFUser.getGreeting();

  var actifs = (RFDossiers.getActifs && RFDossiers.getActifs()) || [];
  var totalAides = 0, sommePct = 0, etapesFaites = 0, docs = 0, urgent = [];

  actifs.forEach(function(dos){
    totalAides += (window.rfTotalDossier && window.rfTotalDossier(dos)) || RFDossiers.totalAides(dos) || 0;
    var tl = RFDossiers.getTimeline(dos);
    var idx = RFDossiers.getCurrentStepIndex(dos);
    sommePct += Math.round((idx / tl.length) * 100);
    etapesFaites += idx;
    docs += (RFDossiers.getDocumentsAttendus(dos) || []).length;
    var step = tl[idx];
    if (step && step.delai) urgent.push({ dos: dos, step: step, j: jours(step.delai) });
  });

  setTxt('rf-dash-total-aides', actifs.length ? eur(totalAides) : '—');
  setTxt('rf-dash-total-count', actifs.length + (actifs.length > 1 ? ' dossiers actifs' : ' dossier actif'));
  setTxt('rf-dash-avg-progress', actifs.length ? Math.round(sommePct / actifs.length) + ' %' : '—');
  setTxt('rf-dash-avg-detail', etapesFaites + (etapesFaites > 1 ? ' étapes complétées' : ' étape complétée'));
  setTxt('rf-dash-docs-count', docs || '—');

  urgent.sort(function(a, b){ return (a.j == null ? 999 : a.j) - (b.j == null ? 999 : b.j); });
  if (urgent.length){
    setTxt('rf-dash-next-deadline', urgent[0].j != null ? urgent[0].j + ' j' : '—');
    setTxt('rf-dash-next-action', urgent[0].step.court || urgent[0].step.libelle);
  } else {
    setTxt('rf-dash-next-deadline', '—');
    setTxt('rf-dash-next-action', actifs.length ? 'Aucune échéance' : 'Aucun dossier');
  }

  var section = document.getElementById('rf-dash-urgent');
  var list = document.getElementById('rf-urgent-list');
  if (section && list && urgent.length){
    section.hidden = false;
    setTxt('rf-urgent-count', urgent.length + (urgent.length > 1 ? ' actions' : ' action'));
    var SHORT = { energetique: 'Énergétique', autonomie: 'MPA', indigne: 'LHI' };
    list.innerHTML = urgent.map(function(u){
      var adr = (u.dos.profile && u.dos.profile.logement && u.dos.profile.logement.adresse) || '';
      var href = u.step.href || ('mes-aides.dc.html?dossier=' + encodeURIComponent(u.dos.id));
      var ext = /^https?:/.test(href) ? ' target="_blank" rel="noopener"' : '';
      return '<div class="rf-urgent">' +
        '<span class="rf-urgent__type rf-urgent__type--' + u.dos.type + '">' + (SHORT[u.dos.type] || u.dos.type) + '</span>' +
        '<div><div class="rf-urgent__title">' + esc(u.step.libelle) + '</div>' +
        '<div class="rf-urgent__meta">Sous ' + esc(u.step.delai) + (adr ? ' · ' + esc(adr) : '') + '</div></div>' +
        '<a class="rf-urgent__cta" href="' + esc(href) + '"' + ext + '>' + esc(u.step.cta || 'Voir le dossier') + '</a>' +
      '</div>';
    }).join('');
  }
})();

