(function(){
  /* Date des BARÈMES, écrite en dur et alignée sur RFCompute.REFERENTIEL
     (version 2026-09-01). L'ancien new Date() affichait la date de la visite :
     la page se déclarait toujours « à jour », quelle que soit la réalité. */
  var dateBaremes = '1er septembre 2026';
  var m2 = document.getElementById('maj-date-2');
  if (m2) m2.textContent = dateBaremes;

  var cards = Array.prototype.slice.call(document.querySelectorAll('details.aide'));
  var toggle = document.getElementById('toggle-all');
  toggle.addEventListener('click', function(){
    var open = cards.some(function(c){ return !c.open; });
    cards.forEach(function(c){ if(!c.hidden) c.open = open; });
    toggle.textContent = open ? 'Tout replier' : 'Tout déplier';
  });

  var q = document.getElementById('q');
  var none = document.getElementById('no-result');
  function norm(s){ return s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,''); }
  cards.forEach(function(c){ c.dataset.text = norm(c.textContent); });
  function filter(){
    var v = norm(q.value.trim());
    var hits = 0;
    cards.forEach(function(c){
      var hit = !v || c.dataset.text.indexOf(v) !== -1;
      c.hidden = !hit;
      if (hit) hits++;
      if (v && hit) c.open = true;
    });
    document.querySelectorAll('h2.sec, .sec-lede').forEach(function(el){
      if (!v) { el.hidden = false; return; }
      var n = el.nextElementSibling, visible = false;
      while (n && !/^H2$/.test(n.tagName)) { if (n.classList.contains('aide') && !n.hidden) { visible = true; break; } n = n.nextElementSibling; }
      if (el.id === 'contacts' || el.id === 'sources') visible = true;
      el.hidden = !visible;
    });
    none.style.display = (v && hits === 0) ? 'block' : 'none';
  }
  q.addEventListener('input', filter);
  document.getElementById('q-clear').addEventListener('click', function(){ q.value=''; filter(); q.focus(); });

  var links = Array.prototype.slice.call(document.querySelectorAll('aside.toc a[href^="#"]'));
  var targets = links.map(function(a){ return document.getElementById(a.getAttribute('href').slice(1)); });
  window.addEventListener('scroll', function(){
    var y = window.scrollY + 120, cur = 0;
    targets.forEach(function(t, i){ if (t && t.offsetTop <= y) cur = i; });
    links.forEach(function(a, i){ a.classList.toggle('active', i === cur); });
  }, {passive:true});

  if (location.hash) { var el = document.querySelector(location.hash); if (el && el.tagName === 'DETAILS') el.open = true; }
})();

