/* JungleRenov — bindings sidebar canonique (lit junglerenov.profile écrit par la simulation) */
(function(){
  const KEY = 'junglerenov.profile';
  function readData(){
    try { return JSON.parse(localStorage.getItem(KEY) || '{}'); }
    catch { return {}; }
  }
  function fmtEUR(n){
    if (n == null || isNaN(n)) return '—';
    return new Intl.NumberFormat('fr-FR').format(Math.round(n)) + ' €';
  }
  function refresh(){
    const d = readData();
    const aids = (window.rfAidsCourantes && window.rfAidsCourantes()) || d.aids || {};
    const trav = aids.travaux || {};

    // Widget aides estimées
    const valEl = document.getElementById('rf-aides-val');
    const subEl = document.getElementById('rf-aides-sub');
    let total = aids.totalAides || aids.total || null;
    let projet = trav.totalTTC || aids.coutTotalTTC || null;
    // Le profil peut être vide alors qu'un dossier transmis existe : on retombe sur
    // le résultat résolu du dernier dossier actif plutôt que d'afficher « — ».
    if (!total && window.RFDossiers && window.rfResolveDossierResult){
      try {
        const actifs = RFDossiers.getActifs();
        const last = actifs.length ? actifs[actifs.length - 1] : null;
        const rr = last ? window.rfResolveDossierResult(last) : null;
        if (rr){
          total = (window.rfTotalDossier ? window.rfTotalDossier(last, rr) : 0)
            || rr.totalAides || (rr.aide && (rr.aide.totalApresEcretement || rr.aide.total)) || null;
          var tt = rr.travaux || {};
          var htStocke = tt.coutEstime || tt.coutHT || 0;
          projet = tt.totalTTC || (htStocke ? Math.round(htStocke * 1.055) : projet);
        }
      } catch (e) { console.warn('[mes-aides] widget sidebar :', e); }
    }
    if (valEl){
      if (total){
        valEl.textContent = fmtEUR(total);
        if (subEl) subEl.textContent = projet ? 'sur ' + fmtEUR(projet) + ' TTC' : 'Estimation indicative';
      } else {
        valEl.textContent = '—';
        if (subEl) subEl.textContent = 'Simulation à compléter';
      }
    }

    // Profil utilisateur en bas
    const nameEl = document.getElementById('rf-me-name');
    const planEl = document.getElementById('rf-me-plan');
    const avEl = document.getElementById('rf-me-av');
    const fn = (d.firstname || '').trim();
    const ln = (d.lastname || '').trim();
    const fullName = (fn + ' ' + ln).trim();
    /* Le badge porte le statut du dossier, jamais une formule commerciale. */
    let planTxt = '';
    try {
      const actifs = (window.RFDossiers && RFDossiers.getActifs && RFDossiers.getActifs()) || [];
      if (actifs.length){
        const dernier = actifs[actifs.length - 1];
        const statut = (window.RFTransmission && RFTransmission.libelleStatut(dernier.statutDossier)) || 'Dossier créé';
        const nomPart = dernier.partenaire && dernier.partenaire.nom;
        planTxt = nomPart ? statut + ' · ' + nomPart : statut;
      } else {
        planTxt = 'Diagnostic en cours';
      }
    } catch (e) { planTxt = ''; }
    if (nameEl) nameEl.textContent = fullName || 'Mon compte';
    if (planEl) planEl.textContent = planTxt || '—';
    if (avEl){
      if (fullName){
        const initials = ((fn[0]||'') + (ln[0]||'')).toUpperCase() || 'RF';
        avEl.textContent = initials;
      } else {
        avEl.textContent = 'RF';
      }
    }
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', refresh);
  else refresh();
  window.addEventListener('storage', refresh);
})();

pages/mes-aides/04.js:
/* JungleRenov — binding défensif du widget central de mes-aides
   (stk-total, stk-cap, stk-bar, stk-legend, diag-recap-s).
   S'exécute après le bind() natif et corrige les valeurs hardcodées
   (Sophie Marin) avec les vraies données de la simulation utilisateur. */
(function(){
  const KEY = 'junglerenov.profile';
  function readData(){
    try { return JSON.parse(localStorage.getItem(KEY) || '{}'); }
    catch { return {}; }
  }
  function fmtEUR(n){
    if (n == null || isNaN(n)) return '—';
    return new Intl.NumberFormat('fr-FR').format(Math.round(n)) + ' €';
  }
  function setText(id, v){ const el = document.getElementById(id); if (el) el.textContent = v; }

  function refresh(){
    try {
      const d = readData();
      const aids = (window.rfAidsCourantes && window.rfAidsCourantes()) || d.aids || {};
      const aides = aids.aides || {};
      const trav = aids.travaux || {};
      const total = aids.totalAides || aids.total || 0;
      const projet = trav.totalTTC || aids.coutTotalTTC || 0;
      /* Mises en garde du moteur (gestes hors parcours, audit manquant, fourchette
         CEE, copropriété estimée…) et version des barèmes. Rendues AVANT le test
         du total : un total nul a justement besoin de son explication. */
      if (window.RFAlertes){
        try {
          RFAlertes.rendre(aids, 'rf-alertes');
          let pied = document.getElementById('rf-referentiel');
          if (!pied){
            pied = document.createElement('div');
            pied.id = 'rf-referentiel';
            const hote = document.getElementById('stk-hors') || document.getElementById('stk-legend');
            if (hote && hote.parentNode) hote.parentNode.appendChild(pied);
          }
          RFAlertes.rendreReferentiel(aids, pied);
        } catch (e) { console.warn('Alertes :', e); }
      }
      const aDesAlertes = !!(aids.alertes && aids.alertes.gestesHorsParcoursGeste && aids.alertes.gestesHorsParcoursGeste.length);
      if (total <= 0 && !aDesAlertes) return; // pas de données, on laisse « — »

      // Grand chiffre central
      setText('stk-total', fmtEUR(total));

      // Caption "soit X % de couverture"
      const stkCap = document.getElementById('stk-cap');      if (stkCap){
        const pct = projet > 0 ? Math.round(100 * total / projet) : 0;
        // L'éco-PTZ est un PRÊT : il n'entre jamais dans le total des aides.
        stkCap.innerHTML = projet > 0
          ? `soit <b>${pct} % de couverture</b> de votre projet de ${fmtEUR(projet)} TTC. Cumul MaPrimeRénov' + CEE + aides locales et régionales.`
          : "Cumul MaPrimeRénov' + CEE + aides locales et régionales.";
      }

      // Décomposition par dispositif
      const mpr   = (aides.mpr   && aides.mpr.total)   || 0;
      const cee   = (aides.cee   && aides.cee.total)   || 0;
      const local = (aides.local && aides.local.total) || 0;
      const tva   = (aides.tva   && aides.tva.total)   || 0;
      /* `geTotal` et non `ge` : la variable `ge` est déjà déclarée plus bas
         dans cette même fonction pour le bloc Grand Est. */
      const geTotal = (aides.grandEst && aides.grandEst.total) || 0;
      const accomp  = (aids.accompagnement && aids.accompagnement.priseEnCharge) || 0;
      const upd = (key, val) => {
        const el = document.querySelector(`[data-leg="${key}"]`);
        if (el) el.textContent = fmtEUR(val);
      };
      upd('mpr', mpr);
      /* CEE : une fourchette, jamais un montant — il dépend de l'organisme. */
      (function(){
        const c = aides.cee || {};
        const el = document.querySelector('[data-leg="cee"]');
        if (el && c.unique === false && c.max > c.min) el.textContent = fmtEUR(c.min) + ' à ' + fmtEUR(c.max);
        else upd('cee', cee);
      })();
      upd('local', local);
      upd('grandEst', geTotal);
      /* Quote-part copropriété : dans le total, donc dans la légende quand elle existe. */
      const coproQP = Number(aids.coproQuotePart) || 0;
      upd('copro', coproQP);
      const coproRow = document.getElementById('stk-copro-row');
      if (coproRow) coproRow.style.display = coproQP > 0 ? '' : 'none';
      upd('tva', tva);
      upd('accompagnement', accomp);
      // La ligne accompagnement n'a de sens qu'en rénovation d'ampleur.
      const accompRow = document.getElementById('stk-accomp-row');
      if (accompRow) accompRow.style.display = accomp > 0 ? '' : 'none';

      // Badge "Rénovation d'ampleur détectée"
      if (aides.mpr && aides.mpr.isRenovAmpleur){
        const badge = document.getElementById('ampleur-badge');
        if (badge) badge.style.display = 'block';
      }

      // Focus Grand Est + aides régionales cumulatives
      const ge = aides.grandEst;
      if (ge && ge.isGrandEst){
        const banner = document.getElementById('grand-est-banner');
        if (banner) banner.style.display = 'flex';
      }
      const geSection = document.getElementById('grand-est-aides');
      const geList    = document.getElementById('grand-est-list');
      if (geSection && geList && ge && Array.isArray(ge.detail) && ge.detail.length > 0){
        geSection.style.display = 'block';
        geList.innerHTML = ge.detail.map(a => `
          <div style="background:#FFFFFF;border:1px solid var(--border);border-radius:6px;padding:16px 20px;display:flex;justify-content:space-between;align-items:flex-start;gap:14px">
            <div style="flex:1">
              <div style="font-weight:600;font-size:17px;color:var(--slate-900)">${a.nom}</div>
              <div style="font-size:17px;color:var(--slate-500);margin-top:4px">${a.note}</div>
            </div>
            <div style="font:700 20px var(--font-mono);color:var(--teal-700);white-space:nowrap">${Math.round(a.montant).toLocaleString('fr-FR')} €</div>
          </div>`).join('');
      }

      /* Barre de répartition : sur les aides RÉELLEMENT VERSÉES, économie de
         TVA exclue — elle ne finance rien, elle réduit la facture. Les quatre
         segments recomposent donc `totalAides`. */
      const sumAids = mpr + cee + local + geTotal + (Number(aids.coproQuotePart) || 0);
      if (sumAids > 0){
        const pct = (n) => Math.round(100 * n / sumAids);
        const bars = document.querySelectorAll('#stk-bar > i');
        if (bars[0]) bars[0].style.width = pct(mpr) + '%';
        if (bars[1]) bars[1].style.width = pct(cee) + '%';
        if (bars[2]) bars[2].style.width = pct(local) + '%';
        if (bars[3]) bars[3].style.width = pct(geTotal) + '%';
        const barEl = document.getElementById('stk-bar');
        if (barEl) barEl.setAttribute('aria-label',
          "Répartition des aides : MaPrimeRénov' " + fmtEUR(mpr)
          + ', CEE ' + fmtEUR(cee) + ', aide locale ' + fmtEUR(local)
          + ', aides régionales et métropolitaines ' + fmtEUR(geTotal)
          + ', soit ' + fmtEUR(sumAids) + ' au total.');
      }

      // Récapitulatif logement
      const recap = document.getElementById('diag-recap-s');
      if (recap){
        const log = d.logement || {};
        const ville = (d.address || '').split(',').pop().trim().replace(/^\d{5}\s*/, '') || null;
        const dpe = log.dpe || (d.foyer && d.foyer.dpe) || null;
        const works = [];
        if (trav.combles > 0) works.push('isolation combles');
        if (trav.ite > 0)     works.push('isolation murs');
        if (trav.pac > 0)     works.push('PAC air/eau');
        const parts = [
          log.type,
          log.surface ? log.surface + ' m²' : null,
          log.year ? 'construction ' + log.year : null,
          ville,
          dpe ? 'DPE actuel ' + dpe : null,
          works.length ? 'projet : ' + works.join(' + ') : null,
        ].filter(Boolean);
        if (parts.length) recap.textContent = parts.join(' · ') + '.';
      }
    } catch(e) { console.warn('Refresh mes-aides :', e); }
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', refresh);
  else refresh();
  window.addEventListener('storage', refresh);
})();

pages/mes-aides/05.js:
/* Résultats enregistrés avant la mise à jour des barèmes : un dossier calculé
   sur l'ancien référentiel afficherait un CEE unique et un total périmé. On
   recalcule UNE fois, au chargement, AVANT tout affichage, et on réenregistre
   le résultat dans le profil et dans le dossier — pour que le bandeau, la
   vignette et l'empilement lisent tous le même totalAides. */
(function(){
  var C = window.RFCompute;
  if (!C || !C.REFERENTIEL || typeof C.recomputeFromProfile !== 'function') return;
  var version = C.REFERENTIEL.version, moteur = C.REFERENTIEL.moteur;
  /* Périmé : autre référentiel, OU calculé par une version antérieure du moteur. */
  var perime = function(r){
    return !!r && (!r.referentiel || r.referentiel.version !== version || r.referentiel.moteur !== moteur);
  };
  try {
    var p = JSON.parse(localStorage.getItem('junglerenov.profile') || '{}');
    var aPerime = perime(p.aids);
    var dossiers = (window.RFDossiers && RFDossiers.getAll) ? RFDossiers.getAll() : [];
    // Le résultat d'un dossier peut vivre dans d.result OU dans sa copie d.profile.aids.
    var energetiquesPerimes = dossiers.filter(function(d){
      return d.type === 'energetique' && (perime(d.result) || perime(d.profile && d.profile.aids));
    });
    if (!aPerime && !energetiquesPerimes.length) return;
    var ok = function(r){ return r && r.eligible !== false && r.totalAides >= 0; };
    if (aPerime){
      var fraisProfil = C.recomputeFromProfile();
      if (ok(fraisProfil)){ p.aids = fraisProfil; localStorage.setItem('junglerenov.profile', JSON.stringify(p)); }
    }
    /* Chaque dossier est recalculé sur SON profil, jamais sur le profil courant :
       deux dossiers distincts gardent deux montants distincts. */
    if (energetiquesPerimes.length){
      var all = RFDossiers.loadAll();
      energetiquesPerimes.forEach(function(d){
        var frais = d.profile ? C.recomputeFromProfile(d.profile) : null;
        if (!ok(frais)) return;
        all.forEach(function(x){
          if (x.id !== d.id) return;
          x.result = frais;
          if (x.profile) x.profile.aids = frais;
        });
      });
      RFDossiers.saveAll(all);
    }
  } catch (e) { console.warn('[mes-aides] recalcul du référentiel impossible :', e); }
})();
(function(){
  /* Source UNIQUE des montants de la page : le résultat du dossier affiché,
     à défaut celui du profil. Bandeau, vignette et empilement la lisent tous. */
  window.rfAidsCourantes = function(){
    try {
      var dos = (RFDossiers.resolveFromUrl && RFDossiers.resolveFromUrl()) || null;
      if (dos && dos.result && dos.result.totalAides >= 0) return dos.result;
    } catch (_) {}
    try { return JSON.parse(localStorage.getItem('junglerenov.profile') || '{}').aids || {}; }
    catch (_) { return {}; }
  };
})();

pages/mes-aides/06.js:
/* JungleRenov — synthèse des aides, un bloc par dossier actif.
   Les cartes documentaires ci-dessous restent affichées : elles décrivent les
   dispositifs, indépendamment des dossiers ouverts. */
(function(){
  // Aucun dossier fictif : la page ne montre que ce que l'utilisateur a saisi.
  var sec  = document.getElementById('dos-section');
  var host = document.getElementById('dos-liste');
  if (!sec || !host || !window.RFDossiers) return;
  var dossiers = RFDossiers.getActifs();
  if (!dossiers.length) return;

  var fmt = function(n){ return Math.round(Number(n) || 0).toLocaleString('fr-FR') + ' €'; };
  function line(k, v, cls){
    return '<div class="dos-line' + (cls ? ' ' + cls : '') + '"><span>' + k + '</span><strong>' + fmt(v) + '</strong></div>';
  }

  /* Un dossier transmis peut avoir été stocké sans son résultat (result: null).
     Plutôt que d'afficher un tiret, on recalcule à la volée depuis le profil
     enregistré — c'est le même moteur, les mêmes entrées, donc le même montant. */
  function resolveDossierResult(dos){
    if (!dos) return null;
    var r = dos.result;
    var peuple = r && (r.totalAides > 0 ||
      (r.aide && (r.aide.total > 0 || r.aide.totalApresEcretement > 0)));
    if (peuple) return r;
    var C = window.RFCompute;
    var p = dos.profile;
    if (!C || !p) return null;
    try {
      // Les tunnels MPA et LHI stockent en profil la charge utile du moteur :
      // elle est directement rejouable.
      if (dos.type === 'autonomie' && C.computeMprAdapt) return C.computeMprAdapt(p);
      if (dos.type === 'indigne'   && C.computeMprLogementDecent) return C.computeMprLogementDecent(p);
      if (dos.type === 'energetique'){
        // Le tunnel énergétique stocke un profil riche, pas la charge utile :
        // les aides déjà calculées font foi, sinon on rejoue le moteur.
        if (p.aids && p.aids.totalAides > 0) return p.aids;
        var log = p.logement || {}, foy = p.foyer || {};
        if (C.compute && (p.travaux || []).length){
          return C.compute({
            surface: Number(log.surface) || 0,
            foyer:   Number(foy.parts) || Number(foy.personnes) || 1,
            rfr:     Number(foy.rfr) || 0,
            region:  foy.region || log.region || '',
            heat:    log.chauffage || log.heat || '',
            dept:    log.dept || '',
            selection: p.travaux || [],
          });
        }
      }
      if (p.aids && p.aids.totalAides > 0) return p.aids;
    } catch (e) {
      console.warn('[mes-aides] recalcul impossible pour ' + dos.id + ' :', e);
    }
    return null;
  }
  window.rfResolveDossierResult = resolveDossierResult;
  // Total unique pour la page entière : card dossier, widget sidebar et vue par
  // type doivent afficher le même chiffre.
  window.rfTotalDossier = function(dos, r){ return totalResolu(dos, r || resolveDossierResult(dos)); };

  /* RFDossiers.totalAides() lit dos.result : inutilisable sur un dossier stocké
     sans résultat. On prend le total du résultat résolu, sinon la somme des
     postes réellement affichés — jamais 0 € au-dessus de lignes non nulles. */
  function totalResolu(dos, r){
    if (!r) return 0;
    // LHI et MPA : les services pris en charge par l'Anah, les prêts et les
    // prestations à demander ailleurs ne sont pas des subventions versées.
    if (dos && dos.type === 'indigne') return lhiBreakdown(dos, r).totalDirectes;
    if (dos && dos.type === 'autonomie') return mpaBreakdown(dos, r).totalDirectes;
    if (r.totalAides > 0) return r.totalAides;
    if (r.aide){
      if (r.aide.totalApresEcretement > 0) return r.aide.totalApresEcretement;
      if (r.aide.total > 0) return r.aide.total;
    }
    var A = r.aides || {}, s = 0;
    ['mpr','cee','tva','local','grandEst'].forEach(function(k){
      if (A[k] && A[k].total) s += A[k].total;
    });
    return s;
  }

  function relancerHref(type){
    if (type === 'autonomie') return 'parcours-autonomie.dc.html?fresh=1';
    if (type === 'indigne')   return 'parcours-indigne.dc.html?fresh=1';
    return 'onboarding-diagnostic.dc.html?fresh=1';
  }

  // Traçabilité : savoir en console quels dossiers ont été stockés incomplets.
  dossiers.forEach(function(dos){
    if (dos.result) return;
    if (dos.profile) console.info('[mes-aides] Dossier ' + dos.id + ' sans result — recalcul à la volée depuis le profil');
    else console.warn('[mes-aides] Dossier ' + dos.id + ' sans result ni profil — CTA de reprise proposé');
  });

  /* Un dossier LHI mélange trois natures très différentes. Les confondre gonfle
     faussement le total : seules les subventions versées sont additionnées.
       · aides directes   → versées au bénéficiaire, sommées
       · services Anah    → financés par un forfait, jamais versés au ménage
       · prêt éco-PTZ     → remboursable, hors total */
  var LHI_AUDIT_EUR = 800, LHI_AMO_EUR = 1200;
  function lhiBreakdown(dos, resolved){
    var r = resolved || dos.result || {};
    var aide = r.aide || {};
    var directes = [
      { label: 'Ma Prime Logement Décent (ANAH)',    montant: aide.totalApresEcretement || aide.total || aide.base || 0 },
      { label: "MaPrimeRénov' (partie énergétique)", montant: aide.mprCumulable || 0, note: 'si audit fait' },
      { label: 'Aides régionales Grand Est',         montant: aide.local || 0, note: 'à vérifier localement' },
    ];
    return {
      directes: directes,
      totalDirectes: directes.reduce(function(s, l){ return s + (l.montant || 0); }, 0),
      services: [
        { label: 'Audit énergétique remboursé',             montant: LHI_AUDIT_EUR },
        { label: 'Accompagnement AMO opérateur spécialisé', montant: LHI_AMO_EUR },
      ],
      prets: [
        { label: 'Éco-PTZ mobilisable', montant: aide.ecoPtz || 50000, note: 'prêt à 0 %, 20 ans' },
      ],
    };
  }

  /* MaPrimeAdapt' mêle une subvention travaux, un accompagnement pris en charge
     par l'Anah, et des prestations à demander ailleurs (APA au Département, PCH à
     la MDPH). Les trois natures ne se somment pas : seules les subventions
     versées entrent dans le total. */
  var MPA_AMO_EUR = 1200;
  function mpaBreakdown(dos, resolved){
    var r = resolved || dos.result || {};
    var aide = r.aide || {};
    var prof = dos.profile || {};
    var age = Number(prof.age) || 0;
    var handicap = prof.handicap === 'oui_50plus' || prof.handicap === 'oui_pch';
    var directes = [
      { label: "MaPrimeAdapt' travaux", montant: aide.travaux || aide.total || 0 },
      { label: 'Aides locales Grand Est', montant: aide.local || 0, note: 'à vérifier localement' },
    ];
    var mobilisables = [];
    if (age >= 60){
      mobilisables.push({ label: "APA — Allocation Personnalisée d'Autonomie",
        note: 'à demander au Conseil départemental si GIR 1 à 4' });
    }
    if (handicap){
      mobilisables.push({ label: 'PCH — aménagement du logement',
        note: 'à demander à la MDPH' });
    }
    return {
      directes: directes,
      totalDirectes: directes.reduce(function(s, l){ return s + (l.montant || 0); }, 0),
      services: [{ label: 'Accompagnement AMO habilité Anah', montant: aide.amo || MPA_AMO_EUR }],
      mobilisables: mobilisables,
    };
  }

  function renderMpaCardBody(dos, resolved){
    var bd = mpaBreakdown(dos, resolved);
    var note = function(l){ return l.note ? ' <span class="dos-note">(' + l.note + ')</span>' : ''; };
    var h = '<div class="dos-section-label">Aides financières directes</div>';
    bd.directes.forEach(function(l){
      h += '<div class="dos-line"><span>' + l.label + note(l) + '</span><strong>' +
        (l.montant > 0 ? fmt(l.montant) : '— €') + '</strong></div>';
    });
    h += line('Total des aides directes', bd.totalDirectes, 'tot');
    h += '<div class="dos-section-label dos-section-label--small">Service financé par un forfait Anah — un solde est possible</div>';
    bd.services.forEach(function(l){
      h += '<div class="dos-line dos-line--service"><span>' + l.label +
        '</span><em class="dos-tag-gratuit">gratuit — ' + fmt(l.montant) + '</em></div>';
    });
    if (bd.mobilisables.length){
      h += '<div class="dos-section-label dos-section-label--small">Aides complémentaires mobilisables</div>';
      bd.mobilisables.forEach(function(l){
        h += '<div class="dos-line dos-line--pret"><span>' + l.label + note(l) +
          '</span><em>selon votre dossier</em></div>';
      });
    }
    return h;
  }

  function renderLhiCardBody(dos, resolved){
    var bd = lhiBreakdown(dos, resolved);
    var note = function(l){ return l.note ? ' <span class="dos-note">(' + l.note + ')</span>' : ''; };
    var h = '<div class="dos-section-label">Aides financières directes</div>';
    bd.directes.forEach(function(l){
      h += '<div class="dos-line"><span>' + l.label + note(l) + '</span><strong>' +
        (l.montant > 0 ? fmt(l.montant) : '— €') + '</strong></div>';
    });
    h += line('Total des aides directes', bd.totalDirectes, 'tot');
    h += '<div class="dos-section-label dos-section-label--small">Services financés par un forfait Anah — un solde est possible</div>';
    bd.services.forEach(function(l){
      h += '<div class="dos-line dos-line--service"><span>' + l.label +
        '</span><em class="dos-tag-gratuit">gratuit — ' + fmt(l.montant) + '</em></div>';
    });
    h += '<div class="dos-section-label dos-section-label--small">Prêt mobilisable</div>';
    bd.prets.forEach(function(l){
      h += '<div class="dos-line dos-line--pret"><span>' + l.label + note(l) +
        '</span><em>jusqu\'à ' + fmt(l.montant) + '</em></div>';
    });
    return h;
  }

  /* Chaque moteur range ses montants différemment : un rendu par type. */
  function lignes(dos){
    var r = resolveDossierResult(dos);
    if (!r) return '<div class="dos-line"><span>Estimation à recalculer</span>' +
      '<a class="dos-relance" href="' + relancerHref(dos.type) + '">Reprendre</a></div>';
    if (dos.type === 'autonomie') return renderMpaCardBody(dos, r);
    if (dos.type === 'indigne') return renderLhiCardBody(dos, r);
    if (r.aides){
      var h = '';
      if (r.aides.mpr && r.aides.mpr.total)   h += line("MaPrimeRénov'", r.aides.mpr.total);
      if (r.aides.cee && r.aides.cee.total)   h += line('CEE', r.aides.cee.total);
      if (r.aides.tva && r.aides.tva.total)   h += line('Économie TVA', r.aides.tva.total);
      if (r.aides.local && r.aides.local.total) h += line('Aide locale', r.aides.local.total);
      if (r.aides.grandEst && r.aides.grandEst.total) h += line('Aides Grand Est', r.aides.grandEst.total);
      return h + line('Total des aides', totalResolu(dos, r), 'tot');
    }
    return line('Total des aides', totalResolu(dos, r), 'tot');
  }

  sec.hidden = false;
  host.innerHTML = dossiers.map(function(dos){
    var meta = RFDossiers.meta(dos.type);
    var adr = (dos.profile && dos.profile.logement && dos.profile.logement.adresse) || '';
    return '<div class="dos-block" style="border-left-color:' + meta.color + '">' +
        '<h3 style="color:' + meta.color + '">' + meta.titre + '</h3>' +
        (adr ? '<div class="dos-adresse">' + adr.replace(/[&<>"]/g, function(c){ return ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'})[c]; }) + '</div>' : '') +
        '<div class="dos-meta">Créé le ' + RFDossiers.fmtDate(dos.transmisLe) +
          ((dos.partenaire && dos.partenaire.nom) ? ' · ' + dos.partenaire.nom : '') + '</div>' +
        '<div class="dos-lines">' + lignes(dos) + '</div>' +
        '<a class="dos-open" href="' + meta.detail + '?dossier=' + encodeURIComponent(dos.id) + '">Ouvrir ce dossier</a>' +
      '</div>';
  }).join('');
})();

pages/mes-aides/07.js:
/* JungleRenov — rend le widget profil de sidebar cliquable et ajoute Déconnexion */
(function(){
  function init(){
    var me = document.querySelector('.sidebar .me, aside .me');
    if (!me) return;
    me.style.cursor = 'pointer';
    me.style.position = 'relative';
    var menu = document.createElement('div');
    menu.style.cssText = 'display:none;position:absolute;bottom:calc(100% + 6px);left:0;right:0;background:#FFFFFF;border:1px solid #E9E3D3;border-radius:6px;box-shadow:none;padding:6px;z-index:50;font-size:17px';
    menu.innerHTML =
      '<a href="mon-profil.dc.html" style="display:flex;align-items:center;gap:8px;padding:9px 12px;border-radius:6px;color:#123A2E;text-decoration:none">' +
        '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="12" cy="8" r="4"/><path d="M4 21c0-4 4-7 8-7s8 3 8 7"/></svg>' +
        'Mon profil' +
      '</a>' +
      '<div style="height:1px;background:#E9E3D3;margin:4px 0"></div>' +
      '<a href="#" id="rf-side-logout" style="display:flex;align-items:center;gap:8px;padding:9px 12px;border-radius:6px;color:#991B1B;text-decoration:none">' +
        '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"/><path d="m16 17 5-5-5-5"/><path d="M21 12H9"/></svg>' +
        'Se déconnecter' +
      '</a>';
    me.appendChild(menu);
    me.addEventListener('click', function(e){
      if (e.target.closest('a')) return;
      menu.style.display = menu.style.display === 'none' ? 'block' : 'none';
    });
    document.addEventListener('click', function(e){
      if (!e.target.closest('.me')) menu.style.display = 'none';
    });
    var logoutLink = document.getElementById('rf-side-logout');
    if (logoutLink){
      logoutLink.addEventListener('click', function(e){
        e.preventDefault();
        if (window.RFStore) RFStore.logout();
        else {
          ['junglerenov.session','junglerenov.profile'].forEach(function(k){ try{localStorage.removeItem(k);}catch{} });
        }
        window.location.href = 'login.dc.html';
      });
    }
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();
})();

pages/mes-aides/08.js:
/* ═══════════════════════════════════════════════════════════════════
   Mes aides — génération dynamique des cartes depuis profile.aids
   - 1 carte par aide réellement éligible (montant > 0)
   - Statut par défaut "Éligible — à déposer" (pas "déposé" mensonger)
   - Boutons branchés sur les portails officiels
   - Liste des pièces requises affichée à la demande
   ═══════════════════════════════════════════════════════════════════ */
(function(){
  const KEY = 'junglerenov.profile';
  function getProfile(){
    try { return JSON.parse(localStorage.getItem(KEY) || '{}'); }
    catch { return {}; }
  }
  function fmtEUR(n){
    if (n == null || isNaN(n) || n <= 0) return null;
    return new Intl.NumberFormat('fr-FR').format(Math.round(n)) + ' €';
  }
  function escHtml(s){
    return String(s == null ? '' : s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  }

  // ─── Modèles d'aides : ce qui ne change pas selon l'utilisateur ─────
  const AIDS = [
    {
      key: 'mpr',
      logo: 'MPR',
      logoClass: '',
      name: "MaPrimeRénov'",
      org: "ANAH — Agence nationale de l'habitat",
      portalUrl: 'https://www.maprimerenov.gouv.fr/',
      portalLabel: 'Ouvrir mon compte ANAH',
      desc: 'Aide de l\'ANAH. En 2026, l\'<b>isolation des murs</b> et les <b>chaudières biomasse</b> ne sont plus finançables par geste — elles restent éligibles en rénovation d\'ampleur ou via CEE Coup de pouce. Les ménages aux ressources supérieures ne sont plus éligibles au parcours par geste.',
      pieces: ['Avis d\'imposition N-2', 'Devis d\'un artisan RGE', 'Photo avant travaux', 'Justificatif d\'identité'],
    },
    {
      key: 'cee',
      logo: 'CEE',
      logoClass: 'cee',
      name: 'Prime CEE — Certificats d\'économies d\'énergie',
      org: 'Obligé énergie (TotalEnergies, EDF, Engie…)',
      portalUrl: 'https://www.ecologie.gouv.fr/coup-pouce-economies-denergie',
      portalLabel: 'Choisir mon obligé énergie',
      desc: 'Prime financée par les fournisseurs d\'énergie. À demander AVANT signature du devis. Cumulable avec MaPrimeRénov\'.',
      pieces: ['Devis signé', 'Facture des travaux', 'Attestation sur l\'honneur'],
    },
    {
      key: 'local',
      logo: 'Loc',
      logoClass: 'local',
      name: 'Aide locale',
      org: 'Variable selon votre région et commune',
      portalUrl: 'https://france-renov.gouv.fr/aides',
      portalLabel: 'Trouver mon aide locale',
      desc: 'Subvention complémentaire de votre région, département ou intercommunalité. Souvent oubliée.',
      pieces: ['Justificatif de domicile', 'Devis ou facture', 'Formulaire de demande spécifique à votre collectivité'],
    },
    {
      key: 'tva',
      logo: 'TVA',
      logoClass: '',
      name: 'TVA réduite à 5,5 %',
      org: 'Appliquée directement par l\'artisan',
      portalUrl: 'https://www.service-public.fr/particuliers/vosdroits/F31506',
      portalLabel: 'Conditions du taux réduit',
      desc: 'Économie automatique sur la facture (au lieu de 10 %, taux normal des travaux de rénovation). L\'artisan applique le taux réduit directement, à condition que son devis soit conforme.',
      pieces: ['Devis mentionnant le taux 5,5 %', 'Attestation TVA simplifiée'],
    },
    {
      key: 'eptz',
      logo: 'PTZ',
      logoClass: 'eptz',
      name: 'Éco-prêt à taux zéro',
      org: 'Banque agréée par l\'État',
      portalUrl: 'https://www.service-public.fr/particuliers/vosdroits/F19905',
      portalLabel: 'Liste des banques agréées',
      desc: 'Prêt à 0 % d\'intérêts pour financer votre reste à charge. Plafond 7 000 à 30 000 € en rénovation ponctuelle selon le nombre de gestes, sur 15 ans max. Jusqu\'à 50 000 € sur 20 ans en rénovation globale (audit énergétique + saut de 2 classes DPE).',
      pieces: ['Devis des travaux', 'Avis d\'imposition', 'Justificatif d\'identité', 'Formulaire emprunteur'],
    },
  ];

  // ─── Affichage ──────────────────────────────────────────────────────
  function render(){
    const p = getProfile();
    const courant = (window.rfAidsCourantes && window.rfAidsCourantes()) || p.aids || {};
    const aids = courant.aides || {};
    const container = document.getElementById('aids-dynamic');
    const emptyEl = document.getElementById('aids-empty');
    if (!container) return;

    // Construit la liste des aides EFFECTIVES (montant > 0)
    const items = [];
    AIDS.forEach(model => {
      let montant = null;
      if (model.key === 'mpr')   montant = aids.mpr && aids.mpr.total;
      else if (model.key === 'cee')   montant = aids.cee && aids.cee.total;
      else if (model.key === 'local') montant = aids.local && aids.local.total;
      else if (model.key === 'tva')   montant = aids.tva && aids.tva.total;
      else if (model.key === 'eptz')  {
        // Éco-PTZ : finance le RESTE À CHARGE (TTC - aides directes), pas le coût total.
        // Plafonds officiels rénovation ponctuelle (service-public.fr F19905) :
        //   - 7 000 € : 1 action parois vitrées (menuiseries) SEULE
        //   - 15 000 € : 1 action autre nature
        //   - 25 000 € : lot de 2 travaux
        //   - 30 000 € : lot de 3 travaux ou plus
        // Le plafond 50 000 € est réservé à la rénovation globale (audit énergétique
        // démontrant un gain ≥ 2 classes DPE), non auto-détectable ici — mentionné dans le PDF.
        const trav = (p.aids && p.aids.travaux) || {};
        const totalTTC = trav.totalTTC || 0;
        const totalAides = (p.aids && p.aids.totalAides) || 0;
        const rac = Math.max(0, totalTTC - totalAides);
        const sel = (p.aids && p.aids.selection) || (p.travaux) || [];
        const nbGestes = sel.length;
        const onlyMenuiseries = nbGestes === 1 && sel.includes('menuiseries');
        let plafondPtz;
        if (onlyMenuiseries)          plafondPtz = 7000;   // 1 action parois vitrées seule
        else if (nbGestes >= 3)       plafondPtz = 30000;  // lot de 3 travaux ou plus
        else if (nbGestes === 2)      plafondPtz = 25000;  // lot de 2 travaux
        else if (nbGestes === 1)      plafondPtz = 15000;  // 1 action autre que parois vitrées
        else                          plafondPtz = 7000;   // fallback
        if (rac > 0) montant = Math.min(rac, plafondPtz);
      }
      if (montant && montant > 0){
        const localNom = (model.key === 'local' && aids.local && aids.local.nom) ? aids.local.nom : null;
        items.push({ ...model, montant, customName: localNom });
      }
    });

    // Met à jour les compteurs
    const cntAll = document.getElementById('cnt-all');
    const cntEli = document.getElementById('cnt-eli');
    if (cntAll) cntAll.textContent = '(' + items.length + ')';
    if (cntEli) cntEli.textContent = '(' + items.length + ')';

    if (!items.length){
      container.innerHTML = '';
      if (emptyEl) emptyEl.hidden = false;
      return;
    }
    if (emptyEl) emptyEl.hidden = true;

    container.innerHTML = items.map((a, idx) => {
      const displayName = a.customName ? escHtml(a.customName) : escHtml(a.name);
      return `
      <article class="aid" data-status="eligible" data-key="${a.key}">
        <div class="aid-head">
          <div class="aid-h-l">
            <div class="aid-logo ${a.logoClass}">${a.logo}</div>
            <div>
              <div class="aid-name">${displayName}</div>
              <div class="aid-org">${escHtml(a.org)}</div>
              <div style="margin-top:8px;display:flex;gap:6px;flex-wrap:wrap">
                <span class="pill eligible" style="background:var(--success-50);color:var(--success-600);padding:3px 10px;border-radius:6px;font:600 17px var(--font-mono);">Éligible — à déposer</span>
                ${a.key === 'mpr' && p.aids && p.aids.mpr && p.aids.mpr.isRenovAmpleur ? '<span class="pill" style="background:var(--warning-50);color:var(--warning-600);padding:3px 10px;border-radius:6px;font:600 17px var(--font-mono);" title="Audit énergétique + 2 gestes d\'isolation + saut de 2 classes DPE">Parcours accompagné · MAR obligatoire</span>' : ''}
              </div>
            </div>
          </div>
          <div class="aid-amount">
            <div class="v">${fmtEUR(a.montant)}</div>
            <div class="s">Montant estimé</div>
          </div>
        </div>
        <div class="aid-body" style="padding:0 22px 18px">
          <p style="color:var(--slate-600);font-size:17px;margin:0 0 14px;line-height:1.55">${escHtml(a.desc)}</p>
          <details style="margin-bottom:14px">
            <summary style="cursor:pointer;font-size:17px;color:var(--teal-700);font-weight:500;user-select:none">Voir les pièces requises</summary>
            <ul style="margin:8px 0 0;padding-left:18px;font-size:17px;color:var(--slate-700);line-height:1.7">
              ${a.pieces.map(pi => '<li>' + escHtml(pi) + '</li>').join('')}
            </ul>
          </details>
          ${a.key === 'mpr' ? `<div style="background:#E9E3D3;border:1px solid #123A2E;border-radius:6px;padding:12px 14px;margin:12px 0;display:flex;gap:10px;align-items:flex-start;font-size:17px;color:#123A2E">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" style="flex:0 0 auto;margin-top:1px"><circle cx="12" cy="12" r="10"/><path d="M12 16v-4M12 8h0"/></svg>
            <div>
              <b>À savoir avant de déposer</b> — L'Anah exige que <b>vous créiez votre compte MaPrimeRénov' vous-même</b> (5 minutes sur maprimerenov.gouv.fr avec France Connect+). C'est une règle anti-fraude 2026 qui s'applique à tous les mandataires du marché, sans exception. <b>Rassurez-vous, nous vous accompagnons pas à pas</b> : guide illustré, tuto vidéo, checklist des pièces à préparer et support email si besoin. Une fois le compte créé, désignez-nous comme mandataire administratif — nous gérons tout le reste jusqu'au versement de votre prime.
            </div>
          </div>` : ''}
          <div class="aid-actions" style="display:flex;gap:8px;flex-wrap:wrap">
            ${(function(){
              if (a.key === 'tva') {
                return `<button type="button" class="btn btn-primary" data-tva="1" data-aid-name="${escHtml(displayName)}" data-aid-amount="${a.montant}">
                  <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>
                  Télécharger l'attestation pour mon artisan
                </button>
                <span style="font-size:17px;color:var(--slate-500);align-self:center">L'artisan applique le taux directement sur sa facture.</span>`;
              }
              if (a.key === 'eptz') {
                return `<button type="button" class="btn btn-primary" data-eptz="1" data-aid-name="${escHtml(displayName)}" data-aid-amount="${a.montant}">
                  <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>
                  Préparer mon dossier pour la banque
                </button>
                <span style="font-size:17px;color:var(--slate-500);align-self:center">À apporter à votre banquier en agence.</span>`;
              }
              // Rénovation d'ampleur : pour MPR, c'est un MAR qui doit déposer (pas JungleRenov)
              const isRenovAmpleurMpr = a.key === 'mpr' && p.aids && p.aids.mpr && p.aids.mpr.isRenovAmpleur;
              if (isRenovAmpleurMpr){
                return `<a href="https://france-renov.gouv.fr/annuaires-professionnels/accompagnant" target="_blank" rel="noopener" class="btn btn-primary">
                  <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="7"/><path d="m21 21-4.3-4.3"/></svg>
                  Choisir mon MAR (annuaire ANAH) ↗
                </a>
                <span style="font-size:17px;color:var(--warning-600);align-self:center">Rénovation d'ampleur — votre MAR dépose le dossier MPR pour vous (et non JungleRenov).</span>`;
              }
              return `<button type="button" class="btn btn-primary" data-depot="${a.key}" data-aid-name="${escHtml(displayName)}" data-aid-amount="${a.montant}">
                <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 16v-4a2 2 0 0 0-2-2h-7l-3-3H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h7"/><path d="m16 19 2 2 4-4"/></svg>
                Confier le dépôt à JungleRenov
              </button>
              <a href="${escHtml(a.portalUrl)}" target="_blank" rel="noopener" class="btn btn-secondary" style="font-size:17px">
                ou faire moi-même sur le portail officiel ↗
              </a>`;
            })()}
          </div>
        </div>
        <div class="aid-foot" style="padding:12px 22px;border-top:1px solid var(--border);background:var(--slate-50);font-size:17px;color:var(--slate-500);display:flex;justify-content:space-between;flex-wrap:wrap;gap:8px">
          <span>Aide officielle — ${escHtml(a.org)}</span>
          <span>Estimation indicative, à confirmer après dépôt du dossier</span>
        </div>
      </article>`;
    }).join('');
  }

  /* ───── Wizard "Confier le dépôt à JungleRenov" ─────
     3 étapes : récap profil → upload pièces → signature mandat.
     À la validation : enregistre le dossier dans profile.dossiers_a_deposer
     et déclenche le statut "à traiter" côté admin. */
  function openDepotWizard(aidKey, aidName, aidAmount){
    const p = getProfile();
    const fullName = ((p.firstname||'')+' '+(p.lastname||'')).trim() || '—';
    const fmt = n => new Intl.NumberFormat('fr-FR').format(Math.round(n||0)) + ' €';
    const PIECES_BY_KEY = {
      mpr:   ['Avis d\'imposition N-2', 'Devis d\'un artisan RGE', 'Photo avant travaux', 'Justificatif d\'identité'],
      cee:   ['Devis signé d\'un artisan RGE', 'Justificatif de domicile', 'Avis d\'imposition'],
      local: ['Justificatif de domicile', 'Devis ou facture', 'Formulaire de la collectivité'],
      tva:   ['Devis mentionnant le taux 5,5 %', 'Attestation TVA simplifiée'],
      eptz:  ['Devis des travaux', 'Avis d\'imposition', 'Justificatif d\'identité'],
      mpa:   ['Avis d\'imposition N-2', "Justificatif d'âge ou évaluation GIR", 'Justificatif de handicap ou PCH (le cas échéant)', "Devis des travaux d'adaptation", "Diagnostic du logement établi par l'AMO"],
      mpld:  ['Avis d\'imposition N-2', 'Grille de dégradation ou d\'insalubrité', 'Audit énergétique', 'Devis d\'entreprises RGE', 'Justificatif d\'identité'],
    };
    const pieces = PIECES_BY_KEY[aidKey] || ['Pièces justificatives'];

    let modal = document.getElementById('depot-modal');
    if (modal) modal.remove();
    modal = document.createElement('div');
    modal.id = 'depot-modal';
    modal.style.cssText = 'position:fixed;inset:0;background:rgba(15,23,42,.6);display:flex;align-items:center;justify-content:center;z-index:9999;padding:20px;overflow-y:auto';
    modal.innerHTML =
      '<div style="background:#FFFFFF;border-radius:6px;max-width:560px;width:100%;padding:0;box-shadow:none;max-height:92vh;overflow-y:auto">' +
        '<div style="padding:24px 28px 16px;border-bottom:1px solid var(--border);position:sticky;top:0;background:#FFFFFF;z-index:2">' +
          '<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:14px">' +
            '<div>' +
              '<div style="font:600 17px var(--font-mono);color:var(--teal-700);">Confier mon dépôt</div>' +
              '<h3 style="margin:6px 0 4px;font-size:18px;color:var(--slate-900)">' + escHtml(aidName) + '</h3>' +
              '<div style="font-size:17px;color:var(--slate-500)">Montant estimé : <b style="color:var(--teal-800)">' + fmt(aidAmount) + '</b></div>' +
            '</div>' +
            '<button id="depot-close" style="background:transparent;border:0;font-size:22px;color:var(--slate-400);cursor:pointer;line-height:1;padding:0">×</button>' +
          '</div>' +
          '<div style="display:flex;gap:6px;margin-top:14px" id="depot-steps">' +
            '<div data-step="1" class="depot-pip on" style="flex:1;height:4px;border-radius:2px;background:var(--teal-700)"></div>' +
            '<div data-step="2" class="depot-pip" style="flex:1;height:4px;border-radius:2px;background:var(--slate-200)"></div>' +
            '<div data-step="3" class="depot-pip" style="flex:1;height:4px;border-radius:2px;background:var(--slate-200)"></div>' +
          '</div>' +
        '</div>' +
        '<div id="depot-body" style="padding:24px 28px"></div>' +
        '<div style="padding:14px 28px;border-top:1px solid var(--border);display:flex;justify-content:space-between;gap:8px;position:sticky;bottom:0;background:#FFFFFF">' +
          '<button id="depot-prev" class="btn btn-secondary" style="opacity:.4;cursor:not-allowed" disabled>Précédent</button>' +
          '<button id="depot-next" class="btn btn-primary">Continuer</button>' +
        '</div>' +
      '</div>';
    document.body.appendChild(modal);

    let step = 1;
    const uploaded = {}; // pieces uploadées : { 'piece_index' : { name, size } }
    let signatureDataURL = null;

    const stepRenderers = {
      1: () => {
        return '<h4 style="margin:0 0 12px;font-size:17px;color:var(--slate-700)">1. Vérifions vos informations</h4>' +
          '<table style="width:100%;font-size:17px;border-collapse:collapse">' +
            '<tr><td style="padding:7px 0;color:var(--slate-500);width:42%">Nom complet</td><td><b>' + escHtml(fullName) + '</b></td></tr>' +
            '<tr><td style="padding:7px 0;color:var(--slate-500);border-top:1px solid var(--border)">Email</td><td style="border-top:1px solid var(--border)">' + escHtml(p.email||'—') + '</td></tr>' +
            '<tr><td style="padding:7px 0;color:var(--slate-500);border-top:1px solid var(--border)">Adresse</td><td style="border-top:1px solid var(--border)">' + escHtml(p.address||'—') + '</td></tr>' +
            '<tr><td style="padding:7px 0;color:var(--slate-500);border-top:1px solid var(--border)">Logement</td><td style="border-top:1px solid var(--border)">' + escHtml((p.logement&&p.logement.type)||'—') + ' · ' + ((p.logement&&p.logement.surface)||'—') + ' m² · ' + ((p.logement&&p.logement.year)||'—') + '</td></tr>' +
            '<tr><td style="padding:7px 0;color:var(--slate-500);border-top:1px solid var(--border)">RFR</td><td style="border-top:1px solid var(--border)">' + fmt(p.foyer&&p.foyer.rfr) + '</td></tr>' +
            '<tr><td style="padding:7px 0;color:var(--slate-500);border-top:1px solid var(--border)">Catégorie</td><td style="border-top:1px solid var(--border)"><b>' + escHtml((p.foyer&&p.foyer.cat)||(p.aids&&p.aids.profile&&p.aids.profile.cat)||'—') + '</b></td></tr>' +
          '</table>' +
          '<div style="margin-top:14px;padding:10px 12px;background:var(--teal-50);border:1px solid var(--teal-100);border-radius:6px;font-size:17px;color:var(--teal-900)">' +
            'Ces informations sont issues de votre simulation. Pour les modifier, allez dans <a href="mon-profil.dc.html" style="color:var(--teal-700);font-weight:600">Mon profil</a>.' +
          '</div>';
      },
      2: () => {
        let html = '<h4 style="margin:0 0 6px;font-size:17px;color:var(--slate-700)">2. Téléversez vos pièces justificatives</h4>' +
          '<p style="font-size:17px;color:var(--slate-500);margin:0 0 14px">Acceptés : PDF, JPG, PNG. Maximum 10 Mo par pièce.</p>';
        pieces.forEach((piece, i) => {
          const up = uploaded[i];
          html += '<div style="display:flex;align-items:center;gap:10px;padding:10px 12px;border:1px solid var(--border);border-radius:6px;margin-bottom:8px">' +
            '<div style="flex:1">' +
              '<div style="font-size:17px;color:var(--slate-800)">' + escHtml(piece) + '</div>' +
              (up ? '<div style="font-size:17px;color:var(--teal-700);margin-top:2px">✓ ' + escHtml(up.name) + ' · ' + Math.round(up.size/1024) + ' Ko</div>' : '<div style="font-size:17px;color:var(--slate-400);margin-top:2px">À téléverser</div>') +
            '</div>' +
            '<button data-upload-idx="' + i + '" class="btn ' + (up ? 'btn-secondary' : 'btn-primary') + '" style="font-size:17px;padding:6px 12px">' +
              (up ? 'Remplacer' : 'Choisir un fichier') +
            '</button>' +
          '</div>';
        });
        return html;
      },
      3: () => {
        return '<h4 style="margin:0 0 6px;font-size:17px;color:var(--slate-700)">3. Signez le mandat de dépôt</h4>' +
          '<p style="font-size:17px;color:var(--slate-500);margin:0 0 12px">En signant, vous autorisez <b>JungleRenov</b> à déposer cette demande d\'aide en votre nom auprès de l\'organisme compétent.</p>' +
          '<canvas id="depot-canvas" width="500" height="160" style="border:1.5px dashed var(--slate-300);border-radius:6px;width:100%;background:#FFFFFF;touch-action:none;display:block;cursor:crosshair"></canvas>' +
          '<div style="display:flex;justify-content:space-between;font-size:17px;color:var(--slate-400);margin-top:6px">' +
            '<button id="depot-sig-clear" style="background:transparent;border:0;color:var(--teal-700);cursor:pointer;font-size:17px;font-weight:500">Effacer</button>' +
            '<span>Signé le ' + new Date().toLocaleDateString('fr-FR') + '</span>' +
          '</div>' +
          '<div style="margin-top:14px;padding:10px 12px;background:#E9E3D3;border:1px solid #123A2E;border-radius:6px;font-size:17px;color:#123A2E;line-height:1.5">' +
            'Mandat de dépôt simple. Signature manuscrite numérique équivalente à une signature scannée. JungleRenov s\'engage à déposer votre dossier sous 48h ouvrées et à vous tenir informé.' +
          '</div>';
      },
    };

    function renderStep(){
      document.querySelectorAll('#depot-steps .depot-pip').forEach((el, i) => {
        el.style.background = (i+1) <= step ? 'var(--teal-700)' : 'var(--slate-200)';
      });
      document.getElementById('depot-body').innerHTML = stepRenderers[step]();
      const prev = document.getElementById('depot-prev');
      const next = document.getElementById('depot-next');
      prev.disabled = step === 1;
      prev.style.opacity = step === 1 ? .4 : 1;
      prev.style.cursor = step === 1 ? 'not-allowed' : 'pointer';
      next.textContent = step === 3 ? 'Envoyer mon dossier à JungleRenov ✓' : 'Continuer';

      if (step === 2){
        document.querySelectorAll('[data-upload-idx]').forEach(b => b.addEventListener('click', () => {
          const idx = +b.dataset.uploadIdx;
          const i = document.createElement('input');
          i.type = 'file'; i.accept = '.pdf,.jpg,.jpeg,.png';
          i.onchange = () => {
            const f = i.files && i.files[0];
            if (!f) return;
            if (f.size > 10*1024*1024){ alert('Fichier trop volumineux (max 10 Mo).'); return; }
            uploaded[idx] = { name: f.name, size: f.size, mime: f.type };
            renderStep(); // re-render pour afficher l'état uploadé
          };
          i.click();
        }));
      }
      if (step === 3){
        const canvas = document.getElementById('depot-canvas');
        const ctx = canvas.getContext('2d');
        ctx.strokeStyle = '#123A2E'; ctx.lineWidth = 2.5; ctx.lineCap = 'round';
        let drawing = false;
        const getPos = e => {
          const r = canvas.getBoundingClientRect();
          const t = e.touches ? e.touches[0] : e;
          return { x: (t.clientX - r.left) * canvas.width / r.width, y: (t.clientY - r.top) * canvas.height / r.height };
        };
        canvas.addEventListener('mousedown', e => { drawing = true; const p = getPos(e); ctx.beginPath(); ctx.moveTo(p.x, p.y); });
        canvas.addEventListener('mousemove', e => { if (drawing){ const p = getPos(e); ctx.lineTo(p.x,p.y); ctx.stroke(); signatureDataURL = canvas.toDataURL('image/png'); } });
        canvas.addEventListener('mouseup', () => drawing = false);
        canvas.addEventListener('mouseleave', () => drawing = false);
        canvas.addEventListener('touchstart', e => { e.preventDefault(); drawing = true; const p = getPos(e); ctx.beginPath(); ctx.moveTo(p.x,p.y); });
        canvas.addEventListener('touchmove', e => { e.preventDefault(); if (drawing){ const p = getPos(e); ctx.lineTo(p.x,p.y); ctx.stroke(); signatureDataURL = canvas.toDataURL('image/png'); } });
        canvas.addEventListener('touchend', () => drawing = false);
        document.getElementById('depot-sig-clear').addEventListener('click', () => {
          ctx.clearRect(0,0,canvas.width,canvas.height); signatureDataURL = null;
        });
      }
    }

    function close(){ modal.remove(); }
    document.getElementById('depot-close').addEventListener('click', close);
    document.getElementById('depot-prev').addEventListener('click', () => { if (step>1){ step--; renderStep(); } });
    document.getElementById('depot-next').addEventListener('click', () => {
      // Validation par étape
      if (step === 2){
        if (Object.keys(uploaded).length < pieces.length){
          alert('Veuillez téléverser toutes les pièces requises (' + pieces.length + ' au total).');
          return;
        }
      }
      if (step === 3){
        if (!signatureDataURL){
          alert('Veuillez signer le mandat de dépôt.');
          return;
        }
        // Validation finale : enregistrement
        try {
          const prof = getProfile();
          const dossiers = Array.isArray(prof.dossiers_a_deposer) ? prof.dossiers_a_deposer : [];
          dossiers.push({
            aidKey, aidName, aidAmount,
            piecesUploadees: Object.entries(uploaded).map(([i,m]) => ({ piece: pieces[i], name: m.name, size: m.size })),
            mandatSignature: signatureDataURL,
            confiéLe: new Date().toISOString(),
            statut: 'a_deposer',
          });
          prof.dossiers_a_deposer = dossiers;
          // Statut dossier global passe à "a_traiter" pour que l'admin le voie
          prof.dossierStatus = 'a_traiter';
          prof.dossierStatusHistory = prof.dossierStatusHistory || [];
          prof.dossierStatusHistory.unshift({
            at: new Date().toISOString(), from: prof.dossierStatusHistory[0]?.to || 'nouveau',
            to: 'a_traiter', by: prof.email || 'client',
            note: 'Demande de dépôt confiée pour ' + aidName,
          });
          localStorage.setItem('junglerenov.profile', JSON.stringify(prof));

          // Mirror côté clients pour que l'admin voie immédiatement
          try {
            const clients = JSON.parse(localStorage.getItem('junglerenov.clients') || '[]');
            const idx = clients.findIndex(c => c.email === prof.email);
            if (idx >= 0){
              clients[idx].dossierStatus = 'a_traiter';
              clients[idx].dossiers_a_deposer = dossiers;
              clients[idx].updatedAt = new Date().toISOString();
              localStorage.setItem('junglerenov.clients', JSON.stringify(clients));
            }
          } catch {}
        } catch(e){ console.warn('Save dossier :', e); }
        close();
        // Toast / Message confirmation
        const ok = document.createElement('div');
        ok.style.cssText = 'position:fixed;bottom:24px;left:50%;transform:translateX(-50%);background:var(--teal-700);color:#FFFFFF;padding:14px 22px;border-radius:6px;font-size:17px;z-index:10000;max-width:90vw;box-shadow:none';
        ok.innerHTML = '<b>✓ Dossier confié à JungleRenov.</b><br><span style="opacity:.9;font-size:17px">Notre équipe le dépose sous 48h ouvrées. Vous recevrez une notification.</span>';
        document.body.appendChild(ok);
        setTimeout(() => ok.remove(), 5000);
        return;
      }
      step++; renderStep();
    });

    renderStep();
  }

  // Branche les boutons "Confier le dépôt" sur les cartes aides (MPR / CEE / local)
  document.addEventListener('click', e => {
    const btn = e.target.closest('[data-depot]');
    if (btn){
      openDepotWizard(btn.dataset.depot, btn.dataset.aidName, +btn.dataset.aidAmount);
      return;
    }
    const tvaBtn = e.target.closest('[data-tva]');
    if (tvaBtn){
      downloadTvaAttestation();
      return;
    }
    const ptzBtn = e.target.closest('[data-eptz]');
    if (ptzBtn){
      downloadPtzDossier(+ptzBtn.dataset.aidAmount);
      return;
    }
  });

  /* ───── PDF wrappers ─────
     Les générateurs sont factorisés dans _pdf_docs.js (RFDocs.*) pour pouvoir
     être réutilisés depuis mes-documents.dc.html sans dupliquer le code. */
  function downloadTvaAttestation(){
    if (!window.RFDocs || !window.RFDocs.generateTvaAttestation) {
      toast('Bibliothèque PDF indisponible. Vérifiez votre connexion internet.');
      return;
    }
    try {
      window.RFDocs.generateTvaAttestation(getProfile());
      toast('Attestation TVA (PDF) téléchargée. À remettre à votre artisan AVANT le début des travaux.');
    } catch(e){
      console.warn('TVA PDF :', e);
      toast('Erreur lors de la génération du PDF.');
    }
  }
  function downloadPtzDossier(maxAmount){
    if (!window.RFDocs || !window.RFDocs.generatePtzDossier) {
      toast('Bibliothèque PDF indisponible. Vérifiez votre connexion internet.');
      return;
    }
    try {
      window.RFDocs.generatePtzDossier(getProfile(), maxAmount);
      toast('Dossier éco-PTZ (PDF) téléchargé. À imprimer et apporter à votre banquier.');
    } catch(e){
      console.warn('PTZ PDF :', e);
      toast('Erreur lors de la génération du PDF.');
    }
  }

  function triggerDownload(html, filename){
    const blob = new Blob([html], {type:'text/html;charset=utf-8'});
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = filename;
    document.body.appendChild(a); a.click();
    setTimeout(() => { URL.revokeObjectURL(url); a.remove(); }, 100);
  }
  function toast(msg){
    const el = document.createElement('div');
    el.style.cssText = 'position:fixed;bottom:24px;left:50%;transform:translateX(-50%);background:var(--teal-700);color:#FFFFFF;padding:12px 22px;border-radius:6px;font-size:17px;z-index:10000;max-width:90vw;box-shadow:none';
    el.textContent = msg;
    document.body.appendChild(el);
    setTimeout(() => el.remove(), 4000);
  }

  // Filter pills
  document.querySelectorAll('.filters button').forEach(b => {
    b.addEventListener('click', () => {
      document.querySelectorAll('.filters button').forEach(x => x.classList.remove('on'));
      b.classList.add('on');
      const f = b.dataset.f;
      document.querySelectorAll('#aids-dynamic .aid').forEach(a => {
        a.style.display = (f === 'all' || a.dataset.status === f) ? '' : 'none';
      });
    });
  });

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', render);
  else render();
  window.addEventListener('storage', e => { if (e.key === KEY) render(); });
})();

