/* Les sections MPA et LHI ne s'affichent que si l'utilisateur a réellement un
   dossier de ce type : la page « Mes aides » reflète ses parcours, elle ne
   suggère pas de produits qu'il n'a pas demandés. Cachées par défaut (`hidden`
   dans le HTML), révélées ici. */
(function revealMatchingSections(){
  try {
    if (!window.RFDossiers || typeof RFDossiers.getAll !== 'function') return;
    var types = {};
    (RFDossiers.getAll() || []).forEach(function(d){ if (d && d.type) types[d.type] = true; });
    if (types.autonomie){
      var mpa = document.getElementById('aid-block-mpa');
      if (mpa) mpa.removeAttribute('hidden');
    }
    if (types.indigne){
      var lhi = document.getElementById('aid-block-lhi');
      if (lhi) lhi.removeAttribute('hidden');
    }
    // Le catalogue énergétique et « Vos dossiers en cours » restent gérés par
    // la logique existante.
  } catch (_) {}
})();

pages/mes-aides/10.js:
/* Page « Mes aides » polymorphique : avec ?dossier=xxx, elle n'expose que les
   aides du type ouvert. Sans paramètre, elle reste le catalogue transversal.
   Ce bloc tourne en dernier : il a le dernier mot sur les bascules ci-dessus. */
function adaptToOpenDossier(){
  function getOpenDossier(){
    try {
      if (!window.RFDossiers) return null;
      var id = new URLSearchParams(location.search).get('dossier');
      if (id){
        var byId = RFDossiers.getById(id);
        if (byId) return byId;
      }
      // Arrivée par le lien de la sidebar : on ouvre le dossier le plus récent,
      // sinon la page reste en catalogue transversal alors qu'un dossier existe.
      var actifs = (RFDossiers.getActifs && RFDossiers.getActifs()) || [];
      return actifs.length ? actifs[actifs.length - 1] : null;
    } catch (_) { return null; }
  }
  var dossier = getOpenDossier();

  /* L'état « Aucune simulation réalisée » — et les 4 cards pédagogiques qu'il
     contient — n'a de sens que pour un compte vide. Il est piloté par
     junglerenov.profile, qui reste vide sur un parcours MPA ou LHI. */
  try {
    var unDossierExiste = !!(window.RFDossiers && (RFDossiers.getActifs() || []).length);
    var emptyGlobal = document.getElementById('empty-aids');
    if (emptyGlobal && unDossierExiste) emptyGlobal.hidden = true;
  } catch (_) {}

  if (!dossier || !dossier.type) return;

  var eur = function(n){ return Math.round(Number(n) || 0).toLocaleString('fr-FR') + ' €'; };
  var type = dossier.type;
  var r = (window.rfResolveDossierResult ? window.rfResolveDossierResult(dossier) : dossier.result) || {};

  var blocs = {
    autonomie:   document.getElementById('aid-block-mpa'),
    indigne:     document.getElementById('aid-block-lhi'),
    energetique: document.querySelector('[data-aid-block="energetique"]'),
  };
  Object.keys(blocs).forEach(function(k){
    if (blocs[k]) blocs[k].hidden = (k !== type);
  });
  // L'état vide « aucun diagnostic » n'a pas de sens quand un dossier est ouvert.
  var empty = document.getElementById('empty-aids');
  if (empty && type !== 'energetique') empty.hidden = true;

  var titres = {
    energetique: 'Mes aides — Rénovation énergétique',
    autonomie:   "Mes aides — Adaptation à l'autonomie",
    indigne:     'Mes aides — Habitat dégradé ou insalubre',
  };
  var h1 = document.querySelector('h1.page-title');
  if (h1 && titres[type]) h1.textContent = titres[type];

  // Montant du dossier ouvert : celui qui a été acheté, pas un recalcul.
  // Même source de vérité que la card dossier (aides directes pour un LHI).
  var total = (window.rfTotalDossier && window.rfTotalDossier(dossier, r)) || 0;
  if (!total){
    if (type === 'autonomie')   total = (r.aide && r.aide.total) || 0;
    if (type === 'indigne')     total = (r.aide && (r.aide.totalApresEcretement || r.aide.total)) || 0;
    if (type === 'energetique') total = r.totalAides || 0;
  }

  var conf = {
    autonomie: { sel: '#aid-block-mpa', cta: "Voir mon dossier MaPrimeAdapt'" },
    indigne:   { sel: '#aid-block-lhi', cta: 'Voir mon dossier Ma Prime Logement Décent' },
  }[type];
  if (conf && total > 0){
    var amountEl = document.querySelector(conf.sel + ' .aid-amount');
    if (amountEl) amountEl.innerHTML = '<div class="v">' + eur(total) + '</div><div class="s">total estimé</div>';
    var ctaEl = document.querySelector(conf.sel + ' .aid-foot a');
    if (ctaEl){
      ctaEl.textContent = conf.cta;
      ctaEl.href = 'dashboard.dc.html?dossier=' + encodeURIComponent(dossier.id);
    }
  }

  /* Les blocs statiques MPA / LHI servent la découverte (« voici ce que cette
     aide peut apporter »). Dès qu'un dossier du type est ouvert, la card du haut
     porte déjà l'information chiffrée : on retire le doublon. */
  var blocStatique = document.getElementById(type === 'indigne' ? 'aid-block-lhi' : (type === 'autonomie' ? 'aid-block-mpa' : ''));
  if (blocStatique) blocStatique.hidden = true;

  /* Les mini-cards « À évaluer » présentent le catalogue énergétique. Elles
     vivent dans l'état vide, déjà masqué plus haut ; ce filet garantit qu'elles
     ne réapparaîtront pas sur un dossier MPA ou LHI si l'état vide change. */
  if (type !== 'energetique'){
    document.querySelectorAll('[data-aid-mini="energetique"]').forEach(function(el){ el.hidden = true; });
  }

  /* Formulaires officiels attendus selon le dispositif. Les statuts reflètent la
     réalité du parcours : rien n'est générable avant le diagnostic de l'opérateur. */
  (function renderDossiersADeposer(){
    var section = document.getElementById('dossiers-a-deposer');
    var host = document.getElementById('dossiers-a-deposer-list');
    if (!section || !host) return;
    var variant = r.variant || (dossier.profile && dossier.profile.variant) || 'occupant';
    var FORMULAIRES = {
      energetique: [
        { nm: "Demande MaPrimeRénov'",              st: 'En attente de pièces',        ico: 'DOC' },
        { nm: 'Attestation CEE (prime énergie)',    st: 'En attente de pièces',        ico: 'DOC' },
        { nm: 'Attestation TVA 5,5 %',              st: "Document d'aide · à remettre à l'artisan", ico: 'PDF', pret: true },
        { nm: 'Dossier éco-PTZ',                    st: "Document d'aide · à apporter à votre banque", ico: 'PDF', pret: true },
      ],
      autonomie: [
        { nm: "Demande MaPrimeAdapt' — Anah",       st: 'En attente de la simulation AMO', ico: 'DOC' },
        { nm: 'Mandat de représentation AMO',       st: "À signer après le rendez-vous avec l'opérateur", ico: 'DOC' },
      ],
      indigne: [
        { nm: 'Demande Ma Prime Logement Décent — Anah', st: "En attente de l'audit énergétique et de la grille d'évaluation", ico: 'DOC' },
        { nm: 'Mandat opérateur spécialisé LHI',    st: "À signer après le rendez-vous avec l'opérateur", ico: 'DOC' },
        { nm: "Convention Loc'Avantages",           st: 'À signer avec l\'Anah — engagement locatif de 6 ans', ico: 'DOC', variant: 'bailleur' },
        { nm: 'Dossier éco-PTZ',                    st: "Document d'aide · à apporter à votre banque", ico: 'PDF', pret: true },
      ],
    };
    var liste = (FORMULAIRES[type] || []).filter(function(f){ return !f.variant || f.variant === variant; });
    if (!liste.length) return;
    host.innerHTML = liste.map(function(f, i){
      return '<div style="display:flex;justify-content:space-between;align-items:center;gap:14px;padding:14px 0' +
          (i ? ';border-top:1px solid var(--slate-100,#E9E3D3)' : '') + '">' +
        '<div style="display:flex;align-items:center;gap:12px;min-width:0">' +
          '<span class="file-ic ' + (f.pret ? 'gen' : '') + '" style="flex:0 0 auto">' + f.ico + '</span>' +
          '<div style="min-width:0"><div style="font-weight:600;font-size:17px;color:var(--slate-900)">' + f.nm + '</div>' +
          '<div style="font-size:17px;color:var(--slate-500)">' + f.st + '</div></div>' +
        '</div>' +
        '<a class="btn ' + (f.pret ? 'btn-primary' : 'btn-secondary') + '" href="mes-documents.dc.html" style="flex:0 0 auto;font-size:17px">' +
          (f.pret ? 'Ouvrir' : 'Voir le détail') + '</a>' +
      '</div>';
    }).join('');
    section.hidden = false;
  })();

  /* Vue « adaptation à l'autonomie » : subvention travaux, service AMO et
     prestations à demander ailleurs (APA, PCH) selon le profil. */
  if (type === 'autonomie'){
    var detailMpa = document.getElementById('mpa-detail');
    if (detailMpa) detailMpa.hidden = false;
    var aideMpa = r.aide || {};
    var montantMpa = aideMpa.travaux || aideMpa.total || 0;
    var elMpa = document.getElementById('mpa-travaux-amount');
    if (elMpa) elMpa.textContent = montantMpa > 0 ? eur(montantMpa) : '— €';
    var btnMpa = document.querySelector('#mpa-detail [data-depot="mpa"]');
    if (btnMpa) btnMpa.setAttribute('data-aid-amount', String(Math.round(montantMpa)));
    var profMpa = dossier.profile || {};
    if ((Number(profMpa.age) || 0) >= 60){
      var apa = document.querySelector('#mpa-detail [data-aid="apa"]');
      if (apa) apa.hidden = false;
    }
    if (profMpa.handicap === 'oui_50plus' || profMpa.handicap === 'oui_pch'){
      var pch = document.querySelector('#mpa-detail [data-aid="pch"]');
      if (pch) pch.hidden = false;
    }
  }

  // Vue « habitat dégradé » : empilement détaillé, aide par aide.
  if (type === 'indigne'){
    var detail = document.getElementById('lhi-detail');
    if (detail) detail.hidden = false;
    var a = r.aide || {};
    // Montant absent du moteur : « — € » plutôt qu'un 0 € trompeur.
    var put = function(id, v){
      var e = document.getElementById(id);
      if (e) e.textContent = (v > 0) ? eur(v) : '— €';
    };
    put('lhi-mpld-amount', a.totalApresEcretement || a.total || a.base || 0);
    put('lhi-mpr-amount', a.mprCumulable || 0);
    put('lhi-regional-amount', a.local || 0);
    if (a.ecoPtz){
      var ptzEl = document.getElementById('lhi-ptz-amount');
      if (ptzEl) ptzEl.textContent = eur(a.ecoPtz);
    }
    var setBtnAmount = function(key, v){
      var b = document.querySelector('#lhi-detail [data-depot="' + key + '"]');
      if (b) b.setAttribute('data-aid-amount', String(Math.round(v || 0)));
    };
    setBtnAmount('mpld', a.totalApresEcretement || a.total || a.base || 0);
    setBtnAmount('mpr', a.mprCumulable || 0);
    var variant = r.variant || (dossier.profile && dossier.profile.variant) || 'occupant';
    var alerte = document.querySelector('#lhi-detail .lhi-alert[data-variant="' + variant + '"]');
    if (alerte) alerte.hidden = false;
  }

  // Widget sidebar : il doit parler du dossier ouvert, pas du dernier diagnostic
  // énergétique stocké dans le profil.
  if (type !== 'energetique'){
    var set = function(id, v){ var e = document.getElementById(id); if (e) e.textContent = v; };
    set('rf-aides-val', total > 0 ? eur(total) : '— €');
    var cout = 0;
    // coutEstime (MPA) et coutHT (LHI) sont des montants HT : conversion avant
    // affichage sous l'étiquette TTC. totalTTC prime quand il existe.
    var tv = r.travaux || {};
    cout = tv.totalTTC || Math.round((tv.coutEstime || tv.coutHT || 0) * 1.055);
    set('rf-aides-sub', cout > 0 ? 'sur ' + eur(cout) + ' TTC' : 'Estimation indicative');
  }
}
// Le widget sidebar est réécrit au DOMContentLoaded par le script de bascule :
// on passe après lui, sinon le dossier ouvert est écrasé par le profil.
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', adaptToOpenDossier);
else adaptToOpenDossier();

pages/mes-aides/11.js:
/* Ajoute « Voir la fiche complète » vers le glossaire sur chaque card d'aide. */
(function(){
  var MAP = {
    mpr:'mpr-geste', cee:'cee', local:'climaxion', tva:'tva-55', eptz:'eco-ptz',
    'mpa-travaux':'mpa-travaux', apa:'apa', pch:'pch', 'amo-mpa':'amo-mpa',
    mpld:'mpld', 'mpr-cumulable':'mpr-geste', 'eco-ptz':'eco-ptz',
    'regional-lhi':'habiter-mieux-grand-est', audit:'audit-lhi', amo:'amo-lhi'
  };
  function decorate(){
    document.querySelectorAll('article.aid').forEach(function(card){
      if (card.querySelector('.rf-gloss-link')) return;
      var anchor = MAP[card.getAttribute('data-key') || card.getAttribute('data-aid') || ''];
      if (!anchor) return;
      var actions = card.querySelector('.aid-actions');
      if (!actions) {
        actions = document.createElement('div');
        actions.className = 'aid-actions';
        actions.style.cssText = 'display:flex;gap:8px;flex-wrap:wrap;padding:0 22px 18px';
        card.appendChild(actions);
      }
      var a = document.createElement('a');
      a.className = 'rf-gloss-link';
      a.href = 'glossaire-aides.dc.html#' + anchor;
      a.textContent = 'Voir la fiche complète ↗';
      a.style.cssText = 'align-self:center;font:600 17px/1 inherit;color:var(--teal-700);text-decoration:none';
      a.addEventListener('mouseenter', function(){ a.style.textDecoration = 'underline'; });
      a.addEventListener('mouseleave', function(){ a.style.textDecoration = 'none'; });
      actions.appendChild(a);
    });
  }
  var pending = false;
  function schedule(){ if (pending) return; pending = true; requestAnimationFrame(function(){ pending = false; decorate(); }); }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', schedule); else schedule();
  new MutationObserver(schedule).observe(document.body, {childList:true, subtree:true});
})();

