/* Copilote de parcours — peuple le bloc #rf-admin quand un dossier est ouvert.
   Sans dossier, le bloc reste masqué et la page garde son catalogue transversal. */
(function initAdminCopilote(){
  'use strict';
  if (!window.RFDossiers) return;

  function openDossier(){
    try {
      var id = new URLSearchParams(location.search).get('dossier');
      if (id){ var byId = RFDossiers.getById(id); if (byId) return byId; }
      var actifs = (RFDossiers.getActifs && RFDossiers.getActifs()) || [];
      return actifs.length ? actifs[actifs.length - 1] : null;
    } catch (e){ return null; }
  }

  var dossier = openDossier();
  var root = document.getElementById('rf-admin');
  if (!dossier || !dossier.type || !root) return;

  var esc = function(s){ return String(s == null ? '' : s).replace(/[&<>"]/g, function(c){ return ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'})[c]; }); };
  var setTxt = function(id, v){ var el = document.getElementById(id); if (el) el.textContent = v; };
  var eur = function(n){ return Math.round(Number(n) || 0).toLocaleString('fr-FR') + ' €'; };

  document.body.classList.add('rf-admin-type-' + dossier.type);
  root.classList.add('is-on');

  var timeline = RFDossiers.getTimeline(dossier);
  var currentIdx = RFDossiers.getCurrentStepIndex(dossier);
  var step = timeline[currentIdx];
  var adresse = (dossier.profile && dossier.profile.logement && dossier.profile.logement.adresse) || '';

  var r = (window.rfResolveDossierResult ? window.rfResolveDossierResult(dossier) : dossier.result) || {};
  var totalAides = (window.rfTotalDossier && window.rfTotalDossier(dossier, r)) || RFDossiers.totalAides(dossier) || 0;

  /* ── Hero ── */
  var greetEl = document.getElementById('rf-admin-greeting');
  if (greetEl && window.RFUser) greetEl.textContent = RFUser.getGreeting();
  setTxt('rf-hero-type', RFDossiers.meta(dossier.type).titre);
  setTxt('rf-hero-adresse', adresse ? '· ' + adresse : '');
  setTxt('rf-hero-aides', totalAides ? eur(totalAides) : '—');
  setTxt('rf-hero-step', currentIdx + ' / ' + timeline.length);

  /* ── Mini-stepper ── */
  var stepper = document.getElementById('rf-stepper');
  if (stepper){
    stepper.innerHTML = timeline.map(function(s, idx){
      var status = idx < currentIdx ? 'done' : (idx === currentIdx ? 'current' : 'pending');
      var short = s.court || s.libelle.split(' ')[0];
      return '<div class="rf-step rf-step--' + status + '">' +
        '<span class="rf-step__badge">' + (status === 'done' ? '✓' : (idx + 1)) + '</span>' +
        '<span class="rf-step__label">' + esc(short) + '</span></div>';
    }).join('');
    var cur = stepper.querySelector('.rf-step--current');
    if (cur && stepper.scrollWidth > stepper.clientWidth) stepper.scrollLeft = Math.max(0, cur.offsetLeft - stepper.clientWidth / 2 + cur.offsetWidth / 2);
  }

  /* ── Card action immédiate ── */
  if (step){
    setTxt('rf-next-num', currentIdx + 1);
    setTxt('rf-next-title', step.libelle);
    setTxt('rf-next-desc', step.description || step.action || '');
    var dw = document.getElementById('rf-next-delai-wrap');
    if (dw){ dw.hidden = !step.delai; setTxt('rf-next-delai', step.delai || ''); }
    var uw = document.getElementById('rf-next-duree-wrap');
    if (uw){ uw.hidden = !step.duree; setTxt('rf-next-duree', step.duree || ''); }
    var tips = document.getElementById('rf-next-tips');
    var tipsList = document.getElementById('rf-next-tips-list');
    if (tips && tipsList){
      if (step.tips && step.tips.length){
        tips.hidden = false;
        tipsList.innerHTML = step.tips.map(function(t){ return '<li>' + esc(t) + '</li>'; }).join('');
      } else { tips.hidden = true; }
    }
    var cta = document.getElementById('rf-next-cta');
    if (cta){
      if (step.cta && step.href){
        cta.hidden = false;
        cta.textContent = step.cta;
        cta.href = step.href;
        if (/^https?:/.test(step.href)){ cta.target = '_blank'; cta.rel = 'noopener'; }
      } else { cta.hidden = true; }
    }
    var markDone = document.getElementById('rf-mark-done');
    if (markDone){
      markDone.hidden = currentIdx >= timeline.length - 1;
      markDone.addEventListener('click', function(){
        try { RFDossiers.advanceEtape(dossier.id); } catch (e){}
        location.reload();
      });
    }
  }

  /* ── Checklist ── */
  var host = document.getElementById('rf-checklist');
  if (host){
    setTxt('rf-check-done', currentIdx);
    setTxt('rf-check-total', timeline.length);
    host.innerHTML = timeline.map(function(s, idx){
      var status = idx < currentIdx ? 'done' : (idx === currentIdx ? 'current' : 'pending');
      var badge = status === 'done' ? 'Fait' : (status === 'current' ? 'En cours' : 'À venir');
      var mark = status === 'done' ? '✓' : (status === 'current' ? '●' : '');
      return '<div class="rf-check__item rf-check__item--' + status + '">' +
        '<span class="rf-check__box">' + mark + '</span>' +
        '<span class="rf-check__label">' + esc(s.libelle) + '</span>' +
        '<span class="rf-check__badge">' + badge + '</span></div>';
    }).join('');
  }

  /* ── Documents attendus ── */
  var docHost = document.getElementById('rf-admin-doc-list');
  if (docHost){
    var docs = (RFDossiers.getDocumentsAttendus(dossier) || []).slice(0, 4);
    docHost.innerHTML = docs.length ? docs.map(function(doc){
      return '<div class="rf-admin-doc">' +
        '<div class="rf-admin-doc__ico">DOC</div>' +
        '<div><div class="rf-admin-doc__name">' + esc(doc.libelle) + '</div>' +
        '<div class="rf-admin-doc__for">' + (doc.obligatoire ? 'Pièce obligatoire' : 'Pièce complémentaire') + '</div></div>' +
        '<a class="rf-admin-doc__cta" href="mes-documents.dc.html?dossier=' + encodeURIComponent(dossier.id) + '">Téléverser</a>' +
      '</div>';
    }).join('') : '<p style="color:var(--slate-500);font-size:17px;margin:0">Aucune pièce à fournir pour l\'instant.</p>';
  }

  /* ── Récap ── */
  var coutTTC = (r.travaux && (r.travaux.totalTTC || r.travaux.coutEstime)) || r.coutTravaux || r.totalTravaux || 0;
  setTxt('rf-summary-adresse', adresse || '—');
  setTxt('rf-summary-aides', totalAides ? eur(totalAides) : '—');
  setTxt('rf-summary-reste', coutTTC ? eur(Math.max(0, coutTTC - totalAides)) : 'À chiffrer avec vos devis');
  setTxt('rf-summary-partenaire', (dossier.partenaire && dossier.partenaire.nom)
    || (dossier.transmisLe ? 'Accompagnateur agréé — désignation en cours' : 'Non transmis'));
})();

