const PROFILE_KEY = 'junglerenov.profile';
function get(){ try { return JSON.parse(localStorage.getItem(PROFILE_KEY) || '{}'); } catch { return {}; } }
function save(patch){
  const next = { ...get(), ...patch, updatedAt: Date.now() };
  localStorage.setItem(PROFILE_KEY, JSON.stringify(next));
  return next;
}
function toast(msg){
  const t = document.getElementById('toast');
  t.textContent = msg;
  t.classList.add('show');
  setTimeout(() => t.classList.remove('show'), 2400);
}
function toggleBlock(head){ head.parentElement.classList.toggle('open'); }

// Tile single-select dans chaque bloc
document.querySelectorAll('[data-r]').forEach(t => {
  t.addEventListener('click', () => {
    const grp = t.dataset.r;
    document.querySelectorAll(`[data-r="${grp}"]`).forEach(x => x.classList.remove('selected'));
    t.classList.add('selected');
  });
});

// Pré-remplissage
function prefill(){
  const p = get();
  // Localisation Grand Est (lecture seule — modifiable via la simulation)
  const EPCI_LABELS = (window.RFCompute && window.RFCompute.EPCI_GRAND_EST) || {};
  const DEPT_LABELS = (window.RFCompute && window.RFCompute.DEPTS_GRAND_EST) || {};
  const setTxt = (id, v) => { const el = document.getElementById(id); if (el) el.textContent = v || '—'; };
  const lg = p.logement || {};
  setTxt('p-dept', lg.dept ? (DEPT_LABELS[lg.dept] ? lg.dept + ' — ' + DEPT_LABELS[lg.dept] : lg.dept) : null);
  setTxt('p-epci', lg.epci ? (EPCI_LABELS[lg.epci] ? EPCI_LABELS[lg.epci].nom : lg.epci) : null);
  setTxt('p-dpe',  lg.dpeCurrent || lg.dpe || null);
  if (p.address) document.getElementById('p-addr').value = p.address;
  if (p.logement){
    if (p.logement.type) document.querySelectorAll('[data-r="type"]').forEach(t => t.classList.toggle('selected', t.dataset.v === p.logement.type));
    if (p.logement.surface) document.getElementById('p-surf').value = p.logement.surface;
    if (p.logement.year) document.getElementById('p-year').value = p.logement.year;
    if (p.logement.heat) document.querySelectorAll('[data-r="heat"]').forEach(t => t.classList.toggle('selected', t.dataset.v === p.logement.heat));
  }
  if (p.situation){
    if (p.situation.status) document.querySelectorAll('[data-r="status"]').forEach(t => t.classList.toggle('selected', t.dataset.v === p.situation.status));
    if (p.situation.priorite) document.querySelectorAll('[data-r="prio"]').forEach(t => t.classList.toggle('selected', t.dataset.v === p.situation.priorite));
  }
  if (p.foyer){
    if (p.foyer.rfr) document.getElementById('p-rfr').value = p.foyer.rfr.toLocaleString('fr-FR') + ' €';
    if (p.foyer.parts){
      const sel = document.getElementById('p-parts');
      sel.selectedIndex = Math.max(0, Math.min(5, p.foyer.parts - 1));
    }
    if (p.foyer.region) document.getElementById('p-region').value = p.foyer.region;
  }
  if (p.travaux){
    document.querySelectorAll('#works input').forEach(c => { c.checked = p.travaux.includes(c.value); });
  }
  // Account
  if (p.email) document.getElementById('ac-email').textContent = p.email;
  // Sidebar identité
  if (p.firstname || p.lastname){
    const fn = p.firstname || '';
    const ln = p.lastname || '';
    // La sidebar de cette page utilise les ids rf-* (comme le dashboard).
    const meName = document.getElementById('rf-me-name');
    const meAv   = document.getElementById('rf-me-av');
    if (meName) meName.textContent = (fn + ' ' + ln).trim() || 'Mon compte';
    if (meAv)   meAv.textContent = ((fn[0] || '?') + (ln[0] || '')).toUpperCase();
  }
  // Summary card
  if (p.aids && p.aids.travaux){
    const sh = document.getElementById('sum-h');
    const ss = document.getElementById('sum-s');
    if (sh) sh.textContent = 'Aides estimées : ' + Math.round(p.aids.totalAides || 0).toLocaleString('fr-FR') + ' €';
    if (ss) ss.textContent = 'Sur un projet estimé de ' + Math.round(p.aids.travaux.totalTTC || 0).toLocaleString('fr-FR') + ' € TTC';
  }
}

/* ───── Garde-fou modification post-signature ─────
   Si l'utilisateur a déjà signé électroniquement un dossier MPR/CEE, on
   l'avertit que modifier ses données ne mettra PAS à jour ce dossier (le
   PDF signé reste figé via signedSnapshots[]). Il peut quand même corriger
   une typo ou contacter le support pour faire un avenant. */
function checkPostSignatureWarning(block){
  const impactsDossiers = ['logement', 'foyer', 'travaux'];
  if (!impactsDossiers.includes(block)) return true; // pas de warning
  const cur = get();
  const signed = Array.isArray(cur.signedDossiers) ? cur.signedDossiers : [];
  // Filtre les helpers (tva, eptz) — eux ne sont jamais "signés", seuls mpr/cee comptent
  const signedMandates = signed.filter(id => id === 'mpr' || id === 'cee');
  if (signedMandates.length === 0) return true; // aucun dossier impacté

  const names = { mpr: "MaPrimeRénov'", cee: 'CEE (Prime énergie)' };
  const list = signedMandates.map(id => names[id] || id).join(' et ');
  const what = { logement: 'adresse / surface du logement', foyer: 'revenus du foyer', travaux: 'liste des travaux' }[block];

  const msg =
    "Modification après signature\n\n" +
    "Vous avez signé électroniquement votre dossier " + list + ".\n\n" +
    "Modifier votre " + what + " ne mettra PAS à jour ce dossier. " +
    "Le PDF signé reste figé tel quel pour conserver sa valeur légale.\n\n" +
    "• Si c'est une correction mineure (typo, oubli) : cliquez OK.\n" +
    "• Si vous avez déménagé, changé de revenus ou ajouté des travaux : " +
    "contactez le support pour faire un avenant (contact@junglerenov.fr).\n\n" +
    "Confirmer la modification ?";
  return confirm(msg);
}

// Enregistrement par bloc
document.querySelectorAll('[data-save]').forEach(btn => {
  btn.addEventListener('click', () => {
    const block = btn.dataset.save;
    if (!checkPostSignatureWarning(block)) {
      toast('Modification annulée.');
      return;
    }
    const cur = get();
    if (block === 'logement'){
      save({
        address: document.getElementById('p-addr').value || cur.address,
        logement: {
          ...(cur.logement || {}),
          type:    document.querySelector('[data-r="type"].selected')?.dataset.v || cur.logement?.type,
          surface: +document.getElementById('p-surf').value || cur.logement?.surface,
          year:    +document.getElementById('p-year').value || cur.logement?.year,
          heat:    document.querySelector('[data-r="heat"].selected')?.dataset.v || cur.logement?.heat,
        },
      });
    }
    if (block === 'situation'){
      save({
        situation: {
          ...(cur.situation || {}),
          status:   document.querySelector('[data-r="status"].selected')?.dataset.v || cur.situation?.status,
          priorite: document.querySelector('[data-r="prio"].selected')?.dataset.v   || cur.situation?.priorite,
        },
      });
    }
    if (block === 'foyer'){
      const rfr = +(document.getElementById('p-rfr').value || '').replace(/\D/g,'') || cur.foyer?.rfr;
      const partsIdx = document.getElementById('p-parts').selectedIndex;
      save({
        foyer: {
          ...(cur.foyer || {}),
          rfr,
          parts: partsIdx + 1,
          region: document.getElementById('p-region').value,
        },
      });
    }
    if (block === 'travaux'){
      const works = [...document.querySelectorAll('#works input:checked')].map(c => c.value);
      save({ travaux: works });
    }
    // ───── Recalcul automatique des aides si paramètre impactant changé ─────
    // Blocs qui modifient le calcul : logement (surface/heat), foyer (rfr/parts/region),
    // travaux (sélection). Situation (status/priorité) est informatif.
    const impactsAids = ['logement', 'foyer', 'travaux', 'situation'];
    let newTotal = null;
    let oldTotal = null;
    if (impactsAids.includes(block) && window.RFCompute){
      try {
        oldTotal = (get().aids && get().aids.totalAides) || 0;
        const recomputed = window.RFCompute.recomputeFromProfile();
    /* Le recalcul peut changer les mises en garde (nouveau territoire, nouveaux revenus) : on les montre. */
    if (window.RFAlertes && recomputed){
      try {
        let box = document.getElementById('rf-alertes');
        if (!box){
          box = document.createElement('div'); box.id = 'rf-alertes';
          const main = document.querySelector('main') || document.body;
          main.insertBefore(box, main.firstChild);
        }
        RFAlertes.rendre(recomputed, box);
      } catch (e) { console.warn('Alertes :', e); }
    }
        // Patch le profil avec les nouvelles aides
        save({ aids: recomputed });
        newTotal = recomputed.totalAides;
        // Rafraîchit les widgets sidebar (rf-aides-val) + carte résumé (sum-h)
        if (typeof window.RFRefreshWidgets === 'function') window.RFRefreshWidgets();
      } catch(e){ console.warn('Recalcul aides après save :', e); }
    }

    // Toast contextuel
    const fmt = n => Math.round(n).toLocaleString('fr-FR') + ' €';
    if (newTotal !== null){
      const diff = newTotal - oldTotal;
      const arrow = diff > 0 ? '↑' : (diff < 0 ? '↓' : '=');
      const signed = (diff > 0 ? '+' : '') + fmt(diff).replace(' €', ' €');
      toast('Aides recalculées : ' + fmt(newTotal) + ' (' + arrow + ' ' + signed + ')');
    } else {
      toast('Modifications enregistrées.');
    }
    prefill();
  });
});

document.getElementById('reset-dossier').addEventListener('click', () => {
  if (!confirm("Refaire votre simulation ?\n\nVos données de diagnostic (logement, foyer, travaux, aides estimées) seront effacées et vous serez redirigé(e) vers le parcours diagnostic.\n\nVos dossiers, vos pièces téléversées et vos signatures électroniques sont conservés.")){
    return;
  }
  // Reset PARTIEL : on conserve identité, signatures, statuts de pièces.
  // On efface uniquement ce qui relève de la simulation diagnostic.
  const cur = get();
  const preserved = {
    // Identité (sera redemandée mais utile au cas où l'utilisateur ne refait pas tout)
    firstname:           cur.firstname,
    lastname:            cur.lastname,
    email:               cur.email,
    // Documents/signatures (l'utilisateur ne perd pas son travail)
    signatures:          cur.signatures,
    signedDossiers:      cur.signedDossiers,
    statutPieces:        cur.statutPieces,
    // Marqueur de reset
    simulationResetAt:   new Date().toISOString(),
    updatedAt:           Date.now(),
  };
  // Supprimer les clés undefined pour rester propre dans localStorage
  Object.keys(preserved).forEach(k => preserved[k] === undefined && delete preserved[k]);
  localStorage.setItem(PROFILE_KEY, JSON.stringify(preserved));
  toast('Simulation réinitialisée. Redirection…');
  setTimeout(() => { location.href = 'onboarding-diagnostic.dc.html'; }, 1000);
});

/* Statut du dossier — il n'y a plus ni abonnement ni échéance : ce qui
   pilote le parcours est l'état administratif du dossier transmis. */
function renderDossierStatus(){
  const el = document.getElementById('ac-sub-status');
  const elP = document.getElementById('ac-partenaire');
  let dernier = null;
  try {
    const actifs = (window.RFDossiers && RFDossiers.getActifs && RFDossiers.getActifs()) || [];
    dernier = actifs.length ? actifs[actifs.length - 1] : null;
  } catch (e) {}
  if (!el) return;
  if (!dernier){
    el.innerHTML = '<span style="color:var(--slate-500)">Diagnostic en cours — aucun dossier transmis</span>';
    if (elP) elP.textContent = '—';
    return;
  }
  const statut = (window.RFTransmission && RFTransmission.libelleStatut(dernier.statutDossier)) || 'Dossier créé';
  el.innerHTML = '<span style="color:var(--success-600)">' + statut + '</span>'
    + (dernier.transmisLe ? ' · depuis le ' + RFDossiers.fmtDate(dernier.transmisLe) : '');
  if (elP) elP.textContent = (dernier.partenaire && dernier.partenaire.nom)
    || (dernier.transmisLe ? 'Désignation en cours' : '—');
}

/* Retrait du consentement (RGPD art. 7-3) : la transmission est stoppée,
   le compte et les données restent en place. */
const revokeBtn = document.getElementById('revoke-transmission');
if (revokeBtn) revokeBtn.addEventListener('click', () => {
  let actifs = [];
  try { actifs = (window.RFDossiers && RFDossiers.getActifs()) || []; } catch (e) {}
  if (!actifs.length){ toast("Aucun dossier n'a été transmis."); return; }
  if (!confirm("Retirer votre consentement à la transmission ?\n\n"
    + "Votre accompagnateur cessera de traiter votre dossier. Vos données restent dans votre espace, "
    + "et vous pourrez transmettre à nouveau plus tard.")) return;
  try {
    const all = RFDossiers.loadAll();
    all.forEach(d => {
      if (!d.transmisLe) return;
      d.consentementTransmission = Object.assign({}, d.consentementTransmission, {
        retireLe: new Date().toISOString(),
      });
      d.statutDossier = 'complet';
    });
    RFDossiers.saveAll(all);
  } catch (e) { console.warn('Retrait de consentement :', e); }
  toast('Consentement retiré. Votre accompagnateur en est informé.');
  renderDossierStatus();
});

// Appel sécurisé : une erreur ici ne doit pas casser la page
try { renderDossierStatus(); } catch(e){ console.warn('renderDossierStatus :', e); }

