/* JungleRenov — bindings sidebar canonique (lit junglerenov.profile écrit par la simulation) */
(function(){
  const KEY = 'junglerenov.profile';
  function readData(){
    try { return JSON.parse(localStorage.getItem(KEY) || '{}'); }
    catch { return {}; }
  }
  function fmtEUR(n){
    if (n == null || isNaN(n)) return '—';
    return new Intl.NumberFormat('fr-FR').format(Math.round(n)) + ' €';
  }
  function refresh(){
    const d = readData();
    const aids = d.aids || {};
    const trav = aids.travaux || {};

    // Widget aides estimées (sidebar)
    const valEl = document.getElementById('rf-aides-val');
    const subEl = document.getElementById('rf-aides-sub');
    const total = aids.totalAides || aids.total || null;
    const projet = trav.totalTTC || aids.coutTotalTTC || null;
    if (valEl){
      if (total){
        valEl.textContent = fmtEUR(total);
        if (subEl) subEl.textContent = projet ? 'sur ' + fmtEUR(projet) + ' TTC' : 'Estimation indicative';
      } else {
        valEl.textContent = '—';
        if (subEl) subEl.textContent = 'Simulation à compléter';
      }
    }

    // Carte de résumé en haut de page (sum-h / sum-s)
    const sumH = document.getElementById('sum-h');
    const sumS = document.getElementById('sum-s');
    if (sumH && sumS){
      if (total){
        sumH.textContent = 'Aides estimées : ' + fmtEUR(total);
        sumS.textContent = projet
          ? 'Sur un projet estimé de ' + fmtEUR(projet) + ' TTC. Modifiez vos infos ci-dessous pour recalculer.'
          : 'Estimation indicative. Modifiez vos infos ci-dessous pour recalculer.';
      } else {
        sumH.textContent = 'Aides estimées : à calculer';
        sumS.textContent = 'Lancez votre simulation pour estimer vos aides.';
      }
    }

    // Profil utilisateur en bas
    const nameEl = document.getElementById('rf-me-name');
    const planEl = document.getElementById('rf-me-plan');
    const avEl = document.getElementById('rf-me-av');
    const fn = (d.firstname || '').trim();
    const ln = (d.lastname || '').trim();
    const fullName = (fn + ' ' + ln).trim();
    /* Le badge porte le statut du dossier, jamais une formule commerciale. */
    let planTxt = '';
    try {
      const actifs = (window.RFDossiers && RFDossiers.getActifs && RFDossiers.getActifs()) || [];
      if (actifs.length){
        const dernier = actifs[actifs.length - 1];
        const statut = (window.RFTransmission && RFTransmission.libelleStatut(dernier.statutDossier)) || 'Dossier créé';
        const nomPart = dernier.partenaire && dernier.partenaire.nom;
        planTxt = nomPart ? statut + ' · ' + nomPart : statut;
      } else {
        planTxt = 'Diagnostic en cours';
      }
    } catch (e) { planTxt = ''; }
    if (nameEl) nameEl.textContent = fullName || 'Mon compte';
    if (planEl) planEl.textContent = planTxt || '—';
    if (avEl){
      if (fullName){
        const initials = ((fn[0]||'') + (ln[0]||'')).toUpperCase() || 'RF';
        avEl.textContent = initials;
      } else {
        avEl.textContent = 'RF';
      }
    }
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', refresh);
  else refresh();
  window.addEventListener('storage', refresh);
  // Expose pour les autres scripts (save handlers du bloc édition)
  window.RFRefreshWidgets = refresh;
})();

