/* JungleRenov — tableau des dossiers (un achat = un dossier, suivi 12 mois) */
(function(){
  var host = document.getElementById('dos-table-host');
  if (!host || !window.RFDossiers) return;
  var dossiers = RFDossiers.getAll().filter(function(d){ return d.status !== 'brouillon'; });
  if (!dossiers.length){
    host.innerHTML = '<p class="dos-empty">Aucun dossier ouvert pour le moment. ' +
      '<a href="choix-parcours.dc.html">Démarrer un dossier</a></p>';
    return;
  }
  host.innerHTML = '<table class="dos-table"><thead><tr>' +
      '<th>Type</th><th>Créé le</th><th>Statut</th><th>Accompagnateur</th><th>Aides estimées</th><th></th>' +
    '</tr></thead><tbody>' +
    dossiers.map(function(dos){
      var meta = RFDossiers.meta(dos.type);
      var statut = (window.RFTransmission && RFTransmission.libelleStatut(dos.statutDossier)) || 'Dossier créé';
      var part = (dos.partenaire && dos.partenaire.nom) || (dos.transmisLe ? 'Désignation en cours' : '—');
      return '<tr>' +
        '<td style="color:' + meta.color + ';font-weight:600">' + meta.court + '</td>' +
        '<td>' + RFDossiers.fmtDate(dos.createdAt) + '</td>' +
        '<td><span class="dos-badge actif">' + statut + '</span></td>' +
        '<td>' + part + '</td>' +
        '<td class="num">' + Math.round(RFDossiers.totalAides(dos)).toLocaleString('fr-FR') + ' €</td>' +
        '<td><a href="' + meta.detail + '?dossier=' + encodeURIComponent(dos.id) + '">Ouvrir</a></td>' +
      '</tr>';
    }).join('') +
    '</tbody></table>';
})();

