/* JungleRenov — rend le widget profil de sidebar cliquable et ajoute Déconnexion */
(function(){
  function init(){
    var me = document.querySelector('.sidebar .me, aside .me');
    if (!me) return;
    me.style.cursor = 'pointer';
    me.style.position = 'relative';
    var menu = document.createElement('div');
    menu.style.cssText = 'display:none;position:absolute;bottom:calc(100% + 6px);left:0;right:0;background:#FFFFFF;border:1px solid #E9E3D3;border-radius:6px;box-shadow:none;padding:6px;z-index:50;font-size:17px';
    menu.innerHTML =
      '<a href="mon-profil.dc.html" style="display:flex;align-items:center;gap:8px;padding:9px 12px;border-radius:6px;color:#123A2E;text-decoration:none">' +
        '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="12" cy="8" r="4"/><path d="M4 21c0-4 4-7 8-7s8 3 8 7"/></svg>' +
        'Mon profil' +
      '</a>' +
      '<div style="height:1px;background:#E9E3D3;margin:4px 0"></div>' +
      '<a href="#" id="rf-side-logout" style="display:flex;align-items:center;gap:8px;padding:9px 12px;border-radius:6px;color:#991B1B;text-decoration:none">' +
        '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"/><path d="m16 17 5-5-5-5"/><path d="M21 12H9"/></svg>' +
        'Se déconnecter' +
      '</a>';
    me.appendChild(menu);
    me.addEventListener('click', function(e){
      if (e.target.closest('a')) return;
      menu.style.display = menu.style.display === 'none' ? 'block' : 'none';
    });
    document.addEventListener('click', function(e){
      if (!e.target.closest('.me')) menu.style.display = 'none';
    });
    var logoutLink = document.getElementById('rf-side-logout');
    if (logoutLink){
      logoutLink.addEventListener('click', function(e){
        e.preventDefault();
        if (window.RFStore) RFStore.logout();
        else {
          ['junglerenov.session','junglerenov.profile'].forEach(function(k){ try{localStorage.removeItem(k);}catch{} });
        }
        window.location.href = 'login.dc.html';
      });
    }
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();
})();

pages/mon-profil/06.js:
/* ══ Profil polymorphique ═════════════════════════════════════════
   La page a été écrite pour le tunnel énergétique, qui persiste
   junglerenov.profile. Un dossier MPA ou LHI ne vit que dans RFDossiers :
   sans ce bloc, l'utilisateur voit les valeurs par défaut énergétiques.
   Ce script tourne en dernier (après _dossiers.js et _compute_aids.js) et
   n'intervient QUE lorsqu'un dossier non énergétique est ouvert. */
(function(){
  var eur = function(n){ return Math.round(Number(n) || 0).toLocaleString('fr-FR') + ' €'; };

  function resolveActiveDossier(){
    try {
      if (!window.RFDossiers) return null;
      var id = new URLSearchParams(location.search).get('dossier');
      if (id){
        var byId = RFDossiers.getById(id);
        if (byId) return byId;
      }
      var actifs = (RFDossiers.getActifs && RFDossiers.getActifs()) || [];
      if (!actifs.length) return null;
      actifs.sort(function(a, b){ return new Date(b.transmisLe || 0) - new Date(a.transmisLe || 0); });
      return actifs[0];
    } catch (_) { return null; }
  }

  function resultatDe(dos){
    if (!dos) return null;
    var r = dos.result;
    var peuple = r && (r.totalAides > 0 || (r.aide && (r.aide.total > 0 || r.aide.totalApresEcretement > 0)));
    if (peuple) return r;
    var C = window.RFCompute;
    if (!C || !dos.profile) return r || null;
    try {
      if (dos.type === 'autonomie' && C.computeMprAdapt) return C.computeMprAdapt(dos.profile);
      if (dos.type === 'indigne' && C.computeMprLogementDecent) return C.computeMprLogementDecent(dos.profile);
    } catch (e) { console.warn('[mon-profil] recalcul :', e); }
    return r || null;
  }

  function totalDe(dos, r){
    r = r || resultatDe(dos);
    if (!r) return 0;
    if (r.totalAides > 0) return r.totalAides;
    if (r.aids && r.aids.totalAides > 0) return r.aids.totalAides;
    if (r.aide){
      if (dos && dos.type === 'indigne'){
        // Même définition que RFDossiers.totalAides : MPLD + cumulables, hors
        // prêt éco-PTZ et hors services pris en charge par l'Anah.
        var socle = r.aide.totalApresEcretement || r.aide.total || 0;
        return socle + (r.aide.mprCumulable || 0) + (r.aide.local || 0);
      }
      return r.aide.totalApresEcretement || r.aide.total || 0;
    }
    return 0;
  }
  function coutDe(dos, r){
    r = r || resultatDe(dos);
    var t = (r && r.travaux) || {};
    if (t.totalTTC) return t.totalTTC;
    // Dossiers stockés avant l'ajout des alias : coutEstime et coutHT sont HT.
    var ht = t.coutEstime || t.coutHT || 0;
    return ht ? Math.round(ht * 1.055) : 0;
  }

  /* ── Bandeau sidebar : somme de TOUS les dossiers payés, tous types ── */
  function majBandeau(){
    var val = document.getElementById('rf-aides-val');
    var sub = document.getElementById('rf-aides-sub');
    if (!val || !window.RFDossiers) return;
    var actifs = (RFDossiers.getActifs && RFDossiers.getActifs()) || [];
    if (!actifs.length) return; // le binding historique (profil) garde la main
    var aides = 0, cout = 0;
    actifs.forEach(function(d){
      var r = resultatDe(d);
      aides += totalDe(d, r);
      cout += coutDe(d, r);
    });
    if (aides <= 0) return;
    val.textContent = eur(aides);
    if (sub) sub.textContent = cout > 0 ? 'sur ' + eur(cout) + ' TTC' : 'Estimation indicative';
  }

  var dossier = resolveActiveDossier();

  /* Dossier énergétique : le profil stocké dans le dossier a la même forme que
     junglerenov.profile, déjà lu par le pré-remplissage historique. On ne rejoue
     donc les champs que lorsqu'un dossier précis est ciblé par l'URL — utile
     quand l'utilisateur a plusieurs dossiers énergétiques et que le profil global
     ne reflète que le dernier. */
  function prefillEnergetique(dos){
    var p = dos.profile || {};
    var lg = p.logement || {};
    var setVal = function(id, v){ var e = document.getElementById(id); if (e && v != null && v !== '') e.value = v; };
    if (p.address) setVal('p-addr', p.address);
    setVal('p-surf', lg.surface || '');
    setVal('p-year', lg.year || lg.annee || '');
    if (lg.type) document.querySelectorAll('[data-r="type"]').forEach(function(t){
      t.classList.toggle('selected', t.dataset.v === lg.type);
    });
    if (lg.heat) document.querySelectorAll('[data-r="heat"]').forEach(function(t){
      t.classList.toggle('selected', t.dataset.v === lg.heat);
    });
    var foy = p.foyer || {};
    if (foy.rfr) setVal('p-rfr', Number(foy.rfr).toLocaleString('fr-FR') + ' €');
    if (foy.parts){
      var sel = document.getElementById('p-parts');
      if (sel) sel.selectedIndex = Math.max(0, Math.min(5, Number(foy.parts) - 1));
    }
    if (foy.region){
      var reg = document.getElementById('p-region');
      if (reg) reg.value = foy.region;
    }
    if (Array.isArray(p.travaux)){
      document.querySelectorAll('#works input').forEach(function(cb){
        cb.checked = p.travaux.indexOf(cb.value) !== -1;
      });
    }
    var r = dos.result || p.aids || null;
    if (r && r.totalAides){
      var sumH = document.getElementById('sum-h');
      var sumS = document.getElementById('sum-s');
      var cout = (r.travaux && r.travaux.totalTTC) || 0;
      if (sumH) sumH.textContent = 'Aides estimées : ' + eur(r.totalAides);
      if (sumS && cout) sumS.textContent = 'Sur un projet estimé de ' + eur(cout) + ' TTC';
    }
  }

  /* Liste des travaux : une seule source, _travaux_catalog.js, pour que le
     profil propose exactement ce que le tunnel permet de cocher. Sur un dossier
     habitat dégradé le moteur ne raisonne pas en gestes : on garde un
     récapitulatif en lecture seule plutôt que des cases sans effet. */
  function renderTravaux(type, prof){
    var works = document.getElementById('works');
    if (!works) return;
    var btn = works.parentElement && works.parentElement.querySelector('[data-save="travaux"]');

    if (type === 'indigne'){
      var etats = { tres_degrade: 'Très dégradé', moyennement_degrade: 'Moyennement dégradé',
                    insalubre: 'Insalubre', arrete_police: 'Sous arrêté de police' };
      var lignes = [
        ['État du logement', etats[prof.etatLogement] || prof.etatLogement || '—'],
        ['Coût des travaux estimé', prof.coutTravauxHT ? eur(prof.coutTravauxHT) + ' HT' : '—'],
        ['DPE avant / après', [prof.dpeAvant, prof.dpeApres].filter(function(x){ return x && x !== 'unknown'; }).join(' → ') || '—'],
      ];
      works.style.display = 'block';
      works.innerHTML = lignes.map(function(x){
        return '<div style="display:flex;justify-content:space-between;gap:14px;padding:11px 0;border-bottom:1px solid var(--border);font-size:17px;color:var(--slate-600)">' +
          '<span>' + x[0] + '</span><strong style="font:600 17px var(--font-mono);color:var(--slate-900)">' + x[1] + '</strong></div>';
      }).join('') +
      '<p style="margin:12px 0 0;font-size:17px;color:var(--slate-500);line-height:1.55">Le programme de travaux d\'un dossier habitat dégradé est arrêté avec l\'opérateur spécialisé, à partir de la grille d\'évaluation. Il n\'est pas modifiable ici.</p>';
      if (btn) btn.hidden = true;
      return;
    }

    var cat = window.RFTravauxCatalog;
    if (!cat) return;
    var choisis = prof.travaux || [];
    works.style.display = 'block';
    works.innerHTML = cat.bySection(type).map(function(grp){
      return '<div style="font:600 17px var(--font-mono);color:var(--slate-500);margin:14px 0 8px">' +
          grp.section + '</div>' +
        '<div class="works-grid" style="margin-bottom:0">' +
          grp.items.map(function(t){
            var on = choisis.indexOf(t.id) !== -1;
            return '<label class="work-check"><input type="checkbox" value="' + t.id + '"' + (on ? ' checked' : '') + ' />' +
              '<span>' + t.label +
              (t.hint ? '<span style="display:block;font-size:17px;color:var(--slate-500)">' + t.hint + '</span>' : '') +
              '</span></label>';
          }).join('') +
        '</div>';
    }).join('');
    if (btn) btn.hidden = false;
  }

  /* Enregistrement : écrire dans le dossier ouvert, pas seulement dans le profil
     global, et recalculer son résultat avec le moteur du dispositif. Sans cela le
     dashboard et « Mes aides », qui lisent dossier.result, divergent du profil. */
  function attacherSauvegarde(){
    if (!dossier || !window.RFDossiers) return;
    var sumH = document.getElementById('sum-h');
    var sumS = document.getElementById('sum-s');
    document.querySelectorAll('[data-save]').forEach(function(btn){
      btn.addEventListener('click', function(){
        var bloc = btn.dataset.save;
        var all = RFDossiers.loadAll();
        var ref = null;
        for (var i = 0; i < all.length; i++) if (all[i].id === dossier.id) ref = all[i];
        if (!ref) return;
        var prof = ref.profile || (ref.profile = {});
        var lgp = prof.logement || (prof.logement = {});
        var isEnerg = ref.type === 'energetique';
        var num = function(id){ return Number((document.getElementById(id) || {}).value) || 0; };

        if (bloc === 'logement'){
          var a = (document.getElementById('p-addr') || {}).value;
          if (a){ lgp.adresse = a; if (isEnerg) prof.address = a; }
          var s = num('p-surf');
          if (s){ lgp.surface = s; if ('surface' in prof) prof.surface = s; }
          var y = num('p-year');
          if (y){
            // Le profil énergétique nomme l'année « year », les profils Anah « annee ».
            if (isEnerg) lgp.year = y; else lgp.annee = y;
            if (ref.type === 'indigne') prof.ageLogementAnnees = new Date().getFullYear() - y;
          }
          var t = document.querySelector('[data-r="type"].selected');
          if (t) lgp.type = t.dataset.v;
          var ht = document.querySelector('[data-r="heat"].selected');
          if (ht && isEnerg) lgp.heat = ht.dataset.v;
        }
        if (bloc === 'foyer'){
          var rfr = Number(((document.getElementById('p-rfr') || {}).value || '').replace(/\D/g, '')) || 0;
          var sel2 = document.getElementById('p-parts');
          var reg2 = document.getElementById('p-region');
          if (isEnerg){
            var foy = prof.foyer || (prof.foyer = {});
            if (rfr) foy.rfr = rfr;
            if (sel2) foy.parts = sel2.selectedIndex + 1;
            if (reg2) foy.region = reg2.value;
          } else {
            if (rfr) prof.rfr = rfr;
            if (sel2) prof.foyer = sel2.selectedIndex + 1;
            if (reg2) prof.region = reg2.value;
          }
        }
        // L'habitat dégradé n'a pas de liste de gestes : rien à écrire.
        if (bloc === 'travaux' && ref.type !== 'indigne'){
          prof.travaux = Array.prototype.map.call(
            document.querySelectorAll('#works input:checked'), function(c){ return c.value; });
        }
        RFDossiers.saveAll(all);

        try {
          var C = window.RFCompute, res = null;
          if (ref.type === 'autonomie' && C && C.computeMprAdapt) res = C.computeMprAdapt(prof);
          if (ref.type === 'indigne' && C && C.computeMprLogementDecent) res = C.computeMprLogementDecent(prof);
          if (isEnerg && C && C.compute){
            var lg2 = prof.logement || {}, fo2 = prof.foyer || {};
            res = C.compute({
              surface: Number(lg2.surface) || 0,
              foyer:   Number(fo2.parts) || 1,
              rfr:     Number(fo2.rfr) || 0,
              region:  fo2.region || lg2.region || '',
              heat:    lg2.heat || '',
              dept:    lg2.dept || '',
              selection: prof.travaux || [],
            });
            // Le profil énergétique porte aussi ses aides : on garde les deux alignés.
            prof.aids = res;
            RFDossiers.saveAll(all);
          }
          if (res) RFDossiers.updateResult(ref.id, res);
          dossier = RFDossiers.getById(ref.id) || dossier;
          var nt = totalDe(dossier), nc = coutDe(dossier);
          if (sumH && nt > 0) sumH.textContent = 'Aides estimées : ' + eur(nt);
          if (sumS && nc > 0) sumS.textContent = 'Sur un projet estimé de ' + eur(nc) + ' TTC';
          majBandeau();
        } catch (e) { console.warn('[mon-profil] recalcul après enregistrement :', e); }
      });
    });
  }

  /* Titre et fil d'Ariane : nommer le dispositif réellement ouvert. */
  function adaptTitre(dos){
    if (!dos) return;
    var TITRES = {
      energetique: { h1: 'Mon profil — Rénovation énergétique',  crumb: 'Compte · Mon profil · Rénovation énergétique' },
      autonomie:   { h1: "Mon profil — MaPrimeAdapt'",           crumb: "Compte · Mon profil · MaPrimeAdapt'" },
      indigne:     { h1: 'Mon profil — Ma Prime Logement Décent', crumb: 'Compte · Mon profil · Habitat dégradé' },
    };
    var cfg = TITRES[dos.type] || TITRES.energetique;
    var h1 = document.querySelector('main h1.page-title');
    if (h1) h1.textContent = cfg.h1;
    var crumb = document.querySelector('main .breadcrumb');
    if (crumb) crumb.textContent = cfg.crumb;
  }

  function run(){
    majBandeau();
    adaptTitre(dossier);
    // La liste des travaux est la même que celle du tunnel dans tous les cas,
    // dossier ciblé ou non.
    var profGlobal = {};
    try { profGlobal = JSON.parse(localStorage.getItem('junglerenov.profile') || '{}'); } catch(e){}
    renderTravaux((dossier && dossier.type) || 'energetique',
                  (dossier && dossier.profile) || profGlobal);
    if (!dossier) return;
    if (dossier.type === 'energetique'){
      var cible = null;
      try { cible = new URLSearchParams(location.search).get('dossier'); } catch(e){}
      if (cible) prefillEnergetique(dossier);
      attacherSauvegarde();
      return;
    }

    var p = dossier.profile || {};
    var lg = p.logement || {};
    var r = resultatDe(dossier);

    // Sous-titre : nommer le dispositif réellement concerné
    var lead = document.querySelector('main .lead');
    if (lead){
      lead.textContent = dossier.type === 'autonomie'
        ? "Modifiez vos informations à tout moment. Toute modification déclenche un recalcul de votre aide MaPrimeAdapt'."
        : 'Modifiez vos informations à tout moment. Toute modification déclenche un recalcul de vos aides Ma Prime Logement Décent.';
    }

    // ── Mon logement
    var adr = [lg.adresse, [lg.codePostal, lg.ville].filter(Boolean).join(' ')].filter(Boolean).join(', ');
    var setVal = function(id, v){ var e = document.getElementById(id); if (e && v != null && v !== '') e.value = v; };
    var setTxt = function(id, v){ var e = document.getElementById(id); if (e) e.textContent = v || '—'; };
    if (adr) setVal('p-addr', adr);
    setVal('p-surf', lg.surface || p.surface || '');
    setVal('p-year', lg.annee || '');
    var DEPTS = (window.RFCompute && window.RFCompute.DEPTS_GRAND_EST) || {};
    setTxt('p-dept', lg.dept ? (DEPTS[lg.dept] ? lg.dept + ' — ' + DEPTS[lg.dept] : lg.dept) : null);
    setTxt('p-epci', null);
    if (lg.type){
      var libType = /appart/i.test(lg.type) ? 'Appartement' : (/maison|pavillon/i.test(lg.type) ? 'Maison individuelle' : null);
      if (libType) document.querySelectorAll('[data-r="type"]').forEach(function(t){
        t.classList.toggle('selected', t.dataset.v === libType);
      });
    }
    // DPE et énergie de chauffage : hors sujet pour un dossier autonomie.
    var dpeRow = document.getElementById('p-dpe-row');
    var heatRow = document.getElementById('p-heat-row');
    if (dossier.type === 'autonomie'){
      if (dpeRow) dpeRow.hidden = true;
      if (heatRow) heatRow.hidden = true;
    } else {
      setTxt('p-dpe', lg.dpeAvant || p.dpeAvant || null);
      if (heatRow) heatRow.hidden = true; // le moteur LHI ne se sert pas de l'énergie de chauffage
    }

    // ── Foyer fiscal
    if (p.rfr) setVal('p-rfr', Number(p.rfr).toLocaleString('fr-FR') + ' €');
    var parts = Number(p.foyer) || 0;
    if (parts){
      var sel = document.getElementById('p-parts');
      if (sel) sel.selectedIndex = Math.max(0, Math.min(5, parts - 1));
    }
    if (p.region){
      var reg = document.getElementById('p-region');
      if (reg) reg.value = p.region;
    }

    // ── Travaux : la liste vient du catalogue partagé (mêmes codes que le moteur)
    renderTravaux(dossier.type, p);

    // ── Carte résumé
    var total = totalDe(dossier, r), cout = coutDe(dossier, r);
    var sumH = document.getElementById('sum-h');
    var sumS = document.getElementById('sum-s');
    if (sumH && total > 0) sumH.textContent = 'Aides estimées : ' + eur(total);
    if (sumS) sumS.textContent = cout > 0
      ? 'Sur un projet estimé de ' + eur(cout) + ' TTC'
      : 'Cliquez sur un bloc ci-dessous pour modifier, puis Enregistrer.';

    attacherSauvegarde();
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', run);
  else run();
})();

