/* Helpers de montant partagés par l'étape 7 (total + CTA) et l'étape 8 (hero). */
window.rfRoundDownTeaser = function(n){
  // Neutralisé (règle produit du 4 août 2026) : le total des aides doit être
  // strictement identique sur tous les écrans du parcours. Plus d'arrondi au
  // millier inférieur, plus de préfixe « ~ » — l'utilisateur a déjà vu le
  // chiffre exact à l'étape 7. Conservée en identité pour tout appelant futur.
  return Math.round(Number(n) || 0);
};
/* Aucun contenu n'est conditionné dans ce parcours : le détail ligne par ligne
   est visible par tout le monde. Conservée en identité pour tout appelant. */
window.rfDetailVisible = function(){ return true; };

pages/onboarding-diagnostic/02.js:
/* Redémarrage propre du tunnel : ?fresh=1 purge le brouillon en cours.
   Cas énergétique : profil, étape courante et variantes bailleur / copropriété.
   En développement local seulement, les dossiers sont purgés aussi, pour repartir
   d'un tableau de bord vide. Partout ailleurs, junglerenov.dossiers survit toujours —
   de même que le compte et la session, dans tous les cas. */
(function resetIfFresh(){
  try {
    var params = new URLSearchParams(location.search);
    if (params.get('fresh') !== '1') return;
    localStorage.removeItem('junglerenov.profile');
    localStorage.removeItem('junglerenov.currentStep');
    localStorage.removeItem('junglerenov.ownerType');
    localStorage.removeItem('junglerenov.bailleur');
    localStorage.removeItem('junglerenov.bailleurCase');
    localStorage.removeItem('junglerenov.bailleurRental');
    localStorage.removeItem('junglerenov.bailleurLegal');
    localStorage.removeItem('junglerenov.hasCoproCollectifs');
    localStorage.removeItem('junglerenov.copro');
    localStorage.removeItem('junglerenov.returnTo');
    localStorage.removeItem('junglerenov.pendingDossier');
    /* (purge des données de test retirée) */
    history.replaceState(null, '', location.pathname);
  } catch (_) {}
})();

pages/onboarding-diagnostic/04.js:
  // Helper unique de détection du type de logement — priorité au DOM :
  // l'intention exprimée en session prime sur le localStorage, qui peut être stale
  // (la clé profile.logement.type n'est écrite qu'à l'étape 7 ou à la soumission).
  function rfGetTypeLogement() {
    const tile = document.querySelector('[data-radio="type"].selected .nm');
    if (tile) return tile.textContent.toLowerCase().includes('apparte') ? 'appartement' : 'maison';
    try {
      const profil = JSON.parse(localStorage.getItem('junglerenov.profile') || '{}');
      const t = profil && profil.logement && profil.logement.type;
      if (t) return String(t).toLowerCase().includes('apparte') ? 'appartement' : 'maison';
    } catch (_) {}
    return 'maison';
  }

  const steps = [
    {n:1,lbl:"Adresse"},{n:2,lbl:"Logement"},{n:3,lbl:"Situation"},
    {n:4,lbl:"Revenus"},{n:5,lbl:"Travaux"},{n:6,lbl:"Calcul"},{n:7,lbl:"Résultats"},{n:8,lbl:"Transmission"}
  ];
  let cur = 1;
  let maxReached = 1;
  const stepperRow = document.getElementById('stepper-row');
  steps.forEach((s,i)=>{
    if(i>0){const sep=document.createElement('div');sep.className='pip-line';stepperRow.appendChild(sep)}
    const b=document.createElement('button');
    b.className='step-pip';
    b.dataset.step=s.n;
    b.dataset.goto = String(s.n);
    // L'étape 6 n'est qu'une animation de calcul : on la marque franchie mais
    // on n'y renvoie jamais l'utilisateur.
    if (s.n === 6) b.setAttribute('data-non-cliquable', '1');
    b.innerHTML=`<span class="num">${s.n}</span><span class="lbl">${s.lbl}</span>`;
    function jumpTo(){
      // Navigation libre entre les étapes DÉJÀ atteintes, dans les deux sens :
      // reculer pour corriger, puis revenir en avant sans tout re-valider.
      if (s.n === cur || s.n > maxReached) return;
      if (b.hasAttribute('data-non-cliquable')) return;
      goTo(s.n);
    }
    b.addEventListener('click', jumpTo);
    b.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' '){ e.preventDefault(); jumpTo(); }
    });
    stepperRow.appendChild(b);
  });

  function render(){
    document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active'));
    document.getElementById('step-'+cur).classList.add('active');
    if (cur > maxReached) maxReached = cur;
    document.querySelectorAll('.step-pip').forEach(p=>{
      const n=+p.dataset.step;
      p.classList.remove('active','done','pending');
      // Une étape déjà atteinte reste « done » (donc cliquable) même après un
      // retour en arrière : elle ne doit pas repasser en grisé.
      if (n === cur)            p.classList.add('active');
      else if (n <= maxReached) p.classList.add('done');
      else                      p.classList.add('pending');
      // Les étapes non encore atteintes ne sont pas navigables
      if (n > maxReached) p.setAttribute('data-locked','true'); else p.removeAttribute('data-locked');
      const nav = n !== cur && n <= maxReached && !p.hasAttribute('data-non-cliquable');
      if (nav){
        p.setAttribute('tabindex','0');
        p.setAttribute('aria-label', "Retourner à l'étape " + (steps[n-1] ? steps[n-1].lbl : n));
        p.disabled = false;
      } else {
        p.setAttribute('tabindex','-1');
        p.removeAttribute('aria-label');
      }
      p.setAttribute('aria-current', n === cur ? 'step' : 'false');
    });
    try { localStorage.setItem('junglerenov.currentStep', String(cur)); } catch(_){}
    document.getElementById('prog-txt').textContent=`Étape ${cur} sur 8`;
    const pct = Math.round((cur - 1) / 8 * 100);   // étapes achevées, pas l'étape courante
    document.getElementById('prog-bar').style.width=pct+'%';
    const pctEl = document.getElementById('prog-pct');
    if (pctEl) pctEl.textContent = pct + ' %';
    const prevBtn = document.getElementById('prev');
    const nextBtn = document.getElementById('next');
    prevBtn.disabled=(cur===1);
    prevBtn.style.opacity=cur===1?.4:1;
    // Étape 5 = calcul automatique : on masque les boutons et on lance l'animation
    if(cur===6){
      prevBtn.style.visibility='hidden';
      nextBtn.style.visibility='hidden';
      startCalcAnimation();
    } else {
      prevBtn.style.visibility='visible';
      nextBtn.style.visibility='visible';
      stopCalcAnimation();
    }
    // La restauration d'état (junglerenov.currentStep) passe par render() sans passer
    // par le wrapper de goTo() : il faut donc réinjecter le calcul ici, sinon
    // l'étape 7 resterait sur ses placeholders codés en dur.
    if (cur === 7) { try { injectResults(); } catch(e){ console.warn('injectResults (render) :', e); } }
    if (cur === 7) { try { updateCtaScenAmount(); } catch(e){ console.warn('CTA étape 7 :', e); } }
    // Rappel du montant des aides à l'arrivée sur l'étape 8
    if (cur === 8) { try { updateHeroRoiStep8(); } catch(e){ console.warn('hero ROI :', e); } }
    if (cur === 8) { try { updateRecapTransmission(); } catch(e){ console.warn('récap transmission :', e); } }
    if(cur===7){nextBtn.textContent='Continuer mon dossier — gratuit';nextBtn.className='btn btn-amber'}
    else if(cur===8){ /* Le formulaire porte son propre appel à l'action : pas de doublon. */ nextBtn.style.visibility='hidden'; }
    else{nextBtn.textContent='Continuer';nextBtn.className='btn btn-primary'}
    if (cur === 3 && typeof window.__rfUpdateStep3Block === 'function') window.__rfUpdateStep3Block();
    else if (nextBtn) { nextBtn.disabled = false; nextBtn.classList.remove('is-disabled'); }
    window.scrollTo({top:0,behavior:'instant'});
  }
  function goTo(n){cur=Math.max(1,Math.min(8,n));render()}

  /* ═══════════════════════════════════════════════════════════════════════
     REPRISE DU DOSSIER (depuis Mon profil)
     Si l'utilisateur arrive avec #transmission, on saute
     directement à l'étape 8 et on masque la carte "Découverte" puisqu'il
     a déjà un compte (et veut justement le faire évoluer).
     On pré-remplit aussi son email/prénom/nom pour éviter la double saisie.
     ═══════════════════════════════════════════════════════════════════════ */
  (function(){
    const wantsUpgrade = location.hash === '#transmission'
                      || new URLSearchParams(location.search).get('upgrade') === '1';
    if (!wantsUpgrade) return;
    let existingProfile = {};
    try { existingProfile = JSON.parse(localStorage.getItem('junglerenov.profile') || '{}'); } catch {}
    // On ne déclenche le mode upgrade que si l'utilisateur a déjà un profil avec un email
    if (!existingProfile.email) return;
    // Saute à l'étape 8
    setTimeout(() => {
      goTo(8);
      // Adapte le titre + sous-titre à l'arrivée directe sur la transmission
      const titleEl = document.querySelector('#step-8 .q-title');
      const subEl   = document.querySelector('#step-8 .q-sub');
      if (titleEl) titleEl.textContent = "Dernière étape : votre dossier.";
      if (subEl)   subEl.textContent   = "Nous rassemblons votre simulation et votre estimation dans un dossier, conservé dans votre espace. Il sera transmis dès qu'un accompagnateur agréé sera désigné dans votre département. Vous n'avez rien à régler sur ce site.";
      // Pré-remplit les champs identité avec le profil existant
      const setVal = (id, val) => { const el = document.getElementById(id); if (el && val) el.value = val; };
      setVal('su-firstname', existingProfile.firstname);
      setVal('su-lastname',  existingProfile.lastname);
      setVal('su-email',     existingProfile.email);
      // Re-valide le formulaire avec les nouvelles valeurs
      validateSignup();
      // Scroll au bon endroit
      setTimeout(() => {
        const signup = document.getElementById('signup');
        if (signup) jrScrollTo(signup);
      }, 300);
    }, 50);
  })();

  /* Depuis les résultats (7), revenir mène à l'écran de calcul (6) qui masque
   les boutons et relance son animation avant de ré-avancer : on saute
   directement aux travaux (5), comme le font les deux autres tunnels. */
document.getElementById('prev').addEventListener('click',()=>goTo(cur === 7 ? 5 : cur-1));
  document.getElementById('next').addEventListener('click',()=>{
    if(cur===8){
      // Le bouton footer renvoie vers le formulaire de transmission.
      const txBtn = document.getElementById('su-submit');
      if (txBtn) { jrScrollTo(txBtn); txBtn.focus(); }
      return;
    }
    /* Département obligatoire : il pilote la région, l'intercommunalité et les
       aides régionales. Vide, les aides Grand Est tombaient à 0 sans motif. */
    if (cur === 2) {
      const deptEl = document.getElementById('dept');
      if (deptEl && !deptEl.value) {
        /* Message propre à l'étape 2 : showWarn n'existe que dans le bloc de l'étape 4. */
        const deptErr = document.getElementById('dept-err');
        if (deptErr){ deptErr.textContent = 'Indiquez votre département : il détermine les aides régionales et métropolitaines auxquelles vous avez droit.'; deptErr.hidden = false; }
        deptEl.setAttribute('aria-invalid', 'true');
        deptEl.focus();
        return;
      }
      if (deptEl) deptEl.removeAttribute('aria-invalid');
      const deptErrOk = document.getElementById('dept-err'); if (deptErrOk) deptErrOk.hidden = true;
    }
    // Étape 4 : bloquer si le revenu fiscal de référence n'est pas saisi
    if (cur === 3) {
      const ownerChecked = document.querySelector('input[name="rf-owner-type"]:checked');
      let w3 = document.getElementById('step-3-warn');
      if (!ownerChecked) {
        if (!w3) {
          w3 = document.createElement('div');
          w3.id = 'step-3-warn';
          w3.style.cssText = 'margin-bottom:14px;padding:10px 14px;background:#FEE2E2;border:1px solid #FEE2E2;color:#991B1B;border-radius:6px;font-size:17px;font-weight:500';
          document.querySelector('#step-3 .card')?.prepend(w3);
        }
        w3.textContent = 'Merci de préciser si vous faites ces travaux pour votre résidence principale ou pour un bien locatif.';
        w3.style.display = '';
        return;
      }
      if (w3) w3.style.display = 'none';
      // Appartement : réponse copro explicite, sinon on retient "Non"
      if (rfGetTypeLogement() === 'appartement' && !document.querySelector('input[name="rf-copro-collectifs"]:checked')) {
        const noRadio = document.querySelector('input[name="rf-copro-collectifs"][value="no"]');
        if (noRadio) { noRadio.checked = true; noRadio.dispatchEvent(new Event('change', { bubbles:true })); }
      }
    }
    if (cur === 4) {
      const oType = (function(){ try { return localStorage.getItem('junglerenov.ownerType') || 'occupant'; } catch(_){ return 'occupant'; } })();
      const bCase = (function(){ try { return localStorage.getItem('junglerenov.bailleurCase') || 'occupant'; } catch(_){ return 'occupant'; } })();
      const w4 = document.getElementById('step-4-warn');
      const showWarn = m => { if (w4) { w4.textContent = m; w4.style.display = 'block'; } };
      if (oType === 'occupant') {
        if (parseRFR() === null) { showWarn("Renseignez votre revenu fiscal de référence : il détermine votre catégorie MaPrimeRénov' et donc le montant de vos aides."); document.getElementById('rfr')?.focus(); return; }
      } else if (bCase === 'copro') {
        const lots = document.getElementById('rf-copro-lots')?.value;
        const tant = document.getElementById('rf-copro-tantiemes')?.value;
        const dpe  = document.querySelector('[name="rf-copro-dpe"]')?.value;
        if (!lots || Number(lots) < 2) { showWarn('Renseignez le nombre de logements dans la copropriété.'); return; }
        if (!tant || Number(tant) < 1) { showWarn('Renseignez vos tantièmes de copropriété.'); return; }
        if (!dpe) { showWarn('Sélectionnez le DPE moyen actuel de la copropriété.'); return; }
      } else if (['particulier-nu','indivision-nu','sci-ir-nu'].includes(bCase)) {
        const rent = document.getElementById('rf-rent-amount')?.value;
        const zone = document.querySelector('[name="rf-zone"]')?.value;
        const loc  = document.querySelector('input[name="rf-loc-level"]:checked')?.value;
        const dur  = document.querySelector('[name="rf-loc-duration"]')?.value;
        if (!rent || Number(rent) <= 0) { showWarn('Renseignez le loyer mensuel envisagé.'); return; }
        if (!zone) { showWarn('Sélectionnez la zone géographique du logement.'); return; }
        if (!loc)  { showWarn("Choisissez un engagement Loc'Avantages (ou « Aucun »)."); return; }
        if (!dur)  { showWarn("Choisissez une durée d'engagement de location."); return; }
      }
      if (w4) w4.style.display = 'none';
    }
    // Étape 5 : bloquer si aucun travaux coché
    if(cur===5){
      const sel = document.querySelectorAll('#step-5 [data-work].selected');
      if (sel.length === 0){
        const warn = document.getElementById('step-5-warn');
        if (warn){ warn.style.display='block'; warn.textContent='Cochez au moins un poste de travaux pour continuer.'; }
        return;
      }
    }
    goTo(cur+1);
  });

  // Année de construction : borne max = année courante
  const yearMaxEl = document.getElementById('year');
  if (yearMaxEl) yearMaxEl.max = new Date().getFullYear();

  // Tile single-select
  document.querySelectorAll('[data-radio]').forEach(t=>{
    t.addEventListener('click',()=>{
      const grp=t.dataset.radio;
      document.querySelectorAll(`[data-radio="${grp}"]`).forEach(x=>x.classList.remove('selected'));
      t.classList.add('selected');
      document.querySelectorAll(`[data-radio="${grp}"]`).forEach(x=>x.setAttribute('aria-checked', x.classList.contains('selected') ? 'true' : 'false'));
    });
  });

  // Fix #4 — Surface : slider et input numérique synchronisés (bidirectionnel)
  const surf    = document.getElementById('surf');
  const surfNum = document.getElementById('surf-num');
  if (surf && surfNum) {
    surf.addEventListener('input', () => { surfNum.value = surf.value; });
    surfNum.addEventListener('input', () => {
      let v = parseInt(surfNum.value, 10);
      if (isNaN(v)) return;
      v = Math.max(20, Math.min(300, v));
      surf.value = v;
    });
    surfNum.addEventListener('blur', () => {
      let v = parseInt(surfNum.value, 10);
      if (isNaN(v) || v < 20) v = 20;
      if (v > 300) v = 300;
      surfNum.value = v; surf.value = v;
    });
  }

  // Fix #5 — Année de construction : feedback contextuel dynamique
  const yearInput = document.getElementById('year');
  const yearHelp  = document.getElementById('year-help');
  if (yearInput && yearHelp){
    yearInput.addEventListener('input', () => {
      const y = parseInt(yearInput.value, 10);
      if (isNaN(y)) return;
      const now = new Date().getFullYear();
      const age = now - y;
      if (y < 1974)  yearHelp.textContent = `Logement avant 1ʳᵉ RT (${age} ans) — grosse marge de progression, aides maximales possibles.`;
      else if (y < 2001) yearHelp.textContent = `Logement RT88-89 (${age} ans) — éligible MPR (>15 ans), DPE typique D-E-F.`;
      else if (y < 2006) yearHelp.textContent = `Logement RT2000 (${age} ans) — éligible MPR, DPE typique C-D.`;
      else if (y < 2013) yearHelp.textContent = `Logement RT2005 (${age} ans) — éligible MPR, DPE typique C.`;
      else if (age >= 15) yearHelp.textContent = `Logement RT2012 (${age} ans) — éligible MPR, DPE typique B. Peu d'aides isolation.`;
      else yearHelp.innerHTML = `<strong style="color:#991B1B">Logement de moins de 15 ans</strong> — non éligible à MaPrimeRénov'. Seul le CEE reste possible.`;
    });
  }

  // Fix #7 — Tuiles "Nombre de personnes" : synchro avec select caché
  document.querySelectorAll('.parts-tile').forEach(t => {
    t.addEventListener('click', () => {
      const n = parseInt(t.dataset.parts, 10);
      const sel = document.getElementById('parts');
      if (sel) sel.selectedIndex = n - 1;
    });
  });

  // Fix #8 — Feedback catégorie MPR live sous RFR (bleus/jaunes/violets/roses)
  const rfrInput = document.getElementById('rfr');
  const rfrBadge = document.getElementById('rfr-badge');
  const rfrDot   = document.getElementById('rfr-badge-dot');
  const rfrText  = document.getElementById('rfr-badge-text');
  const CAT_COLORS = { bleus: '#1F6B3F', jaunes: '#123A2E', violets: '#123A2E', roses: '#991B1B' };
  const CAT_LABELS_LIVE = {
    bleus:   'Ressources très modestes — <strong>aides MPR maximales</strong>',
    jaunes:  'Ressources modestes — <strong>aides MPR généreuses</strong>',
    violets: 'Ressources intermédiaires — <strong>aides MPR standard</strong>',
    roses:   'Ressources supérieures — <strong>aides MPR limitées</strong>, CEE + TVA restent accessibles'
  };
  function estimateCat(rfr, parts){
    // Délégué au moteur unique (_compute_aids.js) — plafonds Anah 2026,
    // zone IDF/hors-IDF réelle et formule base + add*(foyer-1) non plafonnée.
    const region = parseRegion();
    return window.RFCompute.categorie(rfr, parts || 4, region);
  }
  function updateRfrBadge(){
    if (!rfrInput || !rfrBadge) return;
    const raw = (rfrInput.value || '').replace(/[^\d]/g, '');
    const val = parseInt(raw, 10);
    if (!raw || isNaN(val) || val < 1000){ rfrBadge.style.display = 'none'; return; }
    const partsSel = document.getElementById('parts');
    const parts = partsSel ? (partsSel.selectedIndex + 1) : 4;
    const cat = estimateCat(val, parts);
    const regionIdf = (parseRegion() === 'Île-de-France');
    const regionLabel = regionIdf ? 'Île-de-France' : 'hors IDF';
    rfrDot.style.background = CAT_COLORS[cat];
    // Traçabilité : on montre le plafond de la catégorie et le forfait qui en
    // découle, pour que l'utilisateur relie sa saisie au montant à venir.
    let plafondTxt = '';
    try {
      if (cat !== 'roses' && window.RFCompute && RFCompute.plafond){
        const plaf = RFCompute.plafond(regionIdf ? 'idf' : 'hors_idf', cat, parts);
        if (plaf) plafondTxt = ` · plafond de la catégorie : <strong>${plaf.toLocaleString('fr-FR')} €</strong>`;
      }
    } catch(_){}
    let forfaitTxt = '';
    try {
      const fc = window.RFCompute && RFCompute.MPR && RFCompute.MPR.combles;
      if (fc && fc[cat]) forfaitTxt = `<br><span style="font-size:17px">Exemple de forfait : isolation des combles <strong>${fc[cat]} €/m²</strong>.</span>`;
    } catch(_){}
    rfrText.innerHTML = CAT_LABELS_LIVE[cat]
      + ` <span style="opacity:.7;font-size:17px">(pour ${parts} personne${parts>1?'s':''} ${regionLabel}${plafondTxt})</span>`
      + forfaitTxt;
    rfrBadge.style.display = 'flex';
    rfrBadge.style.background = CAT_COLORS[cat] + '15';
    rfrBadge.style.border = '1px solid ' + CAT_COLORS[cat] + '40';
  }
  if (rfrInput){
    rfrInput.addEventListener('input', updateRfrBadge);
    rfrInput.addEventListener('blur', () => {
      const raw = (rfrInput.value || '').replace(/[^\d]/g, '');
      if (raw) rfrInput.value = parseInt(raw, 10).toLocaleString('fr-FR') + ' €';
      updateRfrBadge();
    });
  }
  document.querySelectorAll('.parts-tile').forEach(t => t.addEventListener('click', updateRfrBadge));

  /* ─── Département → EPCI conditionnel (Grand Est V1) ─── */
  const EPCI_PAR_DEPT = {
    '54': [
      { value: 'metropole_grand_nancy',    label: 'Métropole du Grand Nancy' },
      { value: 'cc_pays_sel_vermois',      label: 'CC des Pays du Sel et du Vermois' },
      { value: 'cc_seille_grand_couronne', label: 'CC Seille et Grand Couronné' },
      { value: 'autre_grand_est',          label: 'Autre EPCI (54)' },
    ],
    '57': [
      { value: 'metz_metropole',           label: 'Metz Métropole' },
      { value: 'autre_grand_est',          label: 'Autre EPCI (57)' },
    ],
    '67': [
      { value: 'eurometropole_strasbourg', label: 'Eurométropole de Strasbourg' },
      { value: 'autre_grand_est',          label: 'Autre EPCI (67)' },
    ],
    '68': [
      { value: 'mulhouse_alsace_agglo',    label: 'Mulhouse Alsace Agglomération' },
      { value: 'colmar_agglomeration',     label: 'Colmar Agglomération' },
      { value: 'autre_grand_est',          label: 'Autre EPCI (68)' },
    ],
    '51': [
      { value: 'grand_reims',              label: 'Grand Reims' },
      { value: 'autre_grand_est',          label: 'Autre EPCI (51)' },
    ],
    '08': [{ value: 'autre_grand_est', label: 'EPCI (08)' }],
    '10': [{ value: 'autre_grand_est', label: 'EPCI (10)' }],
    '52': [{ value: 'autre_grand_est', label: 'EPCI (52)' }],
    '55': [{ value: 'autre_grand_est', label: 'EPCI (55)' }],
    '88': [{ value: 'autre_grand_est', label: 'EPCI (88)' }],
  };
  const deptSelect = document.getElementById('dept');
  const epciField  = document.getElementById('epci-field');
  const epciSelect = document.getElementById('epci');
  function refreshEpci(){
    if (!deptSelect || !epciField || !epciSelect) return;
    const options = EPCI_PAR_DEPT[deptSelect.value];
    if (options){
      const keep = epciSelect.value;
      epciSelect.innerHTML = '<option value="">— Choisir votre EPCI —</option>' +
        options.map(o => `<option value="${o.value}">${o.label}</option>`).join('');
      if (options.some(o => o.value === keep)) epciSelect.value = keep;
      epciField.style.display = '';
    } else {
      epciField.style.display = 'none';
      epciSelect.value = '';
    }
  }
  if (deptSelect) deptSelect.addEventListener('change', refreshEpci);

  /* ══════════════════════════════════════════════════════════════
     Branchement Propriétaire Occupant / Propriétaire Bailleur
     Étape 3 : sélecteur + filtres bloquants
     Étape 4 : bascule des blocs #step4-occupant / #step4-bailleur
     Le champ legacy [data-radio="status"] reste dans le DOM (masqué)
     et sert de miroir pour le moteur de calcul et la persistance.
     ══════════════════════════════════════════════════════════════ */
  (function initOwnerBranching(){
    const ownerRadios    = document.querySelectorAll('input[name="rf-owner-type"]');
    const bailleurFilters= document.getElementById('rf-bailleur-filters');
    const rentalSelect   = document.querySelector('select[name="rf-bailleur-rental-type"]');
    const legalSelect    = document.querySelector('select[name="rf-bailleur-legal"]');
    const blockRental    = document.querySelector('.rf-bailleur-block--rental');
    const blockSci       = document.querySelector('.rf-bailleur-block--sci');
    const blockCopro     = document.querySelector('.rf-bailleur-block--copro');
    if (!ownerRadios.length || !bailleurFilters) return;

    function syncLegacyTiles(ownerType){
      // Reporte le choix sur les tuiles legacy pour que le calcul et la persistance suivent
      document.querySelectorAll('[data-radio="status"]').forEach(t => {
        const nm = (t.querySelector('.nm')?.textContent || '').toLowerCase();
        const match = ownerType === 'bailleur' ? nm.startsWith('bailleur') : nm.startsWith('occupant');
        t.classList.toggle('selected', match);
      });
    }

    function updateProfileVisibility(){
      const val = document.querySelector('input[name="rf-owner-type"]:checked')?.value;
      bailleurFilters.hidden = val !== 'bailleur';
      if (val) {
        try { localStorage.setItem('junglerenov.ownerType', val); } catch(_){}
        syncLegacyTiles(val);
      }
      document.dispatchEvent(new CustomEvent('rf:owner-type-change', { detail:{ ownerType: val } }));
      updateBailleurBlocks();
    }

    function updateBailleurBlocks(){
      const isBailleur = document.querySelector('input[name="rf-owner-type"]:checked')?.value === 'bailleur';
      const rental = rentalSelect?.value;
      const legal  = legalSelect?.value;

      // Warnings informatifs : ils n'empêchent plus de continuer
      if (blockRental) {
        const show = isBailleur && (rental === 'meuble' || rental === 'saisonnier');
        blockRental.hidden = !show;
        if (show) blockRental.querySelectorAll('[data-block-msg]').forEach(el => {
          el.hidden = el.getAttribute('data-block-msg') !== rental;
        });
      }
      if (blockSci) {
        const show = isBailleur && (legal === 'sci-ir' || legal === 'sci-is');
        blockSci.hidden = !show;
        // Si location meublée/saisonnière ET SCI à l'IR : le type de location prime
        // (règle Anah). On force le variant « sci-is » (aides partielles) pour éviter
        // la contradiction visuelle avec le bloc meublé/saisonnier.
        const sciVariant = ((rental === 'meuble' || rental === 'saisonnier') && legal === 'sci-ir')
          ? 'sci-is'
          : legal;
        if (show) blockSci.querySelectorAll('[data-block-msg]').forEach(el => {
          el.hidden = el.getAttribute('data-block-msg') !== sciVariant;
        });
      }
      if (blockCopro) blockCopro.hidden = !isBailleur || legal !== 'copro-communes';

      // Aucun cas ne désactive plus le bouton Continuer
      const nextBtn = document.getElementById('next');
      window.__rfStep3Blocked = false;
      if (nextBtn && typeof cur !== 'undefined' && cur === 3) {
        nextBtn.disabled = false;
        nextBtn.classList.remove('is-disabled');
      }

      const bailleurCase = isBailleur ? computeBailleurCase(rental, legal) : 'occupant';
      window.__rfBailleurCase = bailleurCase;
      // Purge des clés qui n'ont plus de sens dans les cas restreints ou copro
      if (['sci-is','meuble','saisonnier','copro'].includes(bailleurCase)) {
        try {
          const d = JSON.parse(localStorage.getItem('junglerenov.bailleur') || '{}');
          delete d.locLevel; delete d.locDuration; delete d.lpe;
          localStorage.setItem('junglerenov.bailleur', JSON.stringify(d));
        } catch(_){}
      }
      document.dispatchEvent(new CustomEvent('rf:bailleur-case-change', { detail:{ bailleurCase } }));

      try {
        localStorage.setItem('junglerenov.bailleurRental', rental || '');
        localStorage.setItem('junglerenov.bailleurLegal', legal || '');
        localStorage.setItem('junglerenov.bailleurCase', bailleurCase || '');
      } catch(_){}

      updateEligibilityMatrix(bailleurCase);
    }

    // Cas agrégé qui pilote l'affichage et le calcul
    function computeBailleurCase(rental, legal){
      if (legal === 'copro-communes') return 'copro';
      if (rental === 'saisonnier')    return 'saisonnier';
      if (rental === 'meuble')        return 'meuble';
      if (legal === 'sci-is')         return 'sci-is';
      if (legal === 'sci-ir')         return 'sci-ir-nu';
      if (legal === 'indivision')     return 'indivision-nu';
      if (legal === 'particulier')    return 'particulier-nu';
      return null;
    }

    const ELIGIBILITY_TABLE = {
      'occupant': {
        'mpr': 'yes', 'mpr-bailleur': 'no', 'mpr-copro': 'no', 'loc-avantages': 'no',
        'cee': 'yes', 'eco-ptz': 'yes', 'tva': 'yes', 'lpe': 'no',
      },
      'particulier-nu': { 'mpr-bailleur':'yes', 'mpr-copro':'no',  'loc-avantages':'yes',  'cee':'yes', 'eco-ptz':'yes', 'tva':'yes', 'lpe':'cond' },
      'indivision-nu':  { 'mpr-bailleur':'yes', 'mpr-copro':'no',  'loc-avantages':'yes',  'cee':'yes', 'eco-ptz':'yes', 'tva':'yes', 'lpe':'cond' },
      'sci-ir-nu':      { 'mpr-bailleur':'yes', 'mpr-copro':'no',  'loc-avantages':'yes',  'cee':'yes', 'eco-ptz':'yes', 'tva':'yes', 'lpe':'cond' },
      'sci-is':         { 'mpr-bailleur':'no',  'mpr-copro':'no',  'loc-avantages':'no',   'cee':'yes', 'eco-ptz':'yes', 'tva':'yes', 'lpe':'no'   },
      'meuble':         { 'mpr-bailleur':'no',  'mpr-copro':'no',  'loc-avantages':'no',   'cee':'yes', 'eco-ptz':'yes', 'tva':'yes', 'lpe':'no'   },
      'saisonnier':     { 'mpr-bailleur':'no',  'mpr-copro':'no',  'loc-avantages':'no',   'cee':'yes', 'eco-ptz':'no',  'tva':'no',  'lpe':'no'   },
      'copro':          { 'mpr-bailleur':'no',  'mpr-copro':'yes', 'loc-avantages':'cond', 'cee':'yes', 'eco-ptz':'yes', 'tva':'yes', 'lpe':'no'   },
    };

    function updateEligibilityMatrix(bailleurCase){
      const matrix = document.getElementById('rf-eligibility-matrix');
      if (!matrix) return;
      if (!bailleurCase || !ELIGIBILITY_TABLE[bailleurCase]) { matrix.hidden = true; return; }
      matrix.hidden = false;
      // Tout copropriétaire d'appartement peut bénéficier de MaPrimeRénov' Copropriété sur sa
      // quote-part de travaux collectifs votés en AG.
      const typeLogement = rfGetTypeLogement();

      const table = Object.assign({}, ELIGIBILITY_TABLE[bailleurCase]);
      if (typeLogement === 'appartement'
          && bailleurCase !== 'copro' && bailleurCase !== 'meuble'
          && bailleurCase !== 'saisonnier' && bailleurCase !== 'sci-is') {
        table['mpr-copro'] = 'cond';
      }

      matrix.querySelectorAll('li[data-aide]').forEach(li => {
        const status = table[li.getAttribute('data-aide')] || 'no';
        const el = li.querySelector('[data-status]');
        el.setAttribute('data-status', status);
        el.textContent = status === 'yes' ? 'Applicable' : (status === 'cond' ? 'Sous conditions' : 'Non applicable');
        li.classList.remove('is-yes','is-no','is-cond');
        li.classList.add(status === 'yes' ? 'is-yes' : status === 'cond' ? 'is-cond' : 'is-no');
      });

      const liMprCopro = matrix.querySelector('li[data-aide="mpr-copro"]');
      if (liMprCopro) {
        if (typeLogement === 'appartement' && table['mpr-copro'] === 'cond') {
          liMprCopro.setAttribute('title', "Sous réserve d'un vote en Assemblée Générale pour des travaux collectifs (isolation façade, chaudière commune, VMC…). Nécessite un accompagnateur MAR agréé.");
        } else {
          liMprCopro.removeAttribute('title');
        }
      }
    }

    ownerRadios.forEach(r => r.addEventListener('change', updateProfileVisibility));
    rentalSelect?.addEventListener('change', updateBailleurBlocks);
    legalSelect?.addEventListener('change', updateBailleurBlocks);

    // Restauration depuis localStorage
    try {
      const stored = localStorage.getItem('junglerenov.ownerType');
      if (stored) {
        const radio = document.querySelector(`input[name="rf-owner-type"][value="${stored}"]`);
        if (radio) radio.checked = true;
      }
      const sr = localStorage.getItem('junglerenov.bailleurRental');
      if (sr && rentalSelect) rentalSelect.value = sr;
      const sl = localStorage.getItem('junglerenov.bailleurLegal');
      if (sl && legalSelect) legalSelect.value = sl;
    } catch(_){}

    updateProfileVisibility();
    window.__rfUpdateStep3Block = updateBailleurBlocks;
  })();

  /* Étape 4 — bascule des blocs selon le profil */
  (function initStep4Branching(){
    const blockOccupant = document.getElementById('step4-occupant');
    const blockBailleur = document.getElementById('step4-bailleur');
    const blockCopro    = document.getElementById('step4-copro');
    const titleOcc = document.querySelector('.rf-step-title--occupant');
