    function apply(ownerType, bailleurCase){
      const isBailleur = ownerType === 'bailleur';
      const isCopro    = isBailleur && bailleurCase === 'copro';

      // Appartement + travaux collectifs prévus : le bloc copro s'ajoute au parcours
