      // Masquage conditionnel dans #step4-bailleur selon le cas
      document.querySelectorAll('#step4-bailleur [data-show-if]').forEach(el => {
        const allowed = (el.getAttribute('data-show-if') || '').split(',').map(x => x.trim());
        el.hidden = !(isBailleur && !isCopro && allowed.includes(bailleurCase));
