      // Requis dynamique : un champ masqué ne bloque jamais la validation
      function toggleRequired(scope, active){
        document.querySelectorAll(scope + ' [required], ' + scope + ' [data-rf-required]').forEach(el => {
          el.dataset.rfRequired = 'true';
          if (!active || el.closest('[hidden]')) el.removeAttribute('required');
          else el.setAttribute('required','required');
        });
      }
      toggleRequired('#step4-occupant', !isBailleur);
      toggleRequired('#step4-bailleur', isBailleur && !isCopro);
