    }

    function currentCase(){
      try { return localStorage.getItem('junglerenov.bailleurCase') || 'particulier-nu'; } catch(_){ return 'particulier-nu'; }
    }
    function currentOwner(){
      try { return localStorage.getItem('junglerenov.ownerType') || 'occupant'; } catch(_){ return 'occupant'; }
    }

    document.addEventListener('rf:copro-collectifs-change', () => apply(currentOwner(), currentCase()));
    document.addEventListener('rf:owner-type-change',   e => apply(e.detail.ownerType, currentCase()));
    document.addEventListener('rf:bailleur-case-change', e => apply(currentOwner(), e.detail.bailleurCase));

    // Persistance des champs bailleur (étape 4)
    const map = {
      'rf-rent-amount':'rent', 'rf-nb-logements':'nbLogements',
      'rf-zone':'zone', 'rf-loc-level':'locLevel',
      'rf-loc-duration':'locDuration', 'rf-lpe':'lpe',
    };
    function saveBailleur(){
      try {
        const d = {};
        Object.entries(map).forEach(([name, key]) => {
          const el = document.querySelector('[name="' + name + '"]:checked') || document.querySelector('[name="' + name + '"]');
          if (el) d[key] = el.value;
        });
        localStorage.setItem('junglerenov.bailleur', JSON.stringify(d));
      } catch(_){}
    }
    function restoreBailleur(){
      try {
        const d = JSON.parse(localStorage.getItem('junglerenov.bailleur') || '{}');
        Object.entries(map).forEach(([name, key]) => {
          if (d[key] === undefined || d[key] === '') return;
          const radios = document.querySelectorAll('input[type="radio"][name="' + name + '"]');
          if (radios.length) radios.forEach(r => { r.checked = (r.value === d[key]); });
          else { const el = document.querySelector('[name="' + name + '"]'); if (el) el.value = d[key]; }
        });
      } catch(_){}
    }
    document.querySelectorAll('#step4-bailleur [name]').forEach(el => {
      el.addEventListener('change', saveBailleur);
      el.addEventListener('input', saveBailleur);
    });
    restoreBailleur();

    // Persistance des champs copropriété
    const coproMap = {
      'rf-copro-lots':'lots', 'rf-copro-tantiemes':'tantiemes',
      'rf-copro-dpe':'dpe', 'rf-copro-annee':'annee',
      'rf-copro-fragile':'fragile', 'rf-copro-mar':'mar',
      'rf-copro-cout':'coutTravauxCollectifs', 'rf-copro-gain':'gainVise',
      'rf-copro-sortie':'sortiePassoire',
    };
    /* La question « sortie de passoire » n'a de sens que pour un immeuble F ou G. */
    function toggleSortieCopro(){
      const w = document.getElementById('rf-copro-sortie-wrap');
      const d = (document.querySelector('[name="rf-copro-dpe"]:checked') || document.querySelector('[name="rf-copro-dpe"]') || {}).value;
      if (w) w.hidden = !(d === 'F' || d === 'G');
    }
    document.addEventListener('change', e => { if (e.target && e.target.name === 'rf-copro-dpe') toggleSortieCopro(); });
    setTimeout(toggleSortieCopro, 0);
    function saveCopro(){
      try {
        const d = {};
        Object.entries(coproMap).forEach(([name, key]) => {
          const el = document.querySelector('[name="' + name + '"]:checked') || document.querySelector('[name="' + name + '"]');
          if (el) d[key] = el.value;
        });
        localStorage.setItem('junglerenov.copro', JSON.stringify(d));
      } catch(_){}
    }
    function restoreCopro(){
      try {
        const d = JSON.parse(localStorage.getItem('junglerenov.copro') || '{}');
        Object.entries(coproMap).forEach(([name, key]) => {
          if (d[key] === undefined || d[key] === '') return;
          const radios = document.querySelectorAll('input[type="radio"][name="' + name + '"]');
          if (radios.length) radios.forEach(r => { r.checked = (r.value === d[key]); });
          else { const el = document.querySelector('[name="' + name + '"]'); if (el) el.value = d[key]; }
        });
      } catch(_){}
    }
    document.querySelectorAll('#step4-copro [name]').forEach(el => {
      el.addEventListener('change', saveCopro);
      el.addEventListener('input', saveCopro);
    });
    restoreCopro();

    apply(currentOwner(), currentCase());
  })();

  /* Étape 3 — question "travaux collectifs", visible pour les appartements */
  (function initCoproCollectifs(){
    const block = document.getElementById('rf-copro-collectifs');
    if (!block) return;

    function currentTypeLogement(){ return rfGetTypeLogement(); }
    function getVal(){
      return document.querySelector('input[name="rf-copro-collectifs"]:checked')?.value || 'no';
    }
    function apply(){
      const isApart = currentTypeLogement() === 'appartement';
      block.hidden = !isApart;
      if (!isApart) {
        const noRadio = block.querySelector('input[value="no"]');
        if (noRadio) noRadio.checked = true;
        try { localStorage.setItem('junglerenov.hasCoproCollectifs', 'no'); } catch(_){}
      }
