      try { localStorage.setItem('junglerenov.hasCoproCollectifs', v); } catch(_){}
      document.dispatchEvent(new CustomEvent('rf:copro-collectifs-change', { detail:{ value: v } }));
      if (typeof window.__rfUpdateStep3Block === 'function') window.__rfUpdateStep3Block();
    }

    block.querySelectorAll('input[name="rf-copro-collectifs"]').forEach(r => r.addEventListener('change', save));

    try {
      const stored = localStorage.getItem('junglerenov.hasCoproCollectifs');
