      // « Copropriété — parties communes » n'a plus de sens pour une maison
      const legalSel = document.querySelector('select[name="rf-bailleur-legal"]');
      const coproOption = legalSel ? legalSel.querySelector('option[value="copro-communes"]') : null;
      const isApart = rfGetTypeLogement() === 'appartement';
      if (coproOption) { coproOption.disabled = !isApart; coproOption.hidden = !isApart; }
      if (!isApart && legalSel && legalSel.value === 'copro-communes') {
