  /* Étape 2 — signale un changement de type de logement */
  document.querySelectorAll('[data-radio="type"]').forEach(el => {
    el.addEventListener('click', () => {
      setTimeout(() => document.dispatchEvent(new CustomEvent('rf:type-logement-change')), 50);
    });
  });


  /* ===== Step 1 — Address autocomplete via Base Adresse Nationale (api-adresse.data.gouv.fr)
     Service officiel de l'État, gratuit, sans clé d'API. Couvre tout le territoire français (DROM-COM inclus).
     Le label retourné contient le code postal (ex: "14 Rue Pasteur 69100 Villeurbanne"), exploité par
     applyRegionFromAddress() pour pré-sélectionner la région à l'étape 4. ===== */
  const addrInput = document.getElementById('addr');
  const sugBox    = document.getElementById('addr-suggest');
  // Bandeau DPE retiré (était hardcodé en démo). Stubs no-op pour éviter de
  // casser le code historique qui essaie encore d'afficher/masquer la bannière.
  const dpeBanner = { _stub: true, hidden: true };
  const dpeYearEl = { _stub: true, textContent: '' };
  let sugActive = -1;
  let sugCurrent = [];
  let selectedAddr = null;

  function escapeHtml(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
  function highlight(label, q){
    if (!q) return escapeHtml(label);
    const re = new RegExp('('+q.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+')','ig');
    return escapeHtml(label).replace(re,'<mark style="background:transparent;color:var(--teal-700);font-weight:600">$1</mark>');
  }
  function renderSuggest(list, q){
    sugCurrent = list;
    if (!list.length){
      sugBox.hidden = true;
      return;
    }
    sugBox.hidden = false;
    sugBox.innerHTML = list.map((it,i)=>`
      <button type="button" role="option" data-idx="${i}" ${i===sugActive?'aria-selected="true"':''}>
        <span class="pin"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M20 10c0 6-8 12-8 12s-8-6-8-12a8 8 0 0 1 16 0Z"/><circle cx="12" cy="10" r="3"/></svg></span>
        <span class="lbl">${highlight(it.label, q)}</span>
        ${it.dpe?`<span class="meta">DPE ${it.dpe}</span>`:'<span class="meta" style="color:var(--slate-300)">Pas de DPE</span>'}
      </button>
    `).join('');
    sugBox.querySelectorAll('button').forEach(btn=>{
      btn.addEventListener('mousedown', e => e.preventDefault()); // keep input focus
      btn.addEventListener('click',() => pick(+btn.dataset.idx));
      btn.addEventListener('mouseenter',() => { sugActive = +btn.dataset.idx; updateActive(); });
    });
    updateActive();
  }
  function updateActive(){
    sugBox.querySelectorAll('button').forEach((b,i)=>{
      b.style.background = i===sugActive ? 'var(--slate-50)' : '';
    });
  }
  function pick(i){
    const it = sugCurrent[i];
    if (!it) return;
    addrInput.value = it.label;
    selectedAddr = it;
    sugBox.hidden = true;
    sugActive = -1;
    // Lance la récupération du DPE ADEME en async (n'attend pas l'utilisateur)
    fetchDpeFromAdeme(it).then(dpe => {
      /* Échec réseau ou adresse absente de la base : on le dit, on ne laisse pas
         l'utilisateur croire que la tuile présélectionnée vient de l'ADEME. */
      if (!dpe){
        const helpKo = document.getElementById('dpe-help');
        if (helpKo) helpKo.textContent = "Nous n'avons pas trouvé de DPE enregistré pour cette adresse : indiquez la classe de votre dernier diagnostic, ou « Je ne sais pas ».";
        return;
      }
      selectedAddr.dpe   = dpe.dpe;
      selectedAddr.dpeKwh = dpe.kwh;
      selectedAddr.dpeYear = dpe.year;
      console.info('[JungleRenov] DPE ADEME trouvé :', dpe);
      // Pré-sélectionne la tuile DPE correspondante (sans verrouiller)
      const want = (dpe.dpe || '').toUpperCase();
      if (want && /^[A-G]$/.test(want)){
        document.querySelectorAll('[data-radio="dpe"]').forEach(t => {
          t.classList.toggle('selected', (t.dataset.dpe || '').toUpperCase() === want);
        });
        const help = document.getElementById('dpe-help');
        if (help) help.innerHTML = `Pré-sélectionné depuis la base officielle ADEME (DPE ${dpe.year || ''}). Modifiez si nécessaire.`;
      }
      // Si l'année de construction n'est pas encore saisie, on la pré-remplit
      const yEl = document.getElementById('year');
      if (yEl && (!yEl.value || yEl.value === '1972') && dpe.year){
        yEl.value = dpe.year;
      }
    });
  }

  /* ===== API ADEME — récupération du vrai DPE par adresse =====
     Endpoint public, sans clé, sans authentification.
     Dataset : dpe-v2-logements-existants (DPE depuis juillet 2021, méthode harmonisée).
     Si pas de match → on retombe sur l'ancien dataset dpe-france (DPE antérieurs). */
  async function fetchDpeFromAdeme(addr){
    if (!addr || !addr.label) return null;
    const datasets = ['dpe-v2-logements-existants', 'dpe-france'];
    const select = 'etiquette_dpe,date_etablissement_dpe,conso_5_usages_par_m2_ep,annee_construction';
    for (const ds of datasets){
      try {
        const url = 'https://data.ademe.fr/data-fair/api/v1/datasets/' + ds +
                    '/lines?q=' + encodeURIComponent(addr.label) +
                    '&size=1&select=' + select;
        const res = await fetch(url);
        if (!res.ok) continue;
        const json = await res.json();
        const hit = (json.results || [])[0];
        if (!hit) continue;
        return {
          dpe:  hit.etiquette_dpe || null,
          kwh:  hit.conso_5_usages_par_m2_ep || null,
          year: hit.annee_construction || null,
          date: hit.date_etablissement_dpe || null,
          source: ds,
        };
      } catch(e){
        /* verif_dom: repli — on essaie le jeu de données suivant ; l'échec final
           est rendu visible par l'appelant (message sous les tuiles DPE). */
        console.warn('ADEME ' + ds + ' :', e);
      }
    }
    return null;
  }

  /* DPE projeté après travaux — approximation pédagogique.
     Chaque geste majeur gagne ~1 classe DPE. Bouquet ≥ 3 gestes : +1 bonus.
     Le DPE A est le plafond, on ne dépasse pas. */
  const DPE_KWH_BY_CLASS = { A:60, B:90, C:145, D:215, E:290, F:380, G:450 };

  /* Surbrillance du graphique DPE : `from` = classe actuelle (tirets),
     `to` = classe projetée (trait plein). Une seule source de vérité. */
  function updateDpeChart(dpeAvant, dpeApres){
    const bars = document.querySelectorAll('#step-7 .dpe-bar[data-classe]');
    if (!bars.length) return;
    bars.forEach(b => b.classList.remove('from', 'to'));
    const pick = c => document.querySelector('#step-7 .dpe-bar[data-classe="' + c + '"]');
    const a = dpeAvant && pick(String(dpeAvant).toUpperCase());
    if (a) a.classList.add('from');
    const z = dpeApres && pick(String(dpeApres).toUpperCase());
    if (z) z.classList.add('to');
  }

  const DPE_LEVELS = ['G','F','E','D','C','B','A'];
  function projectedDpe(currentDpe, selection){
    let idx = DPE_LEVELS.indexOf((currentDpe || 'E').toUpperCase());
    if (idx < 0) idx = DPE_LEVELS.indexOf('E');
    let bonus = 0;
    if (selection.includes('combles')) bonus += 1;
    if (selection.includes('ite')) bonus += 1;
    if (selection.includes('pac_aireau') || selection.includes('biomasse')) bonus += 1;
    if (selection.length >= 3) bonus += 1; // bouquet rénovation d'ampleur
    return DPE_LEVELS[Math.min(idx + bonus, DPE_LEVELS.length - 1)];
  }
  // Debounce + race protection pour les appels API
  let banDebounce = null;
  let banLastQuery = '';

  function filter(q){
    const norm = q.trim();
    clearTimeout(banDebounce);
    if (norm.length < 3){
      sugBox.hidden = true;
      return;
    }
    banDebounce = setTimeout(() => fetchBan(norm), 250);
  }

  async function fetchBan(q){
    if (q === banLastQuery) return;
    banLastQuery = q;
    try {
      const url = 'https://api-adresse.data.gouv.fr/search/?q=' +
                  encodeURIComponent(q) + '&limit=6&autocomplete=1';
      const res = await fetch(url);
      if (!res.ok) throw new Error('BAN HTTP ' + res.status);
      const json = await res.json();
      // Si une requête plus récente a été lancée entre-temps, on ignore.
      if (q !== banLastQuery) return;
      const list = (json.features || []).map(f => ({
        label:    f.properties.label,
        postcode: f.properties.postcode,
        city:     f.properties.city,
        context:  f.properties.context, // ex: "69, Rhône, Auvergne-Rhône-Alpes"
      }));
      sugActive = list.length ? 0 : -1;
      renderSuggest(list, q);
    } catch(e) {
      console.warn('Base Adresse Nationale :', e);
      sugBox.hidden = true;
      /* Un catch qui n'écrit qu'en console n'est pas un traitement d'erreur :
         l'utilisateur doit savoir qu'il peut continuer sans suggestion. */
      let banMsg = document.getElementById('addr-ban-msg');
      if (!banMsg && addrInput.parentNode){
        banMsg = document.createElement('p');
        banMsg.id = 'addr-ban-msg'; banMsg.className = 'field-help'; banMsg.setAttribute('role', 'status');
        addrInput.parentNode.appendChild(banMsg);
      }
      if (banMsg) banMsg.textContent = "Le service d'adresses ne répond pas. Continuez en saisissant votre adresse complète, avec le code postal : il suffit au calcul.";
    }
  }
