  function detectDept(addrLabel){
    if (!addrLabel) return null;
    // 2A/2B Corse d'abord
    const m2 = addrLabel.match(/\b(2A|2B)\d{3}\b/i);
    if (m2) return m2[1].toUpperCase();
    const m = addrLabel.match(/\b(\d{5})\b/);
    if (!m) return null;
    const cp = m[1];
    // 20xxx → Corse (approximation, mais région correcte)
    if (cp.startsWith('20')) return '2A';
    return cp.slice(0,2);
  }
