  /* ===== Étape 5 — animation du calcul (auto-advance) ===== */
  let calcTimers = [];
  function stopCalcAnimation(){ calcTimers.forEach(t=>clearTimeout(t)); calcTimers = []; }
  function startCalcAnimation(){
    stopCalcAnimation();
    const items   = document.querySelectorAll('#loader-checks .lc-item');
    const circle  = document.getElementById('loader-circle');
    const pctEl   = document.getElementById('loader-pct');
    const titleEl = document.getElementById('loader-title');
    const subEl   = document.getElementById('loader-sub');
    const subs = [
      'Sources : Base Adresse Nationale + IGN',
      'Sources : observatoire DPE ADEME (open data)',
      'Sources : barèmes Anah publiés au JO',
      'Sources : ATEE — fournisseurs d’énergie certifiés',
      'Sources : conseils régionaux, métropoles, intercommunalités',
      'Projection du DPE après travaux',
    ];
    // Reset visuel
    items.forEach(it => {
      it.classList.remove('done','active');
      it.querySelector('.ic').innerHTML = '<svg width="10" height="10" viewBox="0 0 24 24" fill="currentColor"><circle cx="12" cy="12" r="6"/></svg>';
    });
    circle.style.setProperty('--p','0%');
    pctEl.textContent = '0%';
    titleEl.textContent = 'Connexion aux bases officielles…';
    subEl.textContent   = 'Quelques secondes, ne fermez pas la fenêtre.';

    // Anim : 6 étapes, ~900ms chacune
    const stepDur = 900;
    items.forEach((it, i) => {
      // Activate
      calcTimers.push(setTimeout(() => {
        if (cur !== 6) return;
        items.forEach(x => x.classList.remove('active'));
        it.classList.add('active');
        it.querySelector('.ic').innerHTML = '<span class="spinner"></span>';
        titleEl.textContent = it.dataset.lbl;
        subEl.textContent   = subs[i] || '';
      }, i * stepDur));
      // Mark done
      calcTimers.push(setTimeout(() => {
        if (cur !== 6) return;
        it.classList.remove('active');
        it.classList.add('done');
        it.querySelector('.ic').innerHTML = '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="m5 12 5 5L20 7"/></svg>';
        const pct = Math.round(((i+1) / items.length) * 100);
        circle.style.setProperty('--p', pct + '%');
        pctEl.textContent = pct + '%';
      }, (i + 1) * stepDur));
    });
    // Auto-advance vers étape 7 (résultats)
    calcTimers.push(setTimeout(() => {
      if (cur === 6) {
        titleEl.textContent = 'Analyse terminée';
        subEl.textContent   = 'Affichage de vos résultats…';
      }
    }, items.length * stepDur));
    calcTimers.push(setTimeout(() => {
      if (cur === 6) goTo(7);
    }, items.length * stepDur + 600));
  }

