  function pwdStrength(pwd){
    if (!pwd) return { score: 0, label: '', help: '', barColor: 'var(--slate-200)' };
    let score = 0;
    const tips = [];
    // Longueur
    if (pwd.length >= 10) score++;
    else tips.push('au moins 10 caractères');
    if (pwd.length >= 14) score++;
    // Variété : majuscule + minuscule + chiffre + symbole
    let varieties = 0;
    if (/[a-z]/.test(pwd)) varieties++;
    if (/[A-Z]/.test(pwd)) varieties++;
    if (/[0-9]/.test(pwd)) varieties++;
    if (/[^a-zA-Z0-9]/.test(pwd)) varieties++;
    if (varieties >= 3) score++;
    else tips.push('mélangez majuscules, chiffres et symboles');
    if (varieties === 4 && pwd.length >= 12) score++;
    // Pénalité : mot de passe trivial
    const lower = pwd.toLowerCase();
    if (PWD_TRIVIAUX.some(t => lower.includes(t))){
      score = Math.max(0, score - 2);
      tips.unshift('évitez les mots de passe courants (ex : "azerty", "motdepasse")');
    }
    // Pénalité : que des chiffres ou que des lettres
    if (/^\d+$/.test(pwd) || /^[a-zA-Z]+$/.test(pwd)){
      score = Math.max(0, score - 1);
    }
    const labels = ['Très faible','Faible','Acceptable','Bon','Excellent'];
    const colors = ['#991B1B','#123A2E','#123A2E','#1F6B3F','#065F46'];
    return {
      score,
      label: labels[score],
      help: tips.length ? 'Pour renforcer : ' + tips.join(' · ') : 'Excellent mot de passe.',
      barColor: colors[score],
    };
  }
  function renderPwdStrength(){
