  /* Cascade de secours : calcul direct, puis aides déjà enregistrées dans le
     profil, puis rejeu du moteur depuis ce profil. Garantit qu'aucun dossier ne
     part avec result: null — c'était la cause du « Estimation à recalculer ». */
  function resoudreAides(){
    var prev = {};
    try { prev = JSON.parse(localStorage.getItem('junglerenov.profile') || '{}'); } catch(e){}
    var ok = function(a){ return !!(a && a.totalAides > 0); };
    try {
      var r = computeAids();
      if (ok(r)) return r;
    } catch(e){ console.warn('[Transmission] computeAids() a échoué :', e); }
    if (ok(prev.aids)) return prev.aids;
    try {
      if (window.RFCompute && RFCompute.recomputeFromProfile){
        var r2 = RFCompute.recomputeFromProfile();
        if (ok(r2)) return r2;
      }
    } catch(e){ console.warn('[Transmission] rejeu depuis le profil impossible :', e); }
    return null;
  }

  function finalizeTransmission(){
      // Validation AVANT tout : ni confirmation, ni dossier, si le calcul
      // n'aboutit pas.
      var aidesValidees = resoudreAides();
      if (!aidesValidees){
        console.error('[Transmission] aides incalculables — création du dossier abandonnée');
        afficherEchecCalcul();
