      const fn = document.getElementById('su-firstname').value.trim();
      const ln = document.getElementById('su-lastname').value.trim();

      // Persistance du projet pour le dashboard
      // FIX : préserve toutes les données sauvegardées pendant la simulation
      // (address, logement, situation, foyer, aids, diagnostiqueLe) en utilisant ...prev.
      // Et garde les anciennes aides si computeAids() renvoie 0 (cas où les inputs
      // de la simulation ne sont plus accessibles au moment de la transmission).
      try {
        const prev = JSON.parse(localStorage.getItem('junglerenov.profile') || '{}');
        console.group('[JungleRenov] Pipeline de sauvegarde après transmission');
        console.log('1️⃣ prev (localStorage avant écrasement) :', prev);

        // Recompute les aides — fallback complet sur les valeurs par défaut si
        // les inputs sont vides (parseRFR/parseSurface/parseHeat/parseRegion
        // ont tous des fallbacks intégrés).
        // Valeur déjà validée en tête de fonction par resoudreAides().
        const validAids = aidesValidees;
        console.log('2️⃣ validAids retenu :', validAids, '· total =', validAids.totalAides);

        // Relit tous les champs de la simulation en direct (au cas où injectResults
        // n'aurait pas tourné) pour garantir que le profil contient tout ce qu'il
        // faut pour alimenter dashboard / mon-profil / mes-aides.
        const $val = (id) => { const el = document.getElementById(id); return el ? el.value : ''; };
        const $tile = (group) => {
          const el = document.querySelector('[data-radio="' + group + '"].selected .nm');
          return el ? el.textContent.trim() : null;
        };
        const addressNow = $val('addr').trim() || prev.address || '';
        const surfaceNow = parseInt($val('surf'), 10) || (prev.logement && prev.logement.surface) || null;
        const yearNow    = parseInt($val('year'), 10) || (prev.logement && prev.logement.year)    || null;
        const typeNow    = $tile('type')   || (prev.logement && prev.logement.type)   || null;
        const heatRaw    = $tile('heat')   || null;
        const heatNow    = heatRaw ? heatRaw.toLowerCase().replace('é','e').split(' ')[0] : ((prev.logement && prev.logement.heat) || null);
        const statusNow  = $tile('status') || (prev.situation && prev.situation.status)   || null;
