        const partsSel   = document.getElementById('parts');
        const partsNow   = partsSel ? (partsSel.selectedIndex + 1) : ((prev.foyer && prev.foyer.parts) || null);
        const regionNow  = $val('region-select') || (prev.foyer && prev.foyer.region) || null;

        const emailVal = document.getElementById('su-email').value.trim();

        const profileNext = {
          ...prev,
          firstname: fn,
          lastname: ln,
          email: emailVal,
          createdAt: prev.createdAt || new Date().toISOString(),
          address: addressNow,
          logement: {
            ...(prev.logement || {}),
            // Le dashboard et mes-aides lisent `logement.adresse` pour les 3 types
            // de dossiers : sans cette clé, la card énergétique n'affiche rien.
            adresse:    addressNow || null,
            codePostal: (addressNow.match(/\b\d{5}\b/) || [null])[0],
            dept:       (addressNow.match(/\b(\d{2})\d{3}\b/) || [null, null])[1],
