            dpeKwh:  (selectedAddr && selectedAddr.dpeKwh) || (prev.logement && prev.logement.dpeKwh) || null,
          },
          situation: {
            ...(prev.situation || {}),
            status:   statusNow,
            budget:   budgetNow,
            priorite: prioNow,
          },
          foyer: {
            ...(prev.foyer || {}),
            rfr:    rfrNow,
            parts:  partsNow,
            region: regionNow,
          },
          travaux: getSelectedWorks() || prev.travaux || [],
          aids: validAids,
          diagnostiqueLe: prev.diagnostiqueLe || new Date().toISOString(),
        };
        localStorage.setItem('junglerenov.profile', JSON.stringify(profileNext));

        // Multi-dossiers : la transmission crée UN dossier, consigné avec le
        // professionnel destinataire et la preuve du consentement donné.
        try {
          if (window.RFDossiers && validAids && validAids.totalAides > 0){
            var pro = window.__rfPro || null;
            var dosEnergetique = RFDossiers.createTransmis('energetique', profileNext, validAids, {
              partenaireNom: pro && pro.nom,
              partenaireRole: pro && pro.role,
              departement: pro && pro.departement,
              consentementTransmission: {
                donneLe: new Date().toISOString(),
                destinataire: (pro && pro.nom) || ('Accompagnateur agréé ' + ((pro && pro.role) || '')),
                finalite: "Dépôt et suivi du dossier d'aides auprès de l'Anah",
              },
            });
            window.__rfDossierId = dosEnergetique && dosEnergetique.id;
          }
        } catch(eD){ console.warn('Création dossier :', eD); }
        console.log('5️⃣ profil écrit dans localStorage :', profileNext);
        console.log('   ↳ aids.totalAides =', profileNext.aids && profileNext.aids.totalAides);
        console.groupEnd();

        // Pousse ou met à jour le client dans la base partagée `junglerenov.clients`
        // (consommée par l'admin et par la rehydratation dashboard).
        try {
          const clients = JSON.parse(localStorage.getItem('junglerenov.clients') || '[]');
          const idx = clients.findIndex(c => c.email && c.email.toLowerCase() === emailVal.toLowerCase());
          const clientEntry = {
            id: (idx >= 0 ? clients[idx].id : 'client-' + Math.random().toString(36).slice(2, 9) + Date.now().toString(36).slice(-3)),
            email: emailVal,
            firstname: fn,
            lastname: ln,
            address: profileNext.address || '',
            logement: profileNext.logement || {},
            situation: profileNext.situation || {},
            foyer: profileNext.foyer || {},
            travaux: profileNext.travaux || [],
            aids: validAids,
            createdAt: profileNext.createdAt,
            diagnostiqueLe: profileNext.diagnostiqueLe || new Date().toISOString(),
            status: 'actif',
          };
          if (idx >= 0) clients[idx] = { ...clients[idx], ...clientEntry };
          else clients.push(clientEntry);
          localStorage.setItem('junglerenov.clients', JSON.stringify(clients));

          // Ouvre la session client (auto-login) — l'utilisateur arrive connecté sur le dashboard.
          localStorage.setItem('junglerenov.session', JSON.stringify({
            id: clientEntry.id,
            email: clientEntry.email,
            role: 'client',
            firstname: clientEntry.firstname,
            lastname: clientEntry.lastname,
            loggedAt: Date.now(),
          }));
        } catch(e2){ console.warn('Sauvegarde client/session :', e2); }
      } catch(e) { console.warn('Sauvegarde profil :', e); }
      const partEl = document.getElementById('succ-partenaire');
      if (partEl){
        const pro2 = window.__rfPro;
        partEl.textContent = (pro2 && pro2.nom)
          ? pro2.nom
          : "Un accompagnateur agréé de votre département";
      }
      succ.classList.add('show');
      /* Le dossier est créé : c'est maintenant, et seulement maintenant, que la
         progression est complète. */
      const pb = document.getElementById('prog-bar'); if (pb) pb.style.width = '100%';
      const pp = document.getElementById('prog-pct'); if (pp) pp.textContent = '100 %';
      jrScrollTo(succ);
      document.querySelector('.footer-nav').style.display = 'none';
      let n = 4;
      const cd = document.getElementById('succ-cd');
      // Le détail des aides est l'atterrissage attendu après transmission,
      // comme sur MPA et LHI : on ouvre le dossier tout juste créé.
      let dest = 'mes-aides.dc.html';
      if (window.__rfDossierId) dest += '?dossier=' + encodeURIComponent(window.__rfDossierId) + '&transmis=1';
      else dest += '?transmis=1';
      try {
        // Les anciennes pages de résultats MPA / LHI ont été supprimées : toute
        // destination de retour héritée est purgée sans être suivie.
        localStorage.removeItem('junglerenov.returnTo');
      } catch(e){}
      const timer = setInterval(() => {
        n--;
        if (n <= 0){ clearInterval(timer); location.href = dest; }
        else cd.textContent = `Redirection vers votre dossier dans ${n}…`;
      }, 1000);
  }

  document.getElementById('su-submit').addEventListener('click', function(){
    if (this.disabled) return;
    finalizeTransmission();
  });

  /* ===== Moteur de calcul d'aides 2026 — barèmes officiels ANAH / ATEE ===== */

  /* Moteur de calcul : délégué à _compute_aids.js (barèmes Anah 2026).
     Les tables PLAFONDS / MPR / CEE / AIDES_LOCALES et les fonctions
     plafond() / categorie() vivent désormais dans ce module unique. */
  const plafond   = (zone, cat, foyer) => window.RFCompute.plafond(zone, cat, foyer);
  const categorie = (rfr, foyer, region) => window.RFCompute.categorie(rfr, foyer, region);

  function parseRFR(){
    const v = (document.getElementById('rfr').value || '').replace(/[^\d]/g,'');
    const n = parseInt(v, 10);
    return Number.isFinite(n) && n > 0 ? n : null;
  }
  function parseFoyer(){
    const sel = document.getElementById('parts');
    return sel ? (sel.selectedIndex + 1) : 4;
  }
  function parseSurface(){
    return parseInt(document.getElementById('surf').value, 10) || 110;
  }
  function parseDpe(){
    const sel = document.querySelector('[data-radio="dpe"].selected');
    if (!sel) return '';
    return (sel.dataset.dpe || '').toUpperCase();
  }
  function parseHeat(){
    const sel = document.querySelector('[data-radio="heat"].selected');
    if (!sel) return 'fioul';
    const nm = (sel.querySelector('.nm')?.textContent || '').toLowerCase();
    if (nm.startsWith('gaz')) return 'gaz';
    if (nm.startsWith('fioul')) return 'fioul';
    if (nm.startsWith('élect') || nm.startsWith('elec')) return 'electrique';
    if (nm.startsWith('bois')) return 'bois';
    return 'fioul';
  }
  function parseRegion(){
    return document.getElementById('region-select').value || 'Auvergne-Rhône-Alpes';
  }

  function computeAids(){
    const sel = getSelectedWorks();
    return window.RFCompute.compute({
      surface:   parseSurface(),
      foyer:     parseFoyer(),
      rfr:       parseRFR() || 32000,
      region:    parseRegion(),
      heat:      parseHeat(),
      dept:         document.getElementById('dept')?.value || null,
      epci:         document.getElementById('epci')?.value || null,
      typeLogement: (document.querySelector('[data-radio="type"].selected .nm')?.textContent || 'maison').toLowerCase().includes('maison') ? 'maison' : 'appartement',
      hasCoproCollectifs: (function(){ try { return localStorage.getItem('junglerenov.hasCoproCollectifs') || 'no'; } catch(_){ return 'no'; } })(),
      copro:        (function(){ try { return JSON.parse(localStorage.getItem('junglerenov.copro') || '{}'); } catch(_){ return {}; } })(),
      dpeCurrent:   parseDpe() || null,
      oldWoodStove: document.querySelector('[data-radio="oldwood"].selected')?.dataset.oldwood === 'yes',
      status:            (document.querySelector('[data-radio="status"].selected .nm')?.textContent || 'occupant').toLowerCase(),
      // Champs bailleur — mêmes noms de clés que computeBailleur() et recomputeFromProfile()
      ownerType:   (function(){ try { return localStorage.getItem('junglerenov.ownerType') || 'occupant'; } catch(_){ return 'occupant'; } })(),
      // Cas bailleur agrégé (particulier-nu / indivision-nu / sci-ir-nu / sci-is /
      // meuble / saisonnier / copro). Sans cette clé, compute() retombe sur
      // particulier-nu et n'atteint jamais computeBailleurRestreint() ni computeCopro().
      bailleurCase: (function(){ try { return window.__rfBailleurCase || localStorage.getItem('junglerenov.bailleurCase') || 'occupant'; } catch(_){ return 'occupant'; } })(),
      rent:        Number(document.querySelector('#rf-rent-amount')?.value) || 0,
      nbLogementsBailleur: Number(document.querySelector('#rf-nb-logements')?.value) || 1,
      zone:        document.querySelector('select[name="rf-zone"]')?.value || null,
      locLevel:    document.querySelector('input[name="rf-loc-level"]:checked')?.value || 'none',
      locDuration: Number(document.querySelector('select[name="rf-loc-duration"]')?.value) || 6,
      lpe:         document.querySelector('input[name="rf-lpe"]:checked')?.value || 'no',
      // Compatibilité descendante (branche occupant)
      locAvantagesLevel: (function(){ const v = document.querySelector('input[name="rf-loc-level"]:checked')?.value; return (!v || v === 'none') ? null : v; })(),
      rentToMobility:    document.querySelector('input[name="rf-lpe"]:checked')?.value === 'yes',
      selection: sel.length ? sel : ['combles','ite','pac_aireau'],
    });
  }

  const CAT_LABELS = {
    bleus:   'Très modestes (bleus)',
    jaunes:  'Modestes (jaunes)',
    violets: 'Intermédiaires (violets)',
    roses:   'Supérieurs (roses)',
  };

  /* ═══ ÉTAPE 7 : carte unique « Votre projet » ═══
     Un seul résultat, celui de la saisie utilisateur. Aucun geste ajouté ni retiré. */
  const RF_LIBELLES_TRAVAUX = {
    combles:                   'Isolation combles',
    ite:                       'Isolation des murs par l’extérieur',
    iti:                       'Isolation des murs par l’intérieur',
    sarking:                   'Isolation toiture (sarking)',
    toiture_terrasse:          'Isolation toiture-terrasse',
    plancher_bas:              'Isolation plancher bas',
    menuiseries:               'Fenêtres / menuiseries',
    pac_aireau:                'PAC air/eau',
    pac_geothermique:          'PAC géothermique',
    chauffe_eau_thermo:        'Chauffe-eau thermodynamique',
    chauffe_eau_solaire:       'Chauffe-eau solaire',
    chauffage_solaire_combine: 'Chauffage solaire combiné',
    pvt_eau:                   'Panneaux PVT eau',
    poele_buches:              'Poêle à bûches',
    poele_granules:            'Poêle à granulés',
    insert_foyer:              'Insert / foyer fermé',
    biomasse:                  'Chaudière biomasse',
    raccordement_reseau:       'Raccordement réseau de chaleur',
    audit_energetique:         'Audit énergétique',
    depose_cuve_fioul:         'Dépose cuve à fioul',
    vmc_df:                    'VMC double flux',
  };

  /* Remplit la carte unique à partir du résultat déjà calculé pour l'étape 7.
     `r` est la valeur renvoyée par RFCompute.compute() sur la saisie utilisateur :
     aucun second calcul, donc aucune divergence possible avec l'étape 8. */
  function renderProjetUnique(r, selection, dpeAvant, dpeApres){
    if (!r) return;
    const fmt = v => (v == null ? '—' : Math.round(v).toLocaleString('fr-FR') + ' €');
    const setTxt = (id, v) => { const el = document.getElementById(id); if (el) el.textContent = v; };

    const listeEl = document.getElementById('rf-liste-travaux');
    if (listeEl){
      const sel = Array.isArray(selection) ? selection : [];
      listeEl.innerHTML = sel.length
        ? sel.map(g => '<li>' + (RF_LIBELLES_TRAVAUX[g] || g) + '</li>').join('')
        : '<li class="is-empty">Aucun geste sélectionné</li>';
    }

    const coutTTC    = (r.travaux && r.travaux.totalTTC) || 0;
    const totalAides = r.totalAides || 0;
    setTxt('rf-cout-travaux', fmt(coutTTC));
    // Total des aides : montant exact, identique sur tous les écrans
    setTxt('rf-total-aides', fmt(totalAides));
    // Reste à charge : basé sur le vrai total aides — cohérence exacte sur tous les écrans
    setTxt('rf-reste-charge', fmt(Math.max(0, coutTTC - totalAides)));

    // Classes DPE reçues de l'appelant : jamais recalculées ici, sinon les blocs
    // se désynchronisent du graphique.
    const avant = (dpeAvant || 'E').toUpperCase();
    setTxt('rf-dpe-avant', avant);
    setTxt('rf-dpe-apres', (dpeApres || avant).toUpperCase());

    /* Transparence MAR : le besoin d'accompagnement dépend du nombre de gestes
       et du saut de classes DPE — les deux sont connus ici. */
    try {
      if (window.rfMarRefresh) {
        const apres = (dpeApres || avant).toUpperCase();
        const gain = Math.max(0, DPE_LEVELS.indexOf(apres) - DPE_LEVELS.indexOf(avant));
        window.rfMarRefresh({
          gestes: selection || [],
          gainClassesDPE: gain,
          profilAnah: categorie(parseRFR(), parseFoyer(), parseRegion())
        });
      }
    } catch (e) { console.warn('Transparence MAR :', e); }
  }

  function injectResults(){
    const r = computeAids();
    const fmt = n => n.toLocaleString('fr-FR') + ' €';

    // Persistance dès la simulation — alimente mes-aides, dashboard, etc.
    try {
      const prev = JSON.parse(localStorage.getItem('junglerenov.profile') || '{}');
      const addrInputEl = document.getElementById('addr');
      const surf = document.getElementById('surf');
      const year = document.getElementById('year');
      // Budget sélectionné
      const budgetTile = document.querySelector('[data-radio="budget"].selected .nm');
      // Priorité
      const prioTile   = document.querySelector('[data-radio="prio"].selected .nm');
      // Type de logement
      const typeTile   = document.querySelector('[data-radio="type"].selected .nm');
      // Statut occupant/bailleur
      const statTile   = document.querySelector('[data-radio="status"].selected .nm');
      localStorage.setItem('junglerenov.profile', JSON.stringify({
        ...prev,
        address: addrInputEl?.value || prev.address,
        logement: {
          type:    typeTile?.textContent || null,
          surface: parseInt(surf?.value, 10) || null,
          year:    parseInt(year?.value, 10) || null,
          heat:    r.profile.heat,
          dpe:     parseDpe() || null,
          dept:    document.getElementById('dept')?.value || null,
          epci:    document.getElementById('epci')?.value || null,
          dpeCurrent: parseDpe() || null,
          oldWoodStove: document.querySelector('[data-radio="oldwood"].selected')?.dataset.oldwood === 'yes',
        },
        situation: {
          status:  statTile?.textContent || null,
          budget:  budgetTile?.textContent || null,
          priorite:prioTile?.textContent  || null,
          locAvantagesLevel: (function(){ const v = document.querySelector('input[name="rf-loc-level"]:checked')?.value; return (!v || v === 'none') ? null : v; })(),
          rentToMobility: document.querySelector('input[name="rf-lpe"]:checked')?.value === 'yes',
        },
        foyer:    (function(){
          const f = { region: r.profile.region };
          if (r.profile.rfr   !== undefined) f.rfr   = r.profile.rfr;
          if (r.profile.foyer !== undefined) f.parts = r.profile.foyer;
          if (r.profile.cat   !== undefined) f.cat   = r.profile.cat;
          return f;
        })(),
        travaux:  getSelectedWorks(),
        aids:     r,
        diagnostiqueLe: new Date().toISOString(),
      }));
    } catch(e){ console.warn('Sauvegarde diagnostic :', e); }

    // Sous-titre
    const sub = document.querySelector('#step-7 .q-sub');
    const isBailleurRes = r.profile && r.profile.ownerType === 'bailleur';
    const LOC_LABELS = { loc1:"Loc1 (−15 %)", loc2:"Loc2 (−30 %)", loc3:"Loc3 (−45 %)" };
    (function renderSubtitle(){
      /* Date des BARÈMES, lue dans le référentiel du moteur — jamais la date de
         la visite, qui ferait paraître l'estimation toujours à jour. */
      const dateFR = (function(){
        const v = (r.referentiel && r.referentiel.version) || (window.RFCompute && RFCompute.REFERENTIEL && RFCompute.REFERENTIEL.version);
        if (!v) return 'la date indiquée en pied de page';
        const d = new Date(v + 'T00:00:00');
        const j = d.getDate();
        return (j === 1 ? '1<sup>er</sup>' : j) + ' ' + d.toLocaleDateString('fr-FR', { month: 'long', year: 'numeric' });
      })();
      const bc = r.profile.bailleurCase;
      let profilTxt;
      switch (bc) {
        case 'sci-is':
          profilTxt = "<b>Bailleur — SCI à l'IS</b> — aides limitées aux CEE, à l'éco-PTZ et à la TVA 5,5 %, " + (r.profile.region || 'France') + '.'; break;
        case 'meuble':
          profilTxt = "<b>Bailleur — location meublée</b> — aides limitées aux CEE, à l'éco-PTZ et à la TVA 5,5 %, " + (r.profile.region || 'France') + '.'; break;
        case 'saisonnier':
          profilTxt = "<b>Bailleur — location saisonnière</b> — seul le dispositif CEE est applicable, " + (r.profile.region || 'France') + '.'; break;
        case 'copro': {
          const cp = r.profile.copro || {};
          profilTxt = '<b>Copropriétaire</b> — travaux collectifs sur parties communes, ' + (cp.tantiemes || 0) + '/10 000 tantièmes, ' + (r.profile.region || 'France') + '.';
          break;
        }
        case 'particulier-nu':
        case 'indivision-nu':
        case 'sci-ir-nu': {
          const lvl = r.profile.locLevel && r.profile.locLevel !== 'none'
                        ? (LOC_LABELS[r.profile.locLevel] || r.profile.locLevel)
                        : 'aucun engagement';
          profilTxt = '<b>Bailleur</b> — loyer envisagé ' + fmt(r.profile.rent || 0) + "/mois, engagement Loc'Avantages <b>" + lvl +
                      '</b>, durée ' + (r.profile.locDuration || 6) + ' ans, ' + (r.profile.region || 'France') + '.';
          break;
        }
        default:
          profilTxt = 'foyer <b>' + CAT_LABELS[r.profile.cat] + '</b>, RFR ' + fmt(r.profile.rfr).replace(' €','') + ' €, ' +
                      r.profile.foyer + ' personne' + (r.profile.foyer > 1 ? 's' : '') + ', ' + r.profile.region + '.';
      }
      if (sub) sub.innerHTML = 'Estimation indicative basée sur les barèmes officiels en vigueur au <b>' + dateFR + '</b>. Profil retenu : ' + profilTxt;
    })();

    // Bloc total
    const tot   = document.querySelector('#step-7 .total-card .val');
    const total = document.querySelector('#step-7 .total-card .sub');
    if (tot) {
      // Le total affiché est le montant exact calculé pour ce profil.
      tot.textContent = fmt(r.totalAides);
    }
    if (total) {
      const ttc = r.travaux.totalTTC || 0;
      const pct = ttc > 0 ? Math.round(r.totalAides / ttc * 100) : 0;
      total.innerHTML = ttc > 0
        ? `pour ${fmt(ttc)} TTC de travaux · soit <b>${pct} %</b> de prise en charge`
        : `Sélectionnez vos travaux à l'étape 5 pour obtenir une estimation chiffrée.`;
    }
    // Lead magnet : expose le résultat courant et révèle le bloc avec le bon montant
    window.__rfCurrentResult = r;
    /* Le moteur pose un bloc `alertes` que rien ne lisait : sans ça, un
       utilisateur qui coche l'isolation des combles seule reçoit 0 € sans
       aucune explication. On affiche aussi la version des barèmes, plutôt
       que la date de la visite. */
    if (window.RFAlertes){
      try {
        RFAlertes.rendre(r, 'rf-alertes');
        var piedRef = document.getElementById('rf-referentiel');
        if (!piedRef){
          piedRef = document.createElement('div');
          piedRef.id = 'rf-referentiel';
          var hote = document.getElementById('rf-projet-unique');
          if (hote && hote.parentNode) hote.parentNode.insertBefore(piedRef, hote.nextSibling);
        }
        RFAlertes.rendreReferentiel(r, piedRef);
      } catch(eA){ console.warn('Affichage des alertes :', eA); }
    }
    updateLeadMagnetAmount(r.totalAides);
    // Bandeau rénovation d'ampleur / écrêtement
    const ampl = r.aides.mpr && r.aides.mpr.isRenovAmpleur;
    let noteEl = document.getElementById('step7-ampleur-note');
    if (!noteEl && total){
      noteEl = document.createElement('div');
      noteEl.id = 'step7-ampleur-note';
      noteEl.style.cssText = 'margin-top:12px;padding:10px 14px;border-radius:6px;font-size:17px;line-height:1.5;position:relative';
      total.parentElement.appendChild(noteEl);
    }
    if (noteEl){
      const ecr = r.aides.ecretement;
      const ecrOn = !!(ecr && (ecr.applied || ecr.applique));
      const ecrTxt = ecrOn ? ' Le total est plafonné par l\'écrêtement réglementaire.' : '';
      if (ampl){
        noteEl.style.background = 'rgba(255,255,255,.14)';
        noteEl.style.color = '#FFFFFF';
        noteEl.innerHTML = `<b>Rénovation d'ampleur</b> — plafond majoré (${fmt(r.aides.mpr.plafondHT)} HT), taux ${Math.round(r.aides.mpr.taux*100)} % + forfait MAR ${fmt(r.aides.mpr.forfaitMar)}. Accompagnateur agréé obligatoire.${ecrTxt}`;
        noteEl.style.display = 'block';
        showFranceRenovNotice(true);
      } else if (r.profile.cat === 'roses'){
        noteEl.style.background = 'rgba(255,255,255,.14)';
        noteEl.style.color = '#FFFFFF';
        noteEl.innerHTML = `<b>Ressources supérieures</b> — non éligible à MaPrimeRénov' par geste en 2026. Les CEE et la TVA 5,5 % restent accessibles.`;
        noteEl.style.display = 'block';
        showFranceRenovNotice(false);
      } else if (ecr && ecr.applied){
        noteEl.style.background = 'rgba(255,255,255,.14)';
        noteEl.style.color = '#FFFFFF';
        noteEl.innerHTML = `Total plafonné par l'écrêtement réglementaire MPR + CEE.`;
        noteEl.style.display = 'block';
        showFranceRenovNotice(false);
      } else {
        noteEl.style.display = 'none';
        showFranceRenovNotice(false);
      }
    }

    // Lignes du breakdown
    const rows = document.querySelectorAll('#step-7 .breakdown .br-row');
    if (rows.length >= 5){
      const mprTag = r.profile.cat && CAT_LABELS[r.profile.cat]
                       ? `forfaits ${CAT_LABELS[r.profile.cat].toLowerCase()}, Anah`
                       : 'Bailleur — grille unique, Anah';
      // Cas restreints : aucune MPR, on masque la ligne au lieu d'afficher 0 €
      if (r.aides.mpr && r.aides.mpr.variant === 'restreint') {
        rows[0].style.display = 'none';
      } else if (r.profile.bailleurCase === 'copro') {
        rows[0].style.display = '';
        const partPerso = (r.aides.mprCopro && r.aides.mprCopro.partPersonnelle) || 0;
        const tant = (r.profile.copro && r.profile.copro.tantiemes) || 0;
        rows[0].innerHTML = `<span>MaPrimeRénov' Copropriété <em style="font-style:normal;opacity:.65;font-size:17px">— part personnelle (${tant}/10 000)</em></span><span>${fmt(partPerso)}</span>`;
      } else {
        rows[0].style.display = '';
        rows[0].innerHTML = `<span>MaPrimeRénov' <em style="font-style:normal;opacity:.65;font-size:17px">— ${mprTag}</em></span><span>${fmt(r.aides.mpr.total)}</span>`;
      }
      if (r.aides.cee && r.aides.cee.cumulBloque) {
        rows[1].innerHTML = `<span>CEE <em style="font-style:normal;opacity:.65;font-size:17px">— non cumulable avec MaPrimeRénov' ampleur</em></span><span style="opacity:.55">non cumulable</span>`;
      } else rows[1].innerHTML = `<span>CEE <em style="font-style:normal;opacity:.65;font-size:17px">— Coup de pouce ${r.aides.cee.tier === 'precaire' ? 'précaires' : 'standard'}, ATEE</em></span><span>${fmt(r.aides.cee.total)}</span>`;
      if (r.aides.local && r.aides.local.nom && r.aides.local.total > 0){
        rows[2].innerHTML = `<span>${r.aides.local.nom}</span><span>${fmt(r.aides.local.total)}</span>`;
        rows[2].style.display = '';
      } else if (isBailleurRes && r.aides.locAvantages && (r.aides.locAvantages.prime || 0) > 0){
        rows[2].innerHTML = `<span>Loc'Avantages <em style="font-style:normal;opacity:.65;font-size:17px">— prime Anah</em></span><span>${fmt(r.aides.locAvantages.prime || 0)}</span>`;
        rows[2].style.display = '';
      } else {
        rows[2].style.display = 'none';
      }
      // Réduction d'impôt Loc'Avantages : hors cumul (étalée sur la durée d'engagement),
      // affichée à part pour que la somme des lignes réconcilie le total.
      (function renderRiRow(){
        document.querySelectorAll('#step-7 .breakdown .br-row-ri').forEach(el => el.remove());
        const ri = Number(r.reductionImpot) || 0;
        if (!isBailleurRes || ri <= 0) return;
        const dur = (r.profile && r.profile.locDuration) || 9;
        const bd = document.querySelector('#step-7 .breakdown');
        if (!bd) return;
        const row = document.createElement('div');
        row.className = 'br-row br-row-ri';
        row.innerHTML = `<span>Réduction d'impôt Loc'Avantages <em style="font-style:normal;opacity:.65;font-size:17px">— sur ${dur} ans, hors cumul</em></span><span>${fmt(ri)}</span>`;
        bd.appendChild(row);
      })();

      // MaPrimeRénov' Copropriété — part personnelle, en supplément des aides privatives
      (function renderCoproSupplementRow(){
        document.querySelectorAll('#step-7 .breakdown .br-row-copro-supplement').forEach(el => el.remove());
        const supp = r.aides && r.aides.mprCoproSupplement;
        if (!supp || !supp.applicable || !(supp.personnelle > 0)) return;
        const bd = document.querySelector('#step-7 .breakdown');
        if (!bd) return;
        const row = document.createElement('div');
        row.className = 'br-row br-row-copro-supplement';
        row.innerHTML = `<span>MaPrimeRénov' Copropriété <em style="font-style:normal;opacity:.65;font-size:17px">— part personnelle (${supp.tantiemes}/10 000), sous réserve du vote en AG</em></span><span>${fmt(supp.personnelle)}</span>`;
        bd.appendChild(row);
      })();

      // Aides régionales Grand Est : une ligne par dispositif, pour que la somme
      // des lignes affichées réconcilie toujours le grand total.
      (function renderGrandEstRows(){
        document.querySelectorAll('#step-7 .breakdown .br-row-ge').forEach(el => el.remove());
        const ge = r.aides.grandEst;
        if (!ge || !ge.total || !Array.isArray(ge.detail) || !ge.detail.length) return;
        const after = rows[2];
        let prev = after;
        ge.detail.forEach(a => {
          if (!a || !a.montant) return;
          const row = document.createElement('div');
          row.className = 'br-row br-row-ge';
          row.innerHTML = `<span>${a.nom}</span><span>${fmt(a.montant)}</span>`;
          prev.insertAdjacentElement('afterend', row);
          prev = row;
        });
      })();

      // Masquage des dispositifs non applicables — ciblage par ATTRIBUT et non par
      // indice : le NodeList `rows` est statique, alors que les lignes .br-row-ge et
      // .br-row-copro-supplement sont supprimées/réinsérées à chaque rendu.
      (function hideInapplicableRows(){
        const bk = document.querySelector('#step-7 .breakdown');
        if (!bk) return;
        // Éco-PTZ : la clé du moteur est `eligible`. Absente sur le parcours occupant
        // → on garde la ligne visible dans ce cas.
        const ptzRow = bk.querySelector('[data-aide="ecoptz"]');
        if (ptzRow) {
          const ptzOk = !r.aides.ecoPtz || r.aides.ecoPtz.eligible !== false;
          ptzRow.style.display = ptzOk ? '' : 'none';
          // Montant r\u00e9el du plafond \u00e9co-PTZ (7 000 \u2192 50 000 \u20ac selon le nombre d'actions)
          const ptzAmt = ptzRow.querySelector('span:last-child');
          if (ptzAmt && r.aides.ecoPtz && r.aides.ecoPtz.montant > 0){
            ptzAmt.textContent = "jusqu'\u00e0 " + fmt(r.aides.ecoPtz.montant);
          }
        }
        // TVA : masquer plutôt qu'afficher « 0 € ».
        const tvaRow = bk.querySelector('[data-aide="tva"]');
        if (tvaRow) tvaRow.style.display = (r.aides.tva && r.aides.tva.total > 0) ? '' : 'none';

      })();

      rows[3].innerHTML = `<span>Économie TVA 5,5 % vs 10 % <em style="font-style:normal;opacity:.65;font-size:17px">— Service Public</em></span><span>${fmt(r.aides.tva.total)}</span>`;
      // rows[4] = éco-PTZ inchangé
    }

    // Saisie utilisateur et DPE courant — lus une seule fois : le graphique, le
    // texte narratif et la carte « Votre projet » doivent afficher LA MÊME classe.
    const userDpe    = parseDpe();
    const currentDpe = userDpe || (selectedAddr && selectedAddr.dpe) || 'E';
    const selection  = getSelectedWorks() ||
                       ['combles','ite','pac_aireau'];
    const projDpe    = projectedDpe(currentDpe, selection.length ? selection : ['combles','ite','pac_aireau']);

    // Graphique DPE — la surbrillance suit les deux classes calculées ci-dessus
    // (elle était codée en dur sur E → B dans le HTML).
    updateDpeChart(currentDpe, projDpe);

    // Texte narratif sous le graphique
    const arrow = document.querySelector('#step-7 .dpe-arrow div');
    if (arrow){
      const kwhAvant = userDpe
                        ? DPE_KWH_BY_CLASS[userDpe]
                        : ((selectedAddr && selectedAddr.dpeKwh) || Math.round(r.energie.avant / r.profile.surface));
      const kwhApres = DPE_KWH_BY_CLASS[projDpe] || Math.round(r.energie.apres / r.profile.surface);
      const sourceTag = userDpe
                          ? 'classe déclarée par vous'
                          : (selectedAddr && selectedAddr.dpe ? 'ADEME, base DPE officielle' : 'estimation (DPE non renseigné)');
      arrow.innerHTML = `De <strong>${currentDpe} (${kwhAvant} kWh/m²/an)</strong> à <strong>${projDpe} (${kwhApres} kWh/m²/an)</strong> · économie estimée <strong>${fmt(r.energie.economieAn)}/an</strong> (${sourceTag}).`;
    }

    // Carte unique « Votre projet » — même résultat que celui du bandeau total.
    // Le parcours bailleur n'a pas de note spécifique à afficher ici : la carte
    // reflète sa propre saisie, il n'y a plus de grille occupant à écarter.
    const scenSrc  = document.getElementById('scen-sources-box');
    const scenNote = document.getElementById('scen-bailleur-note');
    if (scenNote) scenNote.style.display = 'none';
    if (scenSrc)  scenSrc.style.display = '';
    try {
      renderProjetUnique(r, selection, currentDpe, projDpe);
    } catch(e){ console.warn('renderProjetUnique :', e); }
  }

  // Inject results when entering step 6 (avant l'auto-advance depuis le calcul)
  const _origGoTo2 = goTo;
  goTo = function(n){
