  /* ITE et chaudière biomasse ne sont plus finançables au titre du parcours
     « par geste » en 2026 : elles n'ouvrent des aides qu'en rénovation
     d'ampleur (≥ 2 gestes d'isolation + chauffage décarboné). Cochées seules,
     elles gonflent le coût sans générer de MPR — d'où cet avertissement. */
  const GESTES_ISOLATION = ['combles','toiture_terrasse','iti','ite','plancher_bas','sarking'];
  const GESTES_CHAUFFAGE_ENR = ['pac_aireau','pac_geothermique','poele_granules','poele_buches',
    'insert_foyer','chauffage_solaire_combine','chauffe_eau_solaire','biomasse','pvt_eau'];

  function ampleurGapDetected(){
    const sel = getSelectedWorks();
    const hasHorsGeste = sel.includes('ite') || sel.includes('biomasse');
    if (!hasHorsGeste) return false;
    const nbIsolation = GESTES_ISOLATION.filter(g => sel.includes(g)).length;
    const hasEnR      = GESTES_CHAUFFAGE_ENR.some(g => sel.includes(g));
    // Rénovation d'ampleur atteinte → ces gestes sont finançables, pas d'alerte
    return !(nbIsolation >= 2 && hasEnR);
  }

  function updateAmpleurWarning(){
    let box = document.getElementById('step-5-ampleur-warn');
    if (!ampleurGapDetected()){ if (box) box.style.display = 'none'; return; }
    if (!box){
      const anchor = document.getElementById('step-5-warn');
      if (!anchor || !anchor.parentElement) return;
      box = document.createElement('div');
      box.id = 'step-5-ampleur-warn';
      box.style.cssText = 'margin:14px 0;padding:13px 15px;background:#E9E3D3;border-left:0;border-radius:6px;font-size:17px;color:#123A2E;line-height:1.55';
      box.innerHTML = "<strong>Attention : ces travaux ne sont pas finançables seuls en 2026.</strong> "
        + "L'isolation des murs par l'extérieur et les chaudières biomasse ont été retirées du parcours "
        + "MaPrimeRénov' « par geste ». Elles n'ouvrent des aides qu'en <strong>rénovation d'ampleur</strong>, "
        + "qui suppose au moins <strong>deux gestes d'isolation</strong> (par exemple murs + combles) "
        + "<strong>et</strong> un changement de chauffage décarboné (pompe à chaleur, poêle à granulés, solaire). "
        + "En l'état, leur coût sera compté sans aide MaPrimeRénov' correspondante.";
      anchor.parentElement.insertBefore(box, anchor);
    }
    box.style.display = 'block';
  }
  updateAmpleurWarning();
  function getSelectedWorks(){
    return [...document.querySelectorAll('#step-5 [data-work].selected')].map(t => t.dataset.work);
  }

  /* Estimation dynamique sous chaque tuile travaux — utilise la surface
     déjà saisie à l'étape 2. Les forfaits (PAC, biomasse, VMC, menuiseries)
     sont indépendants de la surface, donc affichage neutre. */
  // (function updateStep5Estimates retirée — plus de chiffrage à l'étape 5)

  /* Conseil contextuel adaptatif : lit les données saisies aux étapes 1-4
     et propose le bouquet de travaux le plus pertinent.
     Pas de pré-sélection, juste une recommandation lisible. */
  function updateStep5Tip(){
    try {
      // Récupération des données saisies — DOM ou localStorage en fallback
      const heat = parseHeat(); // 'gaz' / 'fioul' / 'electrique' / 'bois'
      const year = parseInt(document.getElementById('year')?.value, 10) || 1972;
      const typeTile = document.querySelector('[data-radio="type"].selected .nm');
      const typeStr  = (typeTile?.textContent || '').toLowerCase();
      const isMaison = typeStr.includes('maison');
      const isAppart = typeStr.includes('appart');
      const prioTile = document.querySelector('[data-radio="prio"].selected .nm');
      const prio = (prioTile?.textContent || '').toLowerCase();
      const statTile = document.querySelector('[data-radio="status"].selected .nm');
      const stat = (statTile?.textContent || '').toLowerCase();
      const rfr = parseRFR();
      const foyer = parseFoyer();
      const region = parseRegion();
      const cat = categorie(rfr, foyer, region);

      // Sélection du conseil — ordre de priorité du plus spécifique au plus général
      let tip = '';
      if (cat === 'roses'){
        tip = '<b>Ressources supérieures :</b> vous n\'êtes pas éligible à MaPrimeRénov\' par geste en 2026. Seule la rénovation d\'ampleur (≥ 2 gestes d\'isolation + saut 2 classes DPE) vous ouvre une aide MPR à 10&nbsp;%, en plus des CEE et de la TVA 5,5&nbsp;%.';
      } else if (stat.startsWith('bailleur')){
        tip = '<b>Bailleur :</b> la loi Climat &amp; Résilience interdit à la location les logements <strong>G (depuis 2025)</strong>, <strong>F (2028)</strong> et <strong>E (2034)</strong>. Viser au minimum <strong>DPE E</strong> avant 2028, D ou mieux pour l\'horizon 2034.';
      } else if (isAppart){
        tip = '<b>Appartement :</b> les combles relèvent généralement de la copropriété. Concentrez-vous sur les menuiseries et le chauffage individuel. VMC double flux possible.';
      } else if (heat === 'fioul'){
        tip = '<b>Chauffage au fioul :</b> la pompe à chaleur air/eau est votre meilleur levier — elle vous libère du fioul (interdit en neuf depuis 2022) et déclenche les aides les plus généreuses. Combinez avec les combles pour amplifier.';
      } else if (heat === 'gaz' && year < 1980){
        tip = '<b>Maison ancienne au gaz :</b> commencez par l\'isolation des combles (rentabilité rapide), puis les murs (ITE) avant d\'envisager un changement de chauffage.';
      } else if (heat === 'electrique'){
        tip = '<b>Chauffage électrique :</b> l\'isolation (combles + murs) vous fera plus économiser que de changer de système. Une PAC peut compléter pour les très grandes surfaces.';
      } else if (heat === 'bois'){
        tip = '<b>Chauffage au bois :</b> énergie déjà renouvelable, concentrez-vous sur l\'isolation (combles + murs) pour amplifier les économies sans changer le système.';
      } else if (isMaison && year < 1980){
        tip = '<b>Maison construite avant 1980 :</b> gros défauts d\'isolation typiques de l\'époque. Priorisez combles + murs (ITE) avant tout autre poste.';
      } else if (isMaison && year < 2000){
        tip = '<b>Maison avant RT2000 :</b> l\'isolation extérieure (ITE) reste l\'investissement le plus rentable, suivi du remplacement du chauffage.';
      } else if (prio.startsWith('économ')){
        tip = '<b>Objectif économies :</b> combles d\'abord (rapide à amortir), puis remplacement du chauffage (gros impact facture).';
      } else if (prio.startsWith('confort')){
        tip = '<b>Objectif confort :</b> isolation des murs (ITE) + VMC double flux pour un air sain et des températures stables toute l\'année.';
      } else if (prio.startsWith('écolo')){
        tip = '<b>Objectif écologie :</b> visez le bouquet complet — combles + ITE + PAC ou biomasse — pour une rénovation d\'ampleur et un DPE A/B.';
      } else if (prio.startsWith('mise en conformité') || prio.startsWith('conformité')){
        tip = "<b>Objectif conformité :</b> ciblez au minimum le <strong>DPE E</strong> (combo combles + ITE + PAC) pour rester louable après 2028, D ou mieux pour l'horizon 2034.";
      } else if (cat === 'bleus' || cat === 'jaunes'){
        tip = '<b>Vos aides sont parmi les plus généreuses :</b> profitez-en pour un bouquet ambitieux (combles + ITE + chauffage). MaPrimeRénov\' couvre une part importante.';
      } else if (cat === 'roses'){
        tip = '<b>Vos aides MaPrimeRénov\' sont limitées</b> — ciblez les postes qui maximisent les CEE (PAC, biomasse) et la TVA réduite. L\'isolation reste rentable hors aides.';
      } else {
        tip = '<b>Conseil général :</b> commencez par l\'isolation des combles, c\'est l\'investissement avec le meilleur retour. Puis envisagez le chauffage si actuellement fioul/gaz ancien.';
      }

      const tipBox = document.getElementById('step5-tip');
      const tipTxt = document.getElementById('step5-tip-text');
      if (tipBox && tipTxt && tip){
        tipTxt.innerHTML = tip;
        tipBox.style.display = 'flex';
      }
    } catch(e){ console.warn('updateStep5Tip :', e); }
  }

  // Recalcul à chaque changement de surface à l'étape 2
