  /* ─── Lead magnet : capture email + PDF récap (étape 7) ─── */
  function updateLeadMagnetAmount(totalAides){
    const block = document.getElementById('lead-magnet');
    const el    = document.getElementById('lead-magnet-amount');
    if (!el || !block) return;
    const val = Number(totalAides) || 0;
    if (val <= 0) { block.style.display = 'none'; return; }
    el.textContent = Math.round(val).toLocaleString('fr-FR') + ' €';
    block.style.display = 'block';
  }
  function isValidEmail(email){
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email || '');
  }
  (function initLeadMagnet(){
    const btn      = document.getElementById('lead-magnet-submit');
    const emailIn  = document.getElementById('lead-magnet-email');
    const consent  = document.getElementById('lead-magnet-consent');
    const errorBox = document.getElementById('lead-magnet-error');
    const formBox  = document.getElementById('lead-magnet-form');
    const okBox    = document.getElementById('lead-magnet-success');
    if (!btn || !emailIn || !consent) return;

    btn.addEventListener('click', () => {
      const email = emailIn.value.trim();
      errorBox.style.display = 'none';

      if (!isValidEmail(email)) {
        errorBox.textContent = 'Adresse email invalide — vérifiez la syntaxe (exemple : nom@domaine.fr).';
        errorBox.style.display = 'block';
        emailIn.focus();
        return;
      }
      if (!consent.checked) {
        errorBox.textContent = 'Merci de cocher la case de consentement pour recevoir votre PDF.';
        errorBox.style.display = 'block';
        return;
      }

      const result = window.__rfCurrentResult;
      if (!result) {
        errorBox.textContent = 'Impossible de générer votre récap. Rechargez la page et recommencez.';
        errorBox.style.display = 'block';
        return;
      }

      try {
        const leads = JSON.parse(localStorage.getItem('junglerenov.leads') || '[]');
        leads.push({
          email, capturedAt: new Date().toISOString(), source: 'diagnostic-etape-7',
          totalAides: result.totalAides, profile: result.profile,
          consent: true, consentAt: new Date().toISOString(),
        });
        localStorage.setItem('junglerenov.leads', JSON.stringify(leads));
      } catch(e) { console.warn('Lead storage failed :', e); }

      if (window.RFDocs && typeof window.RFDocs.generateRecapPdf === 'function') {
        window.RFDocs.generateRecapPdf(result, email);
      } else {
        console.warn('RFDocs.generateRecapPdf indisponible — vérifier _pdf_docs.js');
        errorBox.textContent = 'Générateur PDF indisponible. Vérifiez votre connexion et rechargez la page.';
        errorBox.style.display = 'block';
        return;
      }

      formBox.style.display = 'none';
      okBox.style.display   = 'block';
    });
  })();

  updateRecapTransmission();

  /* ===== Pré-remplissage depuis localStorage si une simulation existe déjà ===== */
  (function prefillFromProfile(){
    try {
      const p = JSON.parse(localStorage.getItem('junglerenov.profile') || '{}');
      // Adresse
      if (p.address){
        const a = document.getElementById('addr');
        if (a) a.value = p.address;
      }
      // Logement (étape 2)
      if (p.logement){
        const surf = document.getElementById('surf');
        if (surf && p.logement.surface){
          surf.value = p.logement.surface;
          const sv = document.getElementById('surf-num');
          if (sv) sv.value = p.logement.surface;
        }
        const year = document.getElementById('year');
        if (year && p.logement.year) year.value = p.logement.year;
        // Type maison/appartement
        if (p.logement.type){
          document.querySelectorAll('[data-radio="type"]').forEach(t => {
            const nm = (t.querySelector('.nm')?.textContent || '').toLowerCase();
            const want = p.logement.type.toLowerCase();
            t.classList.toggle('selected', want.startsWith(nm.slice(0,7)) || nm.startsWith(want.slice(0,7)));
          });
        }
        // Chauffage
        if (p.logement.heat){
          document.querySelectorAll('[data-radio="heat"]').forEach(t => {
            const nm = (t.querySelector('.nm')?.textContent || '').toLowerCase();
            let match = false;
            if (p.logement.heat === 'gaz' && nm.startsWith('gaz')) match = true;
            if (p.logement.heat === 'fioul' && nm.startsWith('fioul')) match = true;
            if (p.logement.heat === 'electrique' && (nm.startsWith('élect') || nm.startsWith('elec'))) match = true;
            if (p.logement.heat === 'bois' && nm.startsWith('bois')) match = true;
            t.classList.toggle('selected', match);
          });
        }
        // Classe DPE
        if (typeof p.logement.dpe !== 'undefined'){
          const want = (p.logement.dpe || '').toUpperCase();
          document.querySelectorAll('[data-radio="dpe"]').forEach(t => {
            t.classList.toggle('selected', (t.dataset.dpe || '').toUpperCase() === want);
          });
        }
        // Département / EPCI / appareil bois ancien (Grand Est)
        if (p.logement.dept){
          const d = document.getElementById('dept');
          if (d){ d.value = p.logement.dept; refreshEpci(); }
        }
        if (p.logement.epci){
          const e = document.getElementById('epci');
          if (e) e.value = p.logement.epci;
        }
        if (typeof p.logement.oldWoodStove !== 'undefined'){
          const want = p.logement.oldWoodStove ? 'yes' : 'no';
          document.querySelectorAll('[data-radio="oldwood"]').forEach(t => {
            t.classList.toggle('selected', t.dataset.oldwood === want);
          });
        }
      }
      // Situation (étape 3)
      if (p.situation){
        // Le sélecteur PO/PB de l'étape 3 (junglerenov.ownerType) est propriétaire de ce choix.
        // p.situation.status ne sert que de repli pour les sessions antérieures au branchement.
        let ownerTypeStored = null;
        try { ownerTypeStored = localStorage.getItem('junglerenov.ownerType'); } catch(_){}
        const wantStatus = ownerTypeStored
          ? (ownerTypeStored === 'bailleur' ? 'Bailleur' : 'Occupant')
          : p.situation.status;
        if (wantStatus){
          document.querySelectorAll('[data-radio="status"]').forEach(t => {
            const nm = (t.querySelector('.nm')?.textContent || '');
            t.classList.toggle('selected', nm === wantStatus);
          });
        }
        if (p.situation.budget){
          document.querySelectorAll('[data-radio="budget"]').forEach(t => {
            const nm = (t.querySelector('.nm')?.textContent || '');
            t.classList.toggle('selected', nm === p.situation.budget);
          });
        }
        if (p.situation.priorite){
          document.querySelectorAll('[data-radio="prio"]').forEach(t => {
            const nm = (t.querySelector('.nm')?.textContent || '');
            t.classList.toggle('selected', nm === p.situation.priorite);
          });
        }
      }
      // Foyer (étape 4)
      if (p.foyer){
        if (p.foyer.rfr){
          const rfr = document.getElementById('rfr');
          if (rfr) rfr.value = p.foyer.rfr.toLocaleString('fr-FR') + ' €';
        }
        if (p.foyer.parts){
          const parts = document.getElementById('parts');
          if (parts) parts.selectedIndex = Math.max(0, Math.min(5, p.foyer.parts - 1));
        }
        if (p.foyer.region){
          const reg = document.getElementById('region-select');
          if (reg) reg.value = p.foyer.region;
        }
      }
      // Travaux sélectionnés (étape 5)
      if (Array.isArray(p.travaux) && p.travaux.length){
        document.querySelectorAll('#step-5 [data-work]').forEach(tile => {
          tile.classList.toggle('selected', p.travaux.includes(tile.dataset.work));
        });
      }
      // Bannière "Reprise de diagnostic"
      if (p.address || p.logement || p.foyer){
        const wrap = document.querySelector('#step-1 .card');
        if (wrap){
          const banner = document.createElement('div');
          banner.className = 'prefill';
          banner.style.background = 'var(--teal-50)';
          banner.style.borderColor = 'var(--teal-100)';
          banner.style.color = 'var(--teal-900)';
          banner.style.marginBottom = '16px';
          banner.innerHTML = '<span class="ico"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="m5 12 5 5L20 7"/></svg></span><div>Reprise de votre dernier diagnostic — vos informations ont été pré-remplies. <a href="#" id="reset-diag" style="color:var(--teal-700);text-decoration:underline;font-weight:600">Repartir de zéro</a></div>';
          wrap.insertBefore(banner, wrap.firstChild);
          document.getElementById('reset-diag').addEventListener('click', e => {
            e.preventDefault();
            if (confirm('Effacer la simulation en cours et recommencer ?')){
              try {
                const cur = JSON.parse(localStorage.getItem('junglerenov.profile') || '{}');
                delete cur.address; delete cur.logement; delete cur.situation; delete cur.foyer; delete cur.travaux; delete cur.aids; delete cur.diagnostiqueLe;
                localStorage.setItem('junglerenov.profile', JSON.stringify(cur));
              } catch{}
              location.reload();
            }
          });
        }
      }
    } catch(e){ console.warn('Préremplissage :', e); }
    // La tuile "type de logement" vient d'être restaurée par programme (pas de clic),
    // on signale le changement pour que le bloc copro-collectifs se réévalue.
    document.dispatchEvent(new CustomEvent('rf:type-logement-change'));
  })();

  // Restaure l'étape en cours après un rechargement
  try {
    const savedStep = Number(localStorage.getItem('junglerenov.currentStep'));
    if (savedStep >= 1 && savedStep <= 8) cur = savedStep;
  } catch(_){}
  /* CTA étape 7 — injecte le montant et navigue vers l'étape 8 */
  function updateCtaScenAmount(){
    const wrap = document.getElementById('rf-cta-scen');
    const el   = document.getElementById('rf-cta-scen-amount');
    if (!wrap || !el) return;
    const fmtEur = n => Math.round(n).toLocaleString('fr-FR') + ' €';
    try {
      // Le résultat de l'étape 7 vient d'être calculé par injectResults() ;
      // à défaut on recalcule depuis le DOM plutôt que depuis un profil périmé.
      let total = Number(window.__rfCurrentResult && window.__rfCurrentResult.totalAides) || 0;
      if (!total){
        try { const fresh = computeAids(); total = Number(fresh && fresh.totalAides) || 0; }
        catch(eC){ total = 0; }
      }
      if (total <= 0){ wrap.style.display = 'none'; return; }
      wrap.style.display = '';
      el.textContent = fmtEur(total);
    } catch(e){
      console.warn('CTA étape 7 :', e);
      wrap.style.display = 'none';
    }
  }
  document.addEventListener('click', function(e){
    const btn = e.target.closest('#rf-cta-scen-btn');
    if (!btn) return;
    e.preventDefault();
    goTo(8);
  });

  /* Hero ROI étape 8 — calcule et injecte le comparatif */
  function updateHeroRoiStep8(){
    const wrap    = document.getElementById('rf-hero-roi');
    const gainsEl = document.getElementById('rf-hero-gains');
    if (!wrap || !gainsEl) return;
    // Formateur local : `fmt` est déclaré en portée locale ailleurs.
    const fmtEur = n => Math.round(n).toLocaleString('fr-FR') + ' €';
    try {
      // Recalcul frais DEPUIS LE DOM : recomputeFromProfile() lit profile.travaux
      // dans localStorage, qui n'est réécrit qu'à l'étape 7. Si l'utilisateur
      // arrive ici par le fil d'Ariane sans repasser par 7, ce champ est périmé.
      let total = 0;
      try {
        const fresh = computeAids();
        if (fresh && fresh.totalAides > 0){ window.__rfCurrentResult = fresh; total = Number(fresh.totalAides); }
      } catch(eC){ console.warn('Recalcul étape 8 :', eC); }
      if (!total) total = Number(window.__rfCurrentResult && window.__rfCurrentResult.totalAides) || 0;
      if (total <= 0){ wrap.style.display = 'none'; return; }
      wrap.style.display = '';
      gainsEl.textContent = fmtEur(total);
      // Traçabilité : décomposition du total, aide par aide.
      const subEl2 = document.getElementById('rf-hero-sub');
      const cur    = window.__rfCurrentResult;
      if (subEl2 && cur && cur.aides){
        const A = cur.aides, parts = [];
        if (A.mpr && A.mpr.total)           parts.push("MaPrimeRénov' " + fmtEur(A.mpr.total));
        // CEE : une fourchette, jamais un montant — il dépend de l'organisme.
        if (A.cee && A.cee.total)           parts.push('CEE ' + ((A.cee.unique === false && A.cee.max > A.cee.min)
                                              ? fmtEur(A.cee.min) + ' à ' + fmtEur(A.cee.max) : fmtEur(A.cee.total)));
        if (A.local && A.local.total)       parts.push('aide locale ' + fmtEur(A.local.total));
        if (A.grandEst && A.grandEst.total) parts.push('Grand Est ' + fmtEur(A.grandEst.total));
        const base = (cur.travaux && cur.travaux.totalTTC)
          ? 'Sur ' + fmtEur(cur.travaux.totalTTC) + ' TTC de travaux sélectionnés' : '';
        subEl2.textContent = [base, parts.join(' · ')].filter(Boolean).join(' — ');
      }
      if (window.RFAlertes && cur) RFAlertes.rendreReferentiel(cur, 'rf-referentiel-final');

    } catch(e){
      console.warn('hero ROI étape 8 :', e);
      wrap.style.display = 'none';
    }
  }

  // A.18 — cache le warning étape 4 dès que l'utilisateur corrige
  ['#rfr','#rf-rent-amount','#rf-surface-hab','#rf-copro-lots','#rf-copro-tantiemes'].forEach(sel => {
    document.querySelector(sel)?.addEventListener('input', () => {
      const w = document.getElementById('step-4-warn');
      if (w) w.style.display = 'none';
    });
  });

  render();

