/* Récapitulatif de transmission : rafraîchi à chaque arrivée sur l'étape 8,
   pour refléter la dernière estimation et le bon professionnel. */
(function(){
  'use strict';
  function refresh(){
    {
      try { updateRecapTransmission(); } catch (e) { console.warn('Récap transmission :', e); }
    }
  }
  document.addEventListener('rf:step', function(e){ if (e && e.detail === 8) refresh(); });
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', refresh);
  else refresh();
})();

