/* Redémarrage propre du tunnel : ?fresh=1 purge le brouillon en cours.
   Cas MaPrimeAdapt' : dernière estimation locale et brouillon en attente de transmission.
   En développement local seulement, les dossiers sont purgés aussi, pour repartir
   d'un tableau de bord vide. Partout ailleurs, junglerenov.dossiers survit toujours —
   de même que le compte et la session, dans tous les cas. */
(function resetIfFresh(){
  try {
    var params = new URLSearchParams(location.search);
    if (params.get('fresh') !== '1') return;
    localStorage.removeItem('junglerenov.autonomie.result');
    localStorage.removeItem('junglerenov.dossierEnAttente');
    localStorage.removeItem('junglerenov.returnTo');
    /* (purge des données de test retirée) */
    history.replaceState(null, '', location.pathname);
  } catch (_) {}
})();

pages/parcours-autonomie/02.js:
(function(){
  var C = window.RFCompute;
  var state = { who:null, age:null, gir:null, girChoice:null, handicap:null, travaux:[], logement:{} };
  var STORE = 'junglerenov.autonomie';

  try {
    var saved = JSON.parse(localStorage.getItem(STORE) || 'null');
    if (saved && typeof saved === 'object') state = Object.assign(state, saved);
  } catch(e){}

  function persist(){
    var payload = Object.assign({}, state, {
      foyer: val('foyer'), rfr: val('rfr'),
      region: (document.getElementById('region')||{}).value || 'Grand Est',
    });
    try { localStorage.setItem(STORE, JSON.stringify(payload)); } catch(e){}
  }
  function el(id){ return document.getElementById(id); }
  function val(id){ var e = el(id); return e ? e.value : ''; }
  function esc(s){
    return String(s == null ? '' : s).replace(/[&<>"]/g, function(c){
      return ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;' })[c];
    });
  }
  function fmt(n){ return Math.round(n||0).toLocaleString('fr-FR') + ' €'; }

  /* ── Navigation ─────────────────────────────────────────────── */
  var current = 1;
  var maxReached = 1;

  /* Fil d'Ariane : états visuels + accessibilité des pastilles. */
  function refreshStepperStates(){
    document.querySelectorAll('.pip[data-goto]').forEach(function(p){
      var t = Number(p.dataset.goto);
      p.classList.remove('done', 'active', 'pending');
      // Une étape déjà atteinte reste « done » (donc cliquable) même si on est
      // revenu en arrière : elle ne doit pas repasser en grisé.
      if (t === current)        p.classList.add('active');
      else if (t <= maxReached) p.classList.add('done');
      else                      p.classList.add('pending');
      var clickable = t !== current && t <= maxReached && !p.hasAttribute('data-non-cliquable');
      if (clickable){
        p.setAttribute('role', 'button');
        p.setAttribute('tabindex', '0');
        var lbl = p.querySelector('span:last-child');
        p.setAttribute('aria-label', "Retourner à l'étape " + (lbl ? lbl.textContent : t));
      } else {
        p.removeAttribute('role');
        p.removeAttribute('tabindex');
        p.removeAttribute('aria-label');
      }
      p.setAttribute('aria-current', t === current ? 'step' : 'false');
    });
  }

  function bindStepperClicks(){
    document.querySelectorAll('.pip[data-goto]').forEach(function(p){
      function jump(){
        var t = Number(p.dataset.goto);
        // Navigation libre entre les étapes DÉJÀ atteintes, dans les deux sens :
        // reculer pour corriger, puis revenir en avant sans tout re-valider.
        // Une étape non encore atteinte reste inaccessible.
        if (t === current || t > maxReached) return;
        // L'écran de calcul est une transition, pas une étape sur laquelle revenir
        if (p.hasAttribute('data-non-cliquable')) return;
        goTo(t);
      }
      p.addEventListener('click', jump);
      p.addEventListener('keydown', function(e){
        if (e.key === 'Enter' || e.key === ' '){ e.preventDefault(); jump(); }
      });
    });
  }

  function goTo(n){
    current = n;
    document.querySelectorAll('.screen').forEach(function(s){ s.classList.remove('active'); });
    var screenEl = el('s' + n);
    if (screenEl) screenEl.classList.add('active');
    // Étape la plus avancée atteinte : borne le retour arrière ET empêche
    // de sauter en avant, même en trafiquant les attributs du stepper.
    if (n > maxReached) maxReached = n;
    refreshStepperStates();
    // L'étape Transmission est recalculée à CHAQUE affichage : on peut y arriver
    // par le fil d'Ariane après avoir modifié une réponse en arrière.
    if (n === 8){
      /* Une opération, un try : l'échec du teaser ne doit jamais empêcher le
         récapitulatif de se remplir (sinon adresse, montant et brouillon restent vides). */
      try { renderTeaser(computeAndStore()); } catch(e){ console.error('Teaser :', e); }
      try { if (window.rfUpdateRecapTransmission) window.rfUpdateRecapTransmission(); }
      catch(e){ console.error('Récapitulatif de transmission :', e); }
    }
    if (n === 7) startCalcAnimation(); else stopCalcAnimation();
    window.scrollTo({ top:0, behavior:'smooth' });
    refresh();
  }
  document.querySelectorAll('[data-next]').forEach(function(b){
    b.addEventListener('click', function(){ persist(); goTo(Number(b.dataset.next)); });
  });
  document.querySelectorAll('[data-prev]').forEach(function(b){
    b.addEventListener('click', function(){ goTo(Number(b.dataset.prev)); });
  });

  /* ── Groupes de tuiles à choix unique ───────────────────────── */
  function singleSelect(containerId, key, onPick){
    var box = document.getElementById(containerId);
    if (!box) return;
    box.querySelectorAll('.tile').forEach(function(t){
      if (state[key] === t.dataset.val) t.classList.add('selected');
      t.addEventListener('click', function(){
        box.querySelectorAll('.tile').forEach(function(x){ x.classList.remove('selected'); });
        t.classList.add('selected');
        state[key] = t.dataset.val;
        if (onPick) onPick(t.dataset.val);
        persist(); refresh();
      });
    });
  }
  singleSelect('who', 'who');
  singleSelect('handicap', 'handicap');
  singleSelect('gir-choice', 'girChoice', function(v){
    var f = document.getElementById('gir-select-field');
    var sel = document.getElementById('gir');
    if (f) f.hidden = (v !== 'oui');
    // Le DOM et l'état doivent rester alignés : sans remise à zéro du select,
    // un retour sur « Oui » réafficherait un niveau alors que state.gir est nul,
    // et re-choisir la valeur déjà affichée n'émet aucun `change`.
    if (v === 'oui') {
      state.gir = (sel && sel.value) || null;
    } else {
      state.gir = null;
      if (sel) sel.value = '';
    }
  });

  /* ── Âge & GIR ──────────────────────────────────────────────── */
  var ageIn = document.getElementById('age');
  if (state.age) ageIn.value = state.age;
  var girSel = document.getElementById('gir');
  if (state.gir) girSel.value = state.gir;
  girSel.addEventListener('change', function(){ state.gir = girSel.value || null; persist(); refresh(); });

  /* Visibilité du bloc GIR et de la note contextuelle, dérivée de l'âge.
     Fonction nommée pour être rejouée à la restauration de session : sinon un
     utilisateur de 60-69 ans qui revient dans son tunnel ne voit plus la
     question GIR, alors que sa réponse est bien mémorisée. */
  function updateAgeConditionals(){
    var a = Number(ageIn.value) || 0;
    state.age = a || null;
    var girBlock = document.getElementById('gir-block');
    var note = document.getElementById('age-note');
    if (girBlock) girBlock.hidden = !(a >= 60 && a < 70);
    // Le niveau GIR n'est demandé qu'après une réponse « Oui »
    var girField = document.getElementById('gir-select-field');
    if (girField) girField.hidden = !(a >= 60 && a < 70 && state.girChoice === 'oui');
    if (!note) return;
    if (a >= 70){
      note.hidden = false;
      note.textContent = "À partir de 70 ans, l'éligibilité MaPrimeAdapt' est acquise sans condition d'autonomie — seuls les revenus sont examinés.";
    } else if (a >= 60 && a < 70){
      note.hidden = true;
    } else if (a > 0){
      note.hidden = false;
      note.textContent = "Avant 60 ans, MaPrimeAdapt' est accessible uniquement en situation de handicap (taux ≥ 50 % ou PCH) — question suivante.";
    } else {
      note.hidden = true;
    }
  }

  ageIn.addEventListener('input', function(){
    updateAgeConditionals();
    persist(); refresh();
  });

  // Rejoue la dérivation sur l'état restauré
  updateAgeConditionals();

  /* ── Étape 1 : Logement (adresse BAN, type, surface, année) ─── */
  state.logement = state.logement || {};

  /* Région déduite du département : sert à choisir le bon barème de plafonds
     (Île-de-France vs hors Île-de-France) à l'étape Revenus. */
  var DEPTS_IDF = ['75','77','78','91','92','93','94','95'];
  var DEPTS_GRAND_EST = ['08','10','51','52','54','55','57','67','68','88'];
  function regionFromDept(dept){
    if (DEPTS_IDF.indexOf(dept) !== -1) return 'Île-de-France';
    if (DEPTS_GRAND_EST.indexOf(dept) !== -1) return 'Grand Est';
    return 'Autre';
  }

  var adAdresse = el('ad-adresse');
  var adSugg    = el('ad-adresse-suggestions');
  var adSurface = el('ad-surface');
  var adAnnee   = el('ad-annee');

  function closeSugg(){ if (adSugg){ adSugg.hidden = true; adSugg.innerHTML = ''; } }

  /* Secours : BAN injoignable ou adresse inconnue → saisie manuelle, code postal exigé. */
  var adSecours = window.RFAdresseSecours ? RFAdresseSecours.attach(adAdresse, {
    regionFromDept: regionFromDept,
    onValide: function(data){
      if (data){
        state.logement.adresse = data.adresse; state.logement.codePostal = data.codePostal;
        state.logement.ville = data.ville; state.logement.dept = data.dept;
        state.logement.region = data.region; state.logement.saisieManuelle = true;
      } else state.logement.adresse = null;
      persist(); refresh();
    },
  }) : { ouvrir: function(){} };

  if (adAdresse && adSugg){
    var banTimer = null;
    adAdresse.addEventListener('input', function(){
      clearTimeout(banTimer);
      // La saisie libre invalide l'adresse retenue : il faut choisir une
      // suggestion pour que l'étape soit valide.
      state.logement.adresse = null;
      persist(); refresh();
      var q = adAdresse.value.trim();
      if (q.length < 5){ closeSugg(); return; }
      banTimer = setTimeout(function(){
        fetch('https://api-adresse.data.gouv.fr/search/?q=' + encodeURIComponent(q) + '&limit=5')
          .then(function(r){ if (!r.ok) throw new Error(r.status); return r.json(); })
          .then(function(j){
            var feats = (j && j.features) || [];
            if (!feats.length){ closeSugg(); adSecours.ouvrir("Cette adresse n'est pas dans la base. Saisissez-la ci-dessous."); return; }
            adSugg.innerHTML = feats.map(function(f, i){
              var p = f.properties || {};
              return '<button type="button" class="ban-item" data-i="' + i + '">' +
                '<span class="lbl">' + esc(p.label || '') + '</span>' +
                '<span class="ctx">' + esc(p.context || '') + '</span></button>';
            }).join('');
            adSugg.hidden = false;
            adSugg.querySelectorAll('.ban-item').forEach(function(btn){
              btn.addEventListener('click', function(){
                var p = (feats[Number(btn.dataset.i)] || {}).properties || {};
                var cp = String(p.postcode || '');
                state.logement.adresse    = p.label || '';
                state.logement.codePostal = cp;
                state.logement.ville      = p.city || '';
                state.logement.dept       = cp.slice(0, 2);
                state.logement.codeInsee  = p.citycode || '';
                state.logement.contexte   = p.context || '';
                state.logement.region     = regionFromDept(state.logement.dept);
                adAdresse.value = state.logement.adresse;
                closeSugg();
                // La région déduite pré-sélectionne le barème de l'étape Revenus
                var regSel = el('region');
                if (regSel && state.logement.region) regSel.value = state.logement.region;
                persist(); refresh();
              });
            });
          })
          .catch(function(e){ console.warn('[JungleRenov] BAN :', e); closeSugg(); adSecours.ouvrir("Le service d'adresses ne répond pas. Saisissez votre adresse ci-dessous."); });
      }, 250);
    });
    adAdresse.addEventListener('blur', function(){ setTimeout(closeSugg, 150); });
  }

  singleSelectInto('ad-type', 'type');
  /* Variante de singleSelect qui écrit dans state.logement plutôt qu'à la racine. */
  function singleSelectInto(containerId, key){
    var box = el(containerId);
    if (!box) return;
    box.querySelectorAll('.tile').forEach(function(t){
      if (state.logement[key] === t.dataset.val) t.classList.add('selected');
      t.addEventListener('click', function(){
        box.querySelectorAll('.tile').forEach(function(x){ x.classList.remove('selected'); });
        t.classList.add('selected');
        state.logement[key] = t.dataset.val;
        persist(); refresh();
      });
    });
  }

  [[adSurface, 'surface'], [adAnnee, 'annee']].forEach(function(pair){
    var input = pair[0], key = pair[1];
    if (!input) return;
    input.addEventListener('input', function(){
      var v = parseInt(input.value, 10);
      state.logement[key] = v > 0 ? v : null;
      persist(); refresh();
    });
  });
  if (adAnnee) adAnnee.max = String(new Date().getFullYear());

  // Restaure la saisie d'une visite précédente
  if (state.logement.adresse && adAdresse) adAdresse.value = state.logement.adresse;
  if (state.logement.surface && adSurface) adSurface.value = state.logement.surface;
  if (state.logement.annee && adAnnee)     adAnnee.value = state.logement.annee;

  /* ── Travaux ────────────────────────────────────────────────── */
  var GROUPES = [
    { titre:'Salle de bain',        cle:'salle_de_bain' },
    { titre:'Accessibilité',        cle:'accessibilite' },
    { titre:'Autres aménagements',  cle:'autres_amenagements' },
  ];
  function buildWorks(){
    var host = document.getElementById('works');
    if (!host || !C) return;
    host.innerHTML = GROUPES.map(function(g){
      var codes = (C.MPA.travauxEligibles[g.cle] || []);
      return '<div><h3>' + g.titre + '</h3><div class="tiles">' + codes.map(function(code){
        var on = state.travaux.indexOf(code) !== -1;
        return '<button type="button" class="tile' + (on ? ' selected' : '') + '" data-work="' + code + '">' +
          '<span class="box"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><path d="m5 12 5 5L20 7"/></svg></span>' +
          '<span class="nm">' + (C.MPA_LIBELLES[code] || code) + '</span>' +
          '<span class="cost">' + fmt(C.MPA_COUTS_INDICATIFS[code]) + '</span>' +
        '</button>';
      }).join('') + '</div></div>';
    }).join('');
    host.querySelectorAll('[data-work]').forEach(function(b){
      b.addEventListener('click', function(){
        var code = b.dataset.work, i = state.travaux.indexOf(code);
        if (i === -1) state.travaux.push(code); else state.travaux.splice(i, 1);
        b.classList.toggle('selected', i === -1);
        persist(); refresh();
      });
    });
  }
  buildWorks();

  /* ── Validation par étape ───────────────────────────────────── */
  function stepValid(n){
    // Étape 1 — Logement : adresse choisie dans la BAN + type + surface + année
    if (n === 1){
      var L = state.logement || {};
      return !!(L.adresse && L.type && Number(L.surface) >= 9
                && Number(L.annee) >= 1800 && Number(L.annee) <= new Date().getFullYear());
    }
    if (n === 2) return !!state.who;
    if (n === 3) {
      var a = Number(state.age) || 0;
      if (!a) return false;
      // 60-69 ans : « Oui » exige le niveau GIR, sinon le moteur conclurait
      // à tort à une non-éligibilité contredisant la réponse de l'utilisateur.
      if (a >= 60 && a < 70) return state.girChoice === 'oui' ? !!state.gir : !!state.girChoice;
      return true;
    }
    if (n === 4) return !!state.handicap;
    if (n === 5) return Number(val('rfr')) > 0 && Number(val('foyer')) > 0;
    if (n === 6) return state.travaux.length > 0;
    return true;
  }
  function stepMissing(n){
    if (stepValid(n)) return '';
    if (n === 1){
      var L = state.logement || {};
      if (!L.adresse) return "Choisissez votre adresse dans la liste, ou utilisez « Mon adresse n'apparaît pas ».";
      if (!L.type) return 'Indiquez le type de logement.';
      if (!(Number(L.surface) >= 9)) return 'Indiquez la surface habitable (9 m² au moins).';
      return "Indiquez l'année de construction — une approximation suffit.";
    }
    if (n === 2) return 'Indiquez pour qui sont les travaux.';
    if (n === 3) return (Number(state.age) || 0) ? 'Précisez votre niveau de perte d\u2019autonomie (GIR), ou répondez « non ».' : "Indiquez l'âge de la personne concernée.";
    if (n === 4) return 'Répondez à la question sur le handicap.';
    if (n === 5) return "Indiquez votre revenu fiscal de référence et le nombre de personnes du foyer.";
    if (n === 6) return 'Choisissez au moins un aménagement.';
    return '';
  }
  /* Un bouton grisé dit toujours pourquoi. */
  function showMissing(screen, cta, msg){
    if (!screen || !cta) return;
    var p = screen.querySelector('.rf-missing');
    if (!p){
      p = document.createElement('p');
      p.className = 'rf-missing'; p.setAttribute('aria-live', 'polite');
      cta.parentNode.insertBefore(p, cta.nextSibling);
    }
    p.textContent = msg || '';
    p.hidden = !msg;
  }
  function refresh(){
    var screen = document.getElementById('s' + current);
    if (!screen) return;
    var cta = screen.querySelector('[data-next], #go-results');
    if (cta) cta.disabled = !stepValid(current);
    showMissing(screen, cta, stepMissing(current));
    var run = document.getElementById('run-total');
    if (run && C){
      var t = 0;
      state.travaux.forEach(function(c){ t += (C.MPA_COUTS_INDICATIFS[c] || 0); });
      run.textContent = fmt(t);
    }
  }

  /* ── Traçabilité : catégorie de revenus détectée en temps réel ─────
     L'utilisateur doit comprendre d'où vient son taux avant de voir un montant. */
  var CAT_HINT = {
    bleus:   { nom: 'très modestes',   color: '#1F6B3F' },
    jaunes:  { nom: 'modestes',        color: '#065F46' },
    violets: { nom: 'intermédiaires',  color: '#991B1B' },
    roses:   { nom: 'supérieures',     color: '#123A2E' },
  };
  function updateCategorieHint(){
    var box = el('categorie-hint');
    if (!box) return;
    var rfr    = Number(val('rfr')) || 0;
    var foyer  = Number(val('foyer')) || 1;
    var region = val('region') || 'Grand Est';
    if (rfr <= 0 || !C || !C.categorie){ box.hidden = true; return; }

    var cat  = C.categorie(rfr, foyer, region);
    var conf = CAT_HINT[cat] || { nom: cat, color: 'var(--slate-500)' };
    var zone = (region === 'Île-de-France') ? 'idf' : 'hors_idf';
    var plaf = (C.plafond && cat !== 'roses') ? C.plafond(zone, cat, foyer) : null;
    var eligible = (cat === 'bleus' || cat === 'jaunes');

    box.style.borderLeftColor = conf.color;
    box.innerHTML =
      '<div class="cat-title" style="color:' + conf.color + '">' +
        '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6"><path d="m5 12 5 5L20 7"/></svg>' +
        'Ressources ' + conf.nom + '</div>' +
      '<div>Pour un foyer de <strong>' + foyer + ' personne' + (foyer > 1 ? 's' : '') + '</strong> ' +
        (zone === 'idf' ? 'en Île-de-France' : 'hors Île-de-France') + ', ' +
        (plaf ? 'le plafond de cette catégorie est de <strong>' + plaf.toLocaleString('fr-FR') + ' €</strong>. ' : '') +
        'Votre revenu fiscal de référence de <strong>' + rfr.toLocaleString('fr-FR') + ' €</strong> vous y place.</div>' +
      '<div class="cat-taux">' + (eligible
        ? "Taux MaPrimeAdapt' applicable : <strong>" + Math.round((C.MPA.tauxParCategorie[cat] || 0) * 100) + " %</strong> du coût des travaux, dans la limite de " + C.MPA.plafondTravauxHT.toLocaleString('fr-FR') + " € HT. En plus, l'Anah prend en charge l'accompagnement AMO à hauteur d'un forfait de 350 à 800 € selon le niveau de prestation."
        : "MaPrimeAdapt' est réservée aux ménages modestes et très modestes : cette catégorie n'y ouvre pas droit. Nous vous indiquerons les autres leviers mobilisables.") + '</div>';
    box.hidden = false;
  }

  ['foyer','rfr','region'].forEach(function(id){
    var input = el(id);
    if (input) input.addEventListener('input', function(){ persist(); refresh(); updateCategorieHint(); });
    if (input) input.addEventListener('change', function(){ persist(); refresh(); updateCategorieHint(); });
  });
  updateCategorieHint();
  // Restaure les champs revenus
  try {
    var s2 = JSON.parse(localStorage.getItem(STORE) || 'null');
    if (s2){
      if (s2.foyer)  document.getElementById('foyer').value = s2.foyer;
      if (s2.rfr)    document.getElementById('rfr').value = s2.rfr;
      if (s2.region) document.getElementById('region').value = s2.region;
    }
  } catch(e){}

  /* ── Résultats ──────────────────────────────────────────────── */
  /* ── Étape 6 : Transmission ──────────────────────────────────── */
  var lastResult = null;
  var lastPayload = null;
  function computeAndStore(){
    if (!C || !C.computeMprAdapt) return null;
    var payload = {
      rfr: Number(val('rfr')) || 0,
      foyer: Number(val('foyer')) || 1,
      region: val('region') || 'Grand Est',
      age: Number(state.age) || 0,
      gir: state.gir || null,
      handicap: (state.handicap === 'inconnu' ? 'non' : (state.handicap || 'non')),
      travaux: state.travaux,
      amoType: 'complet',
      // Enrichit le profil stocké dans le dossier. computeMprAdapt() ignore
      // proprement les champs qu'il n'utilise pas.
      logement: {
        adresse:    state.logement.adresse || null,
        codePostal: state.logement.codePostal || null,
        ville:      state.logement.ville || null,
        dept:       state.logement.dept || null,
        codeInsee:  state.logement.codeInsee || null,
        region:     state.logement.region || null,
        surface:    state.logement.surface || null,
        annee:      state.logement.annee || null,
        type:       state.logement.type || null,
      },
    };
    var result = C.computeMprAdapt(payload);
    try {
      localStorage.setItem('junglerenov.autonomie.result', JSON.stringify({
        input: Object.assign({}, payload, { who: state.who, girChoice: state.girChoice }),
        result: result, computedAt: new Date().toISOString(),
      }));
    } catch(e){}
    lastResult = result;
    lastPayload = payload;
    try { if (window.rfUpdateCheckoutAmount) window.rfUpdateCheckoutAmount(); } catch(e){}
    return result;
  }

  /* ── Étape Transmission : teaser étape de transmission ──────────────────────── */
  function roundDown100(n){
    // Arrondi indicatif au millier inférieur (à la centaine inférieure sous 1 000 €).
    // Aucun décalage arbitraire : un montant pile sur un multiple reste inchangé.
    // C'est le calcul réel qui varie selon la saisie, jamais l'arrondi.
    var v = Number(n) || 0;
    if (v < 1000) return Math.max(0, Math.floor(v / 100) * 100);
    return Math.floor(v / 1000) * 1000;
  }

  var CAT_TAUX = { bleus:'très modestes', jaunes:'modestes', violets:'intermédiaires', roses:'supérieurs' };

  function renderTeaser(result){
    /* Mises en garde du moteur et version des barèmes, comme sur le tunnel principal. */
    if (window.RFAlertes){
      try {
        RFAlertes.rendre(result, 'rf-alertes');
        RFAlertes.rendreReferentiel(result, 'rf-referentiel');
        RFAlertes.rendreReferentiel(result, 'rf-referentiel-final');
      } catch (e) { console.warn('Alertes :', e); }
    }
    var vEl = document.getElementById('tz-verdict');
    if (!vEl) return;
    // L'utilisateur peut revenir corriger ses réponses : on restaure le bloc de
    // transmission, qu'un passage précédent a pu masquer (cas non éligible).
    if (window.RFPartner) window.RFPartner.mount();
    var checkoutM = document.getElementById('rf-mpa-checkout');
    if (checkoutM) checkoutM.hidden = false;
    validateMPA();
    if (!result || !result.eligible){
      vEl.innerHTML = '<div class="tz-verdict ko">' +
        '<span><b>' + "MaPrimeAdapt' ne peut pas être mobilisée dans cette situation" + '</b>' +
        (result && result.motif ? escapeHtml(result.motif) : "Les conditions d'éligibilité ne sont pas réunies avec les réponses fournies.") +
        '</span></div>';
      // Rien à transmettre si l'aide est nulle : le bloc entier est masqué.
      if (checkoutM) checkoutM.hidden = true;
      return;
    }
    var montant = result.aide.total;
    var arrondi = roundDown100(montant);
    vEl.innerHTML = '<div class="tz-verdict">' +
        '<svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" style="flex:0 0 auto;margin-top:2px"><path d="m5 12 5 5L20 7"/></svg>' +
        '<span><b>' + "Vous êtes éligible à MaPrimeAdapt'" + '</b>' + (function(){
        var CAT = { bleus:'très modestes', jaunes:'modestes' };
        var MOTIFS = { senior_70plus:'70 ans ou plus', senior_60_69_gir:'60 à 69 ans avec évaluation GIR',
                       handicap_50plus:"taux d'incapacité ≥ 50 %", handicap_pch:'bénéficiaire de la PCH' };
        var e = result.eligibilite || {};
        return 'Catégorie : <strong>' + (CAT[e.categorie] || e.categorie || '—') + '</strong>' +
               (MOTIFS[e.motif] ? ' · condition retenue : ' + MOTIFS[e.motif] : '');
      })() + '</span>' +
      '</div>' +
      '<div class="tz-amount"><div class="lbl">Aide estimée jusqu\'à</div>' +
        '<div class="v">~ ' + arrondi.toLocaleString('fr-FR') + ' €</div>' +
        // Traçabilité complète : chaque euro du total est justifié à l'écran.
        (function(){
          var t = result.travaux, ai = result.aide, cat = result.eligibilite.categorie;
          var plafonne = t.coutEstime > t.plafond;
          function ligne(k, v, cls){
            return '<div class="r' + (cls ? ' ' + cls : '') + '"><span>' + k + '</span><b>' + v + '</b></div>';
          }
          return '<div class="tz-calc"><div class="h">Comment ce montant est calculé</div>' +
            ligne('Travaux sélectionnés', fmt(t.coutEstime) + ' HT') +
            (plafonne ? ligne('Coût retenu (plafond ' + fmt(t.plafond) + ')', fmt(t.coutRetenu)) : '') +
            ligne('Catégorie de revenus', CAT_TAUX[cat] || cat) +
            ligne('Taux appliqué', Math.round(ai.tauxApplique * 100) + ' %') +
            ligne("Aide MaPrimeAdapt' travaux", fmt(ai.travaux)) +
            ligne("Accompagnement AMO — forfait Anah", fmt(ai.amo)) +
            ligne('Total calculé', fmt(ai.total), 'tot') +
          '</div>';
        })() +
        '<div class="hint tz-hint-fine">Arrondi indicatif — le montant définitif est arrêté par l\u2019Anah à l\u2019instruction du dossier.</div>' +
      '</div>';
  }

  function escapeHtml(s){
    return String(s == null ? '' : s).replace(/[&<>"]/g, function(c){
      return ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;' })[c];
    });
  }




  /* Le brouillon est créé dès l'arrivée sur l'étape de transmission, pour que
     le dossier transmis soit exactement celui qui a été affiché. */
  function assurerBrouillon(){
    try {
      if (!window.RFDossiers) return null;
      var draft = (RFDossiers.getOrCreateDraft || RFDossiers.createDraft)('autonomie', lastPayload || {}, lastResult);
      if (draft && draft.id) localStorage.setItem('junglerenov.dossierEnAttente', draft.id);
      return draft;
    } catch(e){ console.warn('Création dossier autonomie :', e); return null; }
  }

  /* ── Étape 7 — animation du calcul, puis passage automatique à l'étape 8 ──
     Même rythme que le tunnel énergétique : 6 items à ~900 ms. */
  var calcTimers = [];
  function stopCalcAnimation(){ calcTimers.forEach(function(t){ clearTimeout(t); }); calcTimers = []; }
  function startCalcAnimation(){
    stopCalcAnimation();
    var items   = document.querySelectorAll('#mpa-loader-checks .lc-item');
    var circle  = el('mpa-loader-circle');
    var pctEl   = el('mpa-loader-pct');
    var titleEl = el('mpa-loader-title');
    var subEl   = el('mpa-loader-sub');
    if (!items.length || !circle) return;
    var subs = [
      'Sources : Base Adresse Nationale + IGN',
      "Sources : critères d'éligibilité MaPrimeAdapt' (décret 2023-1104)",
      'Sources : barèmes Anah publiés au JO',
      'Sources : réseau des opérateurs AMO agréés',
      'Sources : conseils départementaux (APA) et MDPH (PCH)',
      'Sources : Guide Anah éd. février 2026, pp. 57-60'
    ];
    var DOT = '<svg width="10" height="10" viewBox="0 0 24 24" fill="currentColor"><circle cx="12" cy="12" r="6"/></svg>';
    var TICK = '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="m5 12 5 5L20 7"/></svg>';
    items.forEach(function(it){
      it.classList.remove('done','active');
      it.querySelector('.ic').innerHTML = DOT;
    });
    circle.style.setProperty('--p','0%');
    if (pctEl) pctEl.textContent = '0%';
    if (titleEl) titleEl.textContent = 'Connexion aux bases officielles…';
    if (subEl) subEl.textContent = 'Quelques secondes, ne fermez pas la fenêtre.';

    var stepDur = 900;
    items.forEach(function(it, i){
      calcTimers.push(setTimeout(function(){
        if (current !== 7) return;
        items.forEach(function(x){ x.classList.remove('active'); });
        it.classList.add('active');
        it.querySelector('.ic').innerHTML = '<span class="spinner"></span>';
        if (titleEl) titleEl.textContent = it.dataset.lbl;
        if (subEl) subEl.textContent = subs[i] || '';
      }, i * stepDur));
      calcTimers.push(setTimeout(function(){
        if (current !== 7) return;
        it.classList.remove('active');
        it.classList.add('done');
        it.querySelector('.ic').innerHTML = TICK;
        var pct = Math.round(((i+1) / items.length) * 100);
        circle.style.setProperty('--p', pct + '%');
        if (pctEl) pctEl.textContent = pct + '%';
      }, (i + 1) * stepDur));
    });
    calcTimers.push(setTimeout(function(){
      if (current !== 7) return;
      if (titleEl) titleEl.textContent = 'Analyse terminée';
      if (subEl) subEl.textContent = 'Affichage de votre estimation…';
    }, items.length * stepDur));
    calcTimers.push(setTimeout(function(){
      if (current === 7) goTo(8);
    }, items.length * stepDur + 600));
  }

  document.getElementById('go-results').addEventListener('click', function(){
    // Le teaser est rendu par goTo(8) : source unique. On passe d'abord par le calcul.
    persist();
    goTo(7);
  });


  /* ── Transmission (même écran que le tunnel énergétique) ───────
     Le brouillon est créé à l'arrivée sur l'étape (assurerBrouillon) ; il passe
     à l'état « créé » au clic sur « Créer mon dossier ». */
  function updateMpaCheckoutAmount(){
    var amountEl = document.getElementById('mpa-roi-amount');
    if (!amountEl || !lastResult) return;
    var total = (lastResult.aide && lastResult.aide.total) || 0;
    amountEl.textContent = Math.round(Number(total) || 0).toLocaleString('fr-FR') + ' €';
    try { if (window.__rfLeadMagnet_mpa) window.__rfLeadMagnet_mpa(total); } catch(e){}
  }
  window.rfUpdateCheckoutAmount = updateMpaCheckoutAmount;

  /* Récapitulatif de transmission : aucun montant relatif à JungleRenov. */
  function updateRecapTransmission(){
    var setTxt = function(id, v){ var e2 = document.getElementById(id); if (e2) e2.textContent = v; };
    var lg = (lastPayload && lastPayload.logement) || {};
    setTxt('tx-adresse', lg.adresse || '—');
    var total = (lastResult && lastResult.aide && lastResult.aide.total) || 0;
    setTxt('tx-aides', total ? Math.round(total).toLocaleString('fr-FR') + ' €' : '—');
    if (window.RFTransmission){
      RFTransmission.injectStyles();
      var dept = lg.dept || (lg.codePostal ? String(lg.codePostal).slice(0, 2) : '')
              || RFTransmission.deptFromDossier({ profile: { logement: lg } });
      var pro = RFTransmission.renderProfessionnel(document.getElementById('rf-tx-pro'), 'autonomie', dept);
      window.__rfPro = pro;
      var dest = document.getElementById('tx-destinataire');
      if (dest && pro) dest.textContent = pro.designe
        ? pro.nom + ' (' + pro.role + ')'
        : "l'accompagnateur agréé " + pro.role + ' désigné pour mon département';
    }
    assurerBrouillon();
  }
  window.rfUpdateRecapTransmission = updateRecapTransmission;

  /* Transmission : le bouton n'est actif qu'avec le consentement explicite à
     la transmission des données et l'acceptation des CGU. Jamais pré-coché. */
  var mpaTos = document.getElementById('mpa-tos');
  var mpaConsent = document.getElementById('mpa-transmission');
  var mpaSubmit = document.getElementById('mpa-submit');

  function validateMPA(){
    if (!mpaSubmit) return;
    var fn = (document.getElementById('mpa-firstname') || {}).value || '';
    var ln = (document.getElementById('mpa-lastname') || {}).value || '';
    var em = (document.getElementById('mpa-email') || {}).value || '';
    var ok = fn.trim().length >= 2
          && ln.trim().length >= 2
          && /^\S+@\S+\.\S+$/.test(em.trim())
          && !!(mpaTos && mpaTos.checked)
          && !!(mpaConsent && mpaConsent.checked);
    mpaSubmit.disabled = !ok;
    mpaSubmit.style.opacity = ok ? '1' : '.55';
    mpaSubmit.style.cursor = ok ? 'pointer' : 'not-allowed';
  }
  ['mpa-firstname','mpa-lastname','mpa-email','mpa-tos','mpa-transmission'].forEach(function(id){
    var el2 = document.getElementById(id);
    if (!el2) return;
    el2.addEventListener('input', validateMPA);
    el2.addEventListener('change', validateMPA);
  });
  validateMPA();

  if (mpaSubmit) mpaSubmit.addEventListener('click', function(){
    if (mpaSubmit.disabled) return;
    var label = mpaSubmit.textContent;
    mpaSubmit.disabled = true;
    mpaSubmit.textContent = 'Transmission…';

    /* Garde : un dossier n'est jamais transmis sans résultat calculé. Cascade —
       dernier calcul en mémoire, puis estimation stockée, puis rejeu du moteur. */
    var resoudreResultat = function(){
      var ok = function(r){ return !!(r && r.aide && (r.aide.totalApresEcretement > 0 || r.aide.total > 0)); };
      if (ok(lastResult)) return lastResult;
      try {
        var stored = JSON.parse(localStorage.getItem('junglerenov.autonomie.result') || 'null');
        if (stored && ok(stored.result)) return stored.result;
      } catch(e){}
      try {
        var C2 = window.RFCompute;
        if (C2 && C2.computeMprAdapt && lastPayload){
          var r = C2.computeMprAdapt(lastPayload);
          if (ok(r)) return r;
        }
      } catch(e){ console.warn('[Transmission autonomie] rejeu du moteur impossible :', e); }
      return null;
    };

    var resultatValide = resoudreResultat();
    if (!resultatValide){
      console.error('[Transmission autonomie] résultat vide — création du dossier abandonnée');
      mpaSubmit.disabled = false;
      mpaSubmit.textContent = label;
      var box = document.createElement('div');
      box.setAttribute('role', 'alert');
      box.style.cssText = 'position:fixed;top:20px;left:50%;transform:translateX(-50%);z-index:2147483001;background:#FEE2E2;border:2px solid #991B1B;color:#991B1B;padding:16px 24px;border-radius:6px;max-width:420px;font:17px/1.5 "Komet","Red Hat Display",system-ui,sans-serif;box-shadow:none';
      box.innerHTML = '<strong>Impossible de transmettre votre dossier</strong><br />' +
        "Votre aide MaPrimeAdapt' n'a pas pu être calculée. Reprenez le parcours depuis la première étape. " +
        '<a href="parcours-autonomie.dc.html?fresh=1" style="color:#1F6B3F;font-weight:600">Reprendre</a>';
      document.body.appendChild(box);
      setTimeout(function(){ if (box.parentNode) box.parentNode.removeChild(box); }, 15000);
      return;
    }

    try {
      /* Identité : le compte sert au suivi du dossier, jamais à facturer. */
      var prof = {};
      try { prof = JSON.parse(localStorage.getItem('junglerenov.profile') || '{}'); } catch(e){}
      prof.firstname = (document.getElementById('mpa-firstname') || {}).value || prof.firstname;
      prof.lastname  = (document.getElementById('mpa-lastname') || {}).value || prof.lastname;
      prof.email     = (document.getElementById('mpa-email') || {}).value || prof.email;
      prof.telephone = (document.getElementById('mpa-tel') || {}).value || prof.telephone;
      localStorage.setItem('junglerenov.profile', JSON.stringify(prof));

      var dossierId = localStorage.getItem('junglerenov.dossierEnAttente');
      if (!dossierId && window.RFDossiers){
        var d = (RFDossiers.getOrCreateDraft || RFDossiers.createDraft)('autonomie', lastPayload || {}, resultatValide);
        dossierId = d && d.id;
      }
      // Le brouillon a pu être créé avant le dernier recalcul : on le réaligne.
      if (window.RFDossiers && dossierId && RFDossiers.updateResult) RFDossiers.updateResult(dossierId, resultatValide);

      var pro = window.__rfPro || null;
      if (window.RFTransmission && dossierId){
        RFTransmission.transmettre(dossierId, {
          consentement: true,
          partenaireNom: pro && pro.nom,
          partenaireRole: pro && pro.role,
          departement: pro && pro.departement,
        });
      }
      localStorage.removeItem('junglerenov.dossierEnAttente');

      var succ = document.getElementById('mpa-success');
      if (succ){
        document.getElementById('mpa-signup').style.display = 'none';
        var partEl = document.getElementById('mpa-succ-partenaire');
        if (partEl) partEl.textContent = (pro && pro.nom) || 'Un accompagnateur agréé de votre département';
        succ.classList.add('show');
        jrScrollTo(succ);
      }
      setTimeout(function(){
        /* Le tableau de bord est la seule page qui traite ?transmis=1, et ces
           tunnels ne créent ni client ni session : « Mes aides » renverrait
           l'utilisateur sur un mur de connexion juste après son succès. */
        location.href = 'dashboard.dc.html?transmis=1' + (dossierId ? '&dossier=' + encodeURIComponent(dossierId) : '');
      }, 2200);
    } catch(err){ console.warn('Transmission autonomie :', err); location.href = 'dashboard.dc.html'; }
  });

  bindStepperClicks();
  goTo(1);
})();

