/* Redémarrage propre du tunnel : ?fresh=1 purge le brouillon en cours.
   Cas habitat dégradé : dernière estimation locale et brouillon en attente de transmission.
   En développement local seulement, les dossiers sont purgés aussi, pour repartir
   d'un tableau de bord vide. Partout ailleurs, junglerenov.dossiers survit toujours —
   de même que le compte et la session, dans tous les cas. */
(function resetIfFresh(){
  try {
    var params = new URLSearchParams(location.search);
    if (params.get('fresh') !== '1') return;
    localStorage.removeItem('junglerenov.indigne.result');
    localStorage.removeItem('junglerenov.dossierEnAttente');
    localStorage.removeItem('junglerenov.returnTo');
    /* (purge des données de test retirée) */
    history.replaceState(null, '', location.pathname);
  } catch (_) {}
})();

pages/parcours-indigne/02.js:
(function(){
  var C = window.RFCompute;
  var STORE = 'junglerenov.indigne';
  var state = { variant:null, etat:null, arrete:null, convention:null, immat:null, logement:{}, copro:{} };
  try {
    var saved = JSON.parse(localStorage.getItem(STORE) || 'null');
    if (saved && typeof saved === 'object') state = Object.assign(state, saved);
  } catch(e){}

  function el(id){ return document.getElementById(id); }
  function val(id){ var e = el(id); return e ? e.value : ''; }
  function num(id){ return Number(val(id)) || 0; }
  function fmt(n){ return Math.round(n||0).toLocaleString('fr-FR') + ' €'; }

  var FIELDS = ['surface','annee','dpe-avant','dpe-apres','cout','lots','annee-copro','part-rp','foyer','rfr','region'];
  function persist(){
    var payload = Object.assign({}, state);
    FIELDS.forEach(function(id){ payload[id] = val(id); });
    payload['arrete-type'] = val('arrete-type');
    try { localStorage.setItem(STORE, JSON.stringify(payload)); } catch(e){}
  }
  // Restaure les champs
  FIELDS.concat(['arrete-type']).forEach(function(id){
    if (state[id] !== undefined && state[id] !== '' && el(id)) el(id).value = state[id];
  });

  /* ── Enchaînement des étapes selon le statut ─────────────────── */
  function flow(){
    if (state.variant === 'bailleur') return [1,2,3,4,6,7,9,8];
    if (state.variant === 'copro')    return [1,2,3,5,7,9,8];
    return [1,2,3,6,7,9,8]; // occupant
  }
  var current = 1;
  var maxReachedPos = 0;   // rang atteint DANS le flux, pas numéro d'écran

  /* Fil d'Ariane : masque les étapes hors flux, numérote de façon contiguë,
     et n'ouvre au clic que les étapes déjà parcourues. */
  function refreshStepperStates(){
    var seq = flow(), pos = seq.indexOf(current);
    document.querySelectorAll('.pip[data-goto]').forEach(function(p){
      var t = Number(p.dataset.goto), idx = seq.indexOf(t);
      p.classList.remove('done', 'active', 'pending', 'hors-flux');
      if (idx === -1){
        // Étape sans objet pour ce statut : on la retire du fil
        p.classList.add('hors-flux');
        p.hidden = true;
        p.removeAttribute('role'); p.removeAttribute('tabindex'); p.removeAttribute('aria-label');
        return;
      }
      p.hidden = false;
      // Numérotation contiguë : rang dans le flux, pas index d'écran
      var numEl = p.querySelector('.num');
      if (numEl) numEl.textContent = String(idx + 1);
      // Une étape déjà atteinte reste « done » (donc cliquable) même après un
      // retour en arrière : elle ne doit pas repasser en grisé.
      if (idx === pos)            p.classList.add('active');
      else if (idx <= maxReachedPos) p.classList.add('done');
      else                        p.classList.add('pending');
      if (idx !== pos && idx <= maxReachedPos && !p.hasAttribute('data-non-cliquable')){
        p.setAttribute('role', 'button');
        p.setAttribute('tabindex', '0');
        var lbl = p.querySelector('span:last-child');
        p.setAttribute('aria-label', "Retourner à l'étape " + (lbl ? lbl.textContent : (idx + 1)));
      } else {
        p.removeAttribute('role'); p.removeAttribute('tabindex'); p.removeAttribute('aria-label');
      }
      p.setAttribute('aria-current', idx === pos ? 'step' : 'false');
    });
  }

  function bindStepperClicks(){
    document.querySelectorAll('.pip[data-goto]').forEach(function(p){
      function jump(){
        var t = Number(p.dataset.goto), seq = flow();
        var idx = seq.indexOf(t), pos = seq.indexOf(current);
        if (idx === -1) return;                            // hors flux du statut courant
        // Navigation libre entre les étapes DÉJÀ atteintes, dans les deux sens.
        if (idx === pos || idx > maxReachedPos) return;     // étape non atteinte
        // L'écran de calcul est une transition, pas une étape sur laquelle revenir
        if (p.hasAttribute('data-non-cliquable')) return;
        goTo(t);
      }
      p.addEventListener('click', jump);
      p.addEventListener('keydown', function(e){
        if (e.key === 'Enter' || e.key === ' '){ e.preventDefault(); jump(); }
      });
    });
  }

  function goTo(n){
    current = n;
    document.querySelectorAll('.screen').forEach(function(s){ s.classList.remove('active'); });
    var sc = el('s' + n);
    if (sc) sc.classList.add('active');
    // Étape la plus avancée atteinte dans le flux courant : borne le retour arrière
    var seqNow = flow(), posNow = seqNow.indexOf(n);
    if (posNow > maxReachedPos) maxReachedPos = posNow;
    refreshStepperStates();
    // L'étape Transmission (toujours la dernière du flux) est recalculée à CHAQUE
    // affichage : on peut y revenir par le fil d'Ariane après modification.
    if (posNow === seqNow.length - 1){
      /* Une opération, un try : l'échec du teaser ne doit jamais empêcher le
         récapitulatif de se remplir (sinon adresse, montant et brouillon restent vides). */
      try { renderTeaser(computeAndStore()); } catch(e){ console.error('Teaser :', e); }
      try { if (window.rfUpdateRecapTransmission) window.rfUpdateRecapTransmission(); }
      catch(e){ console.error('Récapitulatif de transmission :', e); }
    }

    // Intitulé « Étape N sur M » calculé sur le flux réel du statut choisi
    var eyebrow = sc && sc.querySelector('.eyebrow');
    if (eyebrow && posNow !== -1){
      eyebrow.textContent = (posNow === seqNow.length - 1)
        ? 'Étape ' + seqNow.length + ' sur ' + seqNow.length + ' · dernière étape'
        : 'Étape ' + (posNow + 1) + ' sur ' + seqNow.length;
    }
    // Le CTA de l'écran courant pointe vers l'étape suivante du flux
    var cta = sc && sc.querySelector('[data-next]');
    if (cta && posNow !== -1 && seqNow[posNow+1]) cta.dataset.next = seqNow[posNow+1];
    var back = sc && sc.querySelector('[data-prev]');
    if (back && posNow > 0){
      // On ne renvoie jamais l'utilisateur sur l'\u00e9cran de calcul (transition auto)
      var prevStep = seqNow[posNow-1];
      if (prevStep === 9) prevStep = seqNow[posNow-2] || 1;
      back.dataset.prev = prevStep;
    }
    if (n === 7) buildRecap();
    if (n === 9) startCalcAnimation(); else stopCalcAnimation();
    window.scrollTo({ top:0, behavior:'smooth' });
    refresh();
  }
  document.addEventListener('click', function(ev){
    var b = ev.target.closest('[data-next],[data-prev],#back-recap');
    if (!b) return;
    if (b.id === 'back-recap'){
      var seq = flow(), i = seq.indexOf(7);
      goTo(i > 0 ? seq[i - 1] : 1); return;
    }
    if (b.dataset.next){ persist(); goTo(Number(b.dataset.next)); }
    else if (b.dataset.prev){ goTo(Number(b.dataset.prev)); }
  });

  /* ── Groupes à choix unique ─────────────────────────────────── */
  function singleSelect(id, key, onPick){
    var box = el(id);
    if (!box) return;
    box.querySelectorAll('.tile').forEach(function(t){
      if (state[key] === t.dataset.val) t.classList.add('selected');
      t.addEventListener('click', function(){
        box.querySelectorAll('.tile').forEach(function(x){ x.classList.remove('selected'); });
        t.classList.add('selected');
        state[key] = t.dataset.val;
        if (onPick) onPick(t.dataset.val);
        persist(); refresh();
      });
    });
  }
  singleSelect('variant', 'variant', function(){
    // Nouveau statut = nouveau flux : on réinitialise la progression atteinte
    maxReachedPos = 0;
    goTo(1);
  });
  singleSelect('etat', 'etat', function(v){
    el('arrete-field').hidden = (v !== 'arrete_police');
    if (v !== 'arrete_police') el('arrete-type').value = '';
  });
  singleSelect('convention', 'convention', function(v){
    el('conv-warn').hidden = (v !== 'non');
  });
  singleSelect('immat', 'immat');
  el('arrete-type').addEventListener('change', function(){ persist(); refresh(); });

  /* ── Adresse (Base Adresse Nationale) ───────────────────────── */
  state.logement = state.logement || {};

  /* Région déduite du département : sert au barème de plafonds de revenus. */
  var DEPTS_IDF = ['75','77','78','91','92','93','94','95'];
  var DEPTS_GRAND_EST = ['08','10','51','52','54','55','57','67','68','88'];
  function regionFromDept(dept){
    if (DEPTS_IDF.indexOf(dept) !== -1) return 'Île-de-France';
    if (DEPTS_GRAND_EST.indexOf(dept) !== -1) return 'Grand Est';
    return 'Autre';
  }
  function escHtml(s){
    return String(s == null ? '' : s).replace(/[&<>"]/g, function(c){
      return ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;' })[c];
    });
  }

  /* Un même comportement pour les deux champs d'adresse, mais chacun écrit dans
     SON emplacement d'état : l'adresse du logement et celle de la copropriété
     sont deux informations distinctes qui ne doivent pas s'écraser. */
  function bindBanField(prefix, slot){
    var input = el(prefix + '-adresse');
    var sugg  = el(prefix + '-adresse-suggestions');
    if (!input || !sugg) return;
    state[slot] = state[slot] || {};
    function close(){ sugg.hidden = true; sugg.innerHTML = ''; }
    /* Secours : BAN injoignable ou adresse inconnue → saisie manuelle, code postal exigé. */
    var secours = window.RFAdresseSecours ? RFAdresseSecours.attach(input, {
      regionFromDept: regionFromDept,
      onValide: function(data){
        var S = state[slot];
        if (data){
          S.adresse = data.adresse; S.codePostal = data.codePostal; S.ville = data.ville;
          S.dept = data.dept; S.region = data.region; S.saisieManuelle = true;
        } else S.adresse = null;
        persist(); refresh();
      },
    }) : { ouvrir: function(){} };
    var timer = null;
    input.addEventListener('input', function(){
      clearTimeout(timer);
      // Une saisie libre invalide l'adresse retenue : il faut choisir une suggestion.
      state[slot].adresse = null;
      persist(); refresh();
      var q = input.value.trim();
      if (q.length < 5){ close(); return; }
      timer = setTimeout(function(){
        fetch('https://api-adresse.data.gouv.fr/search/?q=' + encodeURIComponent(q) + '&limit=5')
          .then(function(r){ if (!r.ok) throw new Error(r.status); return r.json(); })
          .then(function(j){
            var feats = (j && j.features) || [];
            if (!feats.length){ close(); secours.ouvrir("Cette adresse n'est pas dans la base. Saisissez-la ci-dessous."); return; }
            sugg.innerHTML = feats.map(function(f, i){
              var p = f.properties || {};
              return '<button type="button" class="ban-item" data-i="' + i + '">' +
                '<span class="lbl">' + escHtml(p.label || '') + '</span>' +
                '<span class="ctx">' + escHtml(p.context || '') + '</span></button>';
            }).join('');
            sugg.hidden = false;
            sugg.querySelectorAll('.ban-item').forEach(function(btn){
              btn.addEventListener('click', function(){
                var p = (feats[Number(btn.dataset.i)] || {}).properties || {};
                var cp = String(p.postcode || '');
                var S = state[slot];
                S.adresse    = p.label || '';
                S.codePostal = cp;
                S.ville      = p.city || '';
                S.dept       = cp.slice(0, 2);
                S.codeInsee  = p.citycode || '';
                S.contexte   = p.context || '';
                S.region     = regionFromDept(S.dept);
                input.value  = S.adresse;
                close();
                // La région déduite pré-sélectionne le barème de l'étape Revenus
                var regSel = el('region');
                if (regSel && S.region) regSel.value = S.region;
                persist(); refresh();
              });
            });
          })
          .catch(function(e){ console.warn('[JungleRenov] BAN :', e); close(); secours.ouvrir("Le service d'adresses ne répond pas. Saisissez votre adresse ci-dessous."); });
      }, 250);
    });
    input.addEventListener('blur', function(){ setTimeout(close, 150); });
    // Restaure l'adresse propre à ce champ
    if (state[slot].adresse) input.value = state[slot].adresse;
  }
  bindBanField('li', 'logement');
  bindBanField('co', 'copro');

  /* Type de logement — écrit dans state.logement */
  (function(){
    var box = el('li-type');
    if (!box) return;
    box.querySelectorAll('.tile').forEach(function(t){
      if (state.logement.type === t.dataset.val) t.classList.add('selected');
      t.addEventListener('click', function(){
        box.querySelectorAll('.tile').forEach(function(x){ x.classList.remove('selected'); });
        t.classList.add('selected');
        state.logement.type = t.dataset.val;
        persist(); refresh();
      });
    });
  })();

  /* ── Notes contextuelles ────────────────────────────────────── */
  function contextNotes(){
    updateCategorieHint();
    var cn = el('copro-arrete-note');
    if (cn) cn.hidden = !(state.variant === 'copro' && state.etat && state.etat !== 'arrete_police');

    var dn = el('dpe-note');
    if (dn){
      var a = val('dpe-avant'), b = val('dpe-apres');
      var ORDRE = ['A','B','C','D','E','F','G'];
      var ib = ORDRE.indexOf(b);
      if (state.variant === 'occupant' && ib >= 0 && ib > 4){
        dn.hidden = false;
        dn.textContent = "Si les travaux n'atteignent pas la classe E, Ma Prime Logement Décent s'applique en régime dérogatoire : 50 % d'un plafond de 50 000 € HT.";
      } else if (state.variant === 'occupant' && (a === 'F' || a === 'G') && ib >= 0 && ib <= 2){
        dn.hidden = false;
        dn.textContent = "Sortie de passoire énergétique (" + a + " → " + b + ") : une prime de 10 % du montant retenu s'ajoute à l'aide de base.";
      } else if (state.variant === 'bailleur' && ib >= 0 && ib > 3){
        dn.hidden = false;
        dn.textContent = "Les aides LHI bailleur supposent d'atteindre au minimum la classe D après travaux.";
      } else {
        dn.hidden = true;
      }
    }

    var cs = el('copro-seuil-note');
    if (cs){
      var lots = num('lots'), part = num('part-rp');
      if (lots > 0 && part > 0){
        var seuil = lots <= 20 ? 65 : 75;
        if (part < seuil){
          cs.hidden = false;
          cs.className = 'note warn';
          cs.textContent = "Avec " + lots + " lots, le seuil requis est de " + seuil + " % de résidences principales. "
            + "La part indiquée (" + part + " %) est inférieure : l'aide pourra être refusée à l'instruction.";
        } else {
          cs.hidden = false;
          cs.className = 'note';
          cs.textContent = "Seuil de " + seuil + " % de résidences principales atteint.";
        }
      } else { cs.hidden = true; }
    }

    var rn = el('revenu-note');
    if (rn && C && state.variant === 'occupant'){
      var rfr = num('rfr'), foyer = num('foyer');
      if (rfr > 0 && foyer > 0){
        var cat = C.categorie ? C.categorie(rfr, foyer, val('region') || 'Grand Est') : null;
        var LB = { bleus:'très modestes', jaunes:'modestes', violets:'intermédiaires', roses:'supérieurs' };
        var ok = (cat === 'bleus' || cat === 'jaunes');
        rn.hidden = false;
        rn.className = ok ? 'note' : 'note warn';
        rn.textContent = ok
          ? "Catégorie de revenus : " + LB[cat] + ". Taux de financement " + (cat === 'bleus' ? '80' : '60') + " %."
          : "Catégorie de revenus : " + (LB[cat] || cat) + ". Ma Prime Logement Décent est réservée aux ménages modestes et très modestes — nous vous indiquerons les autres leviers.";
      } else { rn.hidden = true; }
    } else if (rn) { rn.hidden = true; }
  }

  /* ── Traçabilité : catégorie de revenus détectée en temps réel ─────
     L'utilisateur doit comprendre d'où vient son taux avant de voir un montant. */
  var CAT_HINT = {
    bleus:   { nom: 'très modestes',   color: '#1F6B3F' },
    jaunes:  { nom: 'modestes',        color: '#065F46' },
    violets: { nom: 'intermédiaires',  color: '#991B1B' },
    roses:   { nom: 'supérieures',     color: '#123A2E' },
  };
  function updateCategorieHint(){
    var box = el('categorie-hint');
    if (!box) return;
    var rfr    = num('rfr');
    var foyer  = num('foyer') || 1;
    var region = val('region') || 'Grand Est';
    // Le variant copropriété ne passe pas par l'étape Revenus
    if (rfr <= 0 || !C || !C.categorie){ box.hidden = true; return; }

    var cat  = C.categorie(rfr, foyer, region);
    var conf = CAT_HINT[cat] || { nom: cat, color: 'var(--slate-500)' };
    var zone = (region === 'Île-de-France') ? 'idf' : 'hors_idf';
    var plaf = (C.plafond && cat !== 'roses') ? C.plafond(zone, cat, foyer) : null;
    var eligible = (cat === 'bleus' || cat === 'jaunes');

    var taux;
    if (state.variant === 'bailleur'){
      taux = "Le taux des aides bailleur dépend de la nature des travaux (25 à 35 %), pas de vos revenus. "
           + "Votre catégorie sert au barème du locataire dans la convention Loc'Avantages.";
    } else if (eligible){
      var tx = Math.round((C.MPLD.travauxGlobalTresDegrade.tauxParCategorie[cat] || 0) * 100);
      taux = "Taux Ma Prime Logement Décent applicable : <strong>" + tx + " %</strong> du coût des travaux, "
           + "dans la limite de " + C.MPLD.travauxGlobalTresDegrade.plafondHT.toLocaleString('fr-FR') + " € HT "
           + "(50 % d'un plafond de " + C.MPLD.travauxDerogatoire.plafondHT.toLocaleString('fr-FR') + " € si la classe E n'est pas atteinte).";
    } else {
      taux = "Ma Prime Logement Décent est réservée aux ménages modestes et très modestes : cette catégorie "
           + "n'y ouvre pas droit. Nous vous indiquerons les autres leviers mobilisables.";
    }

    box.style.borderLeftColor = conf.color;
    box.innerHTML =
      '<div class="cat-title" style="color:' + conf.color + '">' +
        '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6"><path d="m5 12 5 5L20 7"/></svg>' +
        'Ressources ' + conf.nom + '</div>' +
      '<div>Pour un foyer de <strong>' + foyer + ' personne' + (foyer > 1 ? 's' : '') + '</strong> ' +
        (zone === 'idf' ? 'en Île-de-France' : 'hors Île-de-France') + ', ' +
        (plaf ? 'le plafond de cette catégorie est de <strong>' + plaf.toLocaleString('fr-FR') + ' €</strong>. ' : '') +
        'Votre revenu fiscal de référence de <strong>' + rfr.toLocaleString('fr-FR') + ' €</strong> vous y place.</div>' +
      '<div class="cat-taux">' + taux + '</div>';
    box.hidden = false;
  }

  /* ── Validation ─────────────────────────────────────────────── */
  function stepValid(n){
    if (n === 1) return !!state.variant;
    if (n === 2) return state.etat === 'arrete_police' ? !!val('arrete-type') : !!state.etat;
    // Étape 3 — Logement : adresse issue de la BAN, type, surface et coût
    if (n === 3){
      var L = state.logement || {};
      return !!(L.adresse && L.type) && num('cout') > 0 && num('surface') > 0;
    }
    if (n === 4) return !!state.convention;
    // Étape 5 — Copropriété : sa propre adresse est exigée, distincte de celle
    // du logement saisie à l'étape 3.
    if (n === 5) return !!(state.copro && state.copro.adresse) && num('lots') > 0 && !!state.immat;
    if (n === 6) return num('rfr') > 0 && num('foyer') > 0;
    return true;
  }
  function stepMissing(n){
    if (stepValid(n)) return '';
    if (n === 1) return 'Indiquez votre situation (propriétaire occupant, bailleur ou copropriété).';
    if (n === 2) return state.etat === 'arrete_police' ? "Précisez le type d'arrêté." : "Indiquez l'état du logement.";
    if (n === 3){
      var L = state.logement || {};
      if (!L.adresse) return "Choisissez votre adresse dans la liste, ou utilisez « Mon adresse n'apparaît pas ».";
      if (!L.type) return 'Indiquez le type de logement.';
      if (!(num('surface') > 0)) return 'Indiquez la surface habitable.';
      return 'Indiquez le montant estimé des travaux.';
    }
    if (n === 4) return 'Répondez à la question sur la convention.';
    if (n === 5){
      if (!(state.copro && state.copro.adresse)) return "Indiquez l'adresse de la copropriété — dans la liste, ou avec « Mon adresse n'apparaît pas ».";
      if (!(num('lots') > 0)) return 'Indiquez le nombre de lots.';
      return "Indiquez si la copropriété est immatriculée.";
    }
    if (n === 6) return "Indiquez votre revenu fiscal de référence et le nombre de personnes du foyer.";
    return '';
  }
  /* Un bouton grisé dit toujours pourquoi. */
  function showMissing(screen, cta, msg){
    if (!screen || !cta) return;
    var p = screen.querySelector('.rf-missing');
    if (!p){
      p = document.createElement('p');
      p.className = 'rf-missing'; p.setAttribute('aria-live', 'polite');
      cta.parentNode.insertBefore(p, cta.nextSibling);
    }
    p.textContent = msg || '';
    p.hidden = !msg;
  }
  function refresh(){
    contextNotes();
    var sc = el('s' + current);
    if (!sc) return;
    var cta = sc.querySelector('[data-next]');
    if (cta) cta.disabled = !stepValid(current);
    showMissing(sc, cta, stepMissing(current));
  }
  FIELDS.forEach(function(id){
    var e = el(id);
    if (e) e.addEventListener('input', function(){ persist(); refresh(); });
    if (e && e.tagName === 'SELECT') e.addEventListener('change', function(){ persist(); refresh(); });
  });

  /* ── Récapitulatif ──────────────────────────────────────────── */
  var LIB_VARIANT = { occupant:'Propriétaire occupant', bailleur:'Propriétaire bailleur', copro:'Copropriétaire' };
  var LIB_ETAT = {
    moyennement_degrade:'Moyennement dégradé', tres_degrade:'Très dégradé ou insalubre',
    arrete_police:'Sous arrêté de police', inconnu:'À évaluer',
  };
  var LIB_CONV = { oui:'Oui', info:'À approfondir', non:'Non' };
  function row(k, v){ return '<div class="r"><span class="k">' + k + '</span><span class="v">' + v + '</span></div>'; }
  function buildRecap(){
    var arrLib = (C && C.LHI_ARRETE_LIBELLES) || {};
    var L = state.logement || {};
    var h = (L.adresse ? row('Adresse', escHtml(L.adresse)) : '')
          + (L.type ? row('Type de logement', L.type === 'maison' ? 'Maison individuelle' : 'Appartement') : '')
          + row('Situation', LIB_VARIANT[state.variant] || '—')
          + row('État du logement', LIB_ETAT[state.etat] || '—');
    if (state.etat === 'arrete_police') h += row("Nature de l'arrêté", arrLib[val('arrete-type')] || '—');
    h += row('Surface habitable', (num('surface') || '—') + ' m²');
    if (num('annee')) h += row('Année de construction', num('annee'));
    h += row('DPE', (val('dpe-avant') === 'unknown' ? '?' : val('dpe-avant')) + ' → ' + (val('dpe-apres') === 'unknown' ? '?' : val('dpe-apres')));
    h += row('Coût des travaux', fmt(num('cout')) + ' HT');
    if (state.variant === 'bailleur') h += row("Convention Loc'Avantages", LIB_CONV[state.convention] || '—');
    if (state.variant === 'copro'){
      h += row('Nombre de lots', num('lots') || '—');
      h += row('Résidences principales', (num('part-rp') || '—') + ' %');
      h += row('Immatriculation registre', LIB_CONV[state.immat] || (state.immat === 'inconnu' ? 'Je ne sais pas' : '—'));
      if (state.copro && state.copro.adresse) h += row('Adresse de la copropriété', escHtml(state.copro.adresse));
    }
    if (state.variant !== 'copro'){
      h += row('Foyer', (num('foyer') || 1) + ' personne(s)');
      h += row('Revenu fiscal de référence', fmt(num('rfr')));
      h += row('Région', val('region') || 'Grand Est');
    }
    el('recap').innerHTML = h;
  }

  /* ── Lancement du calcul ────────────────────────────────────── */
  /* ── Étape 8 : Transmission ──────────────────────────────────── */
  var lastResult = null, lastPayload = null;

  function roundDown100(n){
    // Arrondi indicatif au millier inférieur (à la centaine inférieure sous 1 000 €).
    // Aucun décalage arbitraire : un montant pile sur un multiple reste inchangé.
    // C'est le calcul réel qui varie selon la saisie, jamais l'arrondi.
    var v = Number(n) || 0;
    if (v < 1000) return Math.max(0, Math.floor(v / 100) * 100);
    return Math.floor(v / 1000) * 1000;
  }
  function escapeHtml(s){
    return String(s == null ? '' : s).replace(/[&<>"]/g, function(c){
      return ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;' })[c];
    });
  }
  var LIB_CAT = { bleus:'très modestes', jaunes:'modestes', violets:'intermédiaires', roses:'supérieurs' };

  function renderTeaser(result){
    /* Mises en garde du moteur et version des barèmes, comme sur le tunnel principal. */
    if (window.RFAlertes){
      try {
        RFAlertes.rendre(result, 'rf-alertes');
        RFAlertes.rendreReferentiel(result, 'rf-referentiel');
        RFAlertes.rendreReferentiel(result, 'rf-referentiel-final');
      } catch (e) { console.warn('Alertes :', e); }
    }
    var vEl = el('tz-verdict');
    if (!vEl) return;
    // L'utilisateur peut revenir corriger ses réponses : on restaure le bloc de
    // transmission, qu'un passage précédent a pu masquer (cas non éligible).
    if (window.RFPartner) window.RFPartner.mount();
    var checkoutL = el('rf-lhi-checkout');
    if (checkoutL) checkoutL.hidden = false;
    validateLHI();
    if (!result || !result.eligible){
      vEl.innerHTML = '<div class="tz-verdict ko"><span>' +
        '<b>Cette aide ne peut pas être mobilisée en l\'état</b>' +
        escapeHtml((result && result.motif) || "Les conditions d'éligibilité ne sont pas réunies avec les réponses fournies.") +
        '</span></div>';
      // Rien à transmettre si l'aide est nulle : le bloc entier est masqué.
      if (checkoutL) checkoutL.hidden = true;
      return;
    }
    var contexte = (result.variant === 'occupant')
      ? 'Catégorie : <strong>' + (LIB_CAT[result.categorie] || result.categorie || '—') + '</strong> · propriétaire occupant'
      : (result.variant === 'bailleur'
          ? escapeHtml(result.typeLibelle || '') + ' · propriétaire bailleur'
          : 'Copropriété sous arrêté de police');
    var arrondi = roundDown100(result.aide.totalApresEcretement);
    vEl.innerHTML = '<div class="tz-verdict">' +
        '<svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" style="flex:0 0 auto;margin-top:2px"><path d="m5 12 5 5L20 7"/></svg>' +
        '<span><b>Votre projet est éligible</b>' + contexte + '</span>' +
      '</div>' +
      '<div class="tz-amount"><div class="lbl">Aide estimée jusqu\'à</div>' +
        '<div class="v">~ ' + arrondi.toLocaleString('fr-FR') + ' €</div>' +
        // Traçabilité complète : chaque euro du total est justifié à l'écran.
        (function(){
          var t = result.travaux, ai = result.aide;
          function fmtE(v){ return Math.round(Number(v) || 0).toLocaleString('fr-FR') + ' €'; }
          function ligne(k, v, cls){
            return '<div class="r' + (cls ? ' ' + cls : '') + '"><span>' + k + '</span><b>' + v + '</b></div>';
          }
          var plafonne = t.plafondApplique && t.coutHT > t.plafondApplique;
          return '<div class="tz-calc"><div class="h">Comment ce montant est calculé</div>' +
            ligne('Coût des travaux', fmtE(t.coutHT) + ' HT') +
            (plafonne ? ligne('Coût retenu (plafond ' + fmtE(t.plafondApplique) + ')', fmtE(t.coutRetenu)) : '') +
            (result.variant === 'occupant' && result.categorie
              ? ligne('Catégorie de revenus', LIB_CAT[result.categorie] || result.categorie) : '') +
            (result.variant === 'bailleur' && result.typeLibelle
              ? ligne('Nature des travaux', escapeHtml(result.typeLibelle)) : '') +
            ligne('Taux appliqué', Math.round(ai.tauxApplique * 100) + ' %') +
            ligne('Aide de base', fmtE(ai.base)) +
            (ai.primeSortiePassoire ? ligne('Prime sortie de passoire', '+ ' + fmtE(ai.primeSortiePassoire)) : '') +
            (ai.primeGainEnergetique ? ligne('Prime gain énergétique', '+ ' + fmtE(ai.primeGainEnergetique)) : '') +
            (ai.total > ai.totalApresEcretement
              /* Le taux d'écrêtement des ménages aux revenus supérieurs vaut
                 null : sans garde, l'écran affichait « Écrêtement NaN % ». */
              ? ligne(Number.isFinite(ai.ecretement)
                  ? '<abbr title="Plafond qui empêche le total des aides de dépasser un pourcentage du coût des travaux. Le surplus n\'est pas versé.">Écrêtement</abbr> ' + Math.round(ai.ecretement * 100) + ' % TTC'
                  : 'Écrêtement au plafond de dépense',
                '− ' + fmtE(ai.total - ai.totalApresEcretement)) : '') +
            ligne('Total calculé', fmtE(ai.totalApresEcretement), 'tot') +
          '</div>';
        })() +
        /* Régime dérogatoire : faute de DPE après travaux, le moteur retient
           l'hypothèse la plus défavorable (50 % sur 50 000 € au lieu de 80 %
           sur 70 000 €). L'écran doit le dire, sinon « aide estimée jusqu'à X € »
           laisse croire à un plafond alors que c'est un plancher. */
        ((result.dpeInconnu || result.derogatoire)
          ? '<div class="tz-derog" role="note"><strong>' +
              (result.dpeInconnu ? 'Estimation basse, faute d\u2019audit' : 'Régime dérogatoire appliqué') +
            '</strong>' +
              (result.dpeInconnu
                ? "La classe énergétique visée après travaux n'est pas connue : nous retenons le régime le plus prudent. Un audit établissant l'atteinte de la classe E ou mieux porterait le taux et le plafond à la hausse."
                : "Les travaux prévus ne permettent pas d'atteindre la classe E : c'est le régime dérogatoire, moins favorable, qui s'applique.") +
            '</div>'
          : '') +
        '<div class="hint tz-hint-fine">Estimation indicative, arrondie — le montant définitif est arrêté par l\u2019Anah à l\u2019instruction du dossier.</div>' +
      '</div>';
  }




  /* Le brouillon est créé dès l'arrivée sur l'étape de transmission, pour que
     le dossier transmis soit exactement celui qui a été affiché. */
  function assurerBrouillon(){
    try {
      if (!window.RFDossiers) return null;
      var draft = (RFDossiers.getOrCreateDraft || RFDossiers.createDraft)('indigne', lastPayload || {}, lastResult);
      if (draft && draft.id) localStorage.setItem('junglerenov.dossierEnAttente', draft.id);
      return draft;
    } catch(e){ console.warn('Création dossier indigne :', e); return null; }
  }

  /* ── Écran de calcul — animation puis passage automatique à la Transmission ──
     Même rythme que le tunnel énergétique : 6 items à ~900 ms. */
  var calcTimers = [];
  function stopCalcAnimation(){ calcTimers.forEach(function(t){ clearTimeout(t); }); calcTimers = []; }
  function startCalcAnimation(){
    stopCalcAnimation();
    var items   = document.querySelectorAll('#lhi-loader-checks .lc-item');
    var circle  = el('lhi-loader-circle');
    var pctEl   = el('lhi-loader-pct');
    var titleEl = el('lhi-loader-title');
    var subEl   = el('lhi-loader-sub');
    if (!items.length || !circle) return;
    var subs = [
      'Sources : Base Adresse Nationale + IGN',
      'Sources : Guide Anah éd. février 2026, pp. 63-67',
      'Sources : barèmes Anah publiés au JO',
      "Sources : règles de cumul MaPrimeRénov' / Anah",
      'Sources : conseils régionaux, métropoles, intercommunalités',
      'Sources : observatoire DPE ADEME (open data)'
    ];
    var DOT = '<svg width="10" height="10" viewBox="0 0 24 24" fill="currentColor"><circle cx="12" cy="12" r="6"/></svg>';
    var TICK = '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="m5 12 5 5L20 7"/></svg>';
    items.forEach(function(it){
      it.classList.remove('done','active');
      it.querySelector('.ic').innerHTML = DOT;
    });
    circle.style.setProperty('--p','0%');
    if (pctEl) pctEl.textContent = '0%';
    if (titleEl) titleEl.textContent = 'Connexion aux bases officielles…';
    if (subEl) subEl.textContent = 'Quelques secondes, ne fermez pas la fenêtre.';

    var stepDur = 900;
    items.forEach(function(it, i){
      calcTimers.push(setTimeout(function(){
        if (current !== 9) return;
        items.forEach(function(x){ x.classList.remove('active'); });
        it.classList.add('active');
        it.querySelector('.ic').innerHTML = '<span class="spinner"></span>';
        if (titleEl) titleEl.textContent = it.dataset.lbl;
        if (subEl) subEl.textContent = subs[i] || '';
      }, i * stepDur));
      calcTimers.push(setTimeout(function(){
        if (current !== 9) return;
        it.classList.remove('active');
        it.classList.add('done');
        it.querySelector('.ic').innerHTML = TICK;
        var pct = Math.round(((i+1) / items.length) * 100);
        circle.style.setProperty('--p', pct + '%');
        if (pctEl) pctEl.textContent = pct + '%';
      }, (i + 1) * stepDur));
    });
    calcTimers.push(setTimeout(function(){
      if (current !== 9) return;
      if (titleEl) titleEl.textContent = 'Analyse terminée';
      if (subEl) subEl.textContent = 'Affichage de votre estimation…';
    }, items.length * stepDur));
    calcTimers.push(setTimeout(function(){
      if (current === 9) goTo(8);
    }, items.length * stepDur + 600));
  }

  el('go-results').addEventListener('click', function(){
    // Le teaser est rendu par goTo(8) : source unique. On passe d'abord par le calcul.
    computeAndStore();
    goTo(9);
  });

  /* Construit le payload depuis l'état courant, calcule et mémorise le résultat.
     Appelée aussi bien par le récapitulatif que par chaque affichage du teaser. */
  function computeAndStore(){
    if (!C || !C.computeMprLogementDecent) return null;
    var annee = num('annee') || num('annee-copro');
    var payload = {
      variant: state.variant || 'occupant',
      rfr: num('rfr'), foyer: num('foyer') || 1, region: val('region') || 'Grand Est',
      ageLogementAnnees: annee > 0 ? (new Date().getFullYear() - annee) : 0,
      surface: num('surface'),
      coutTravauxHT: num('cout'),
      /* Part énergétique déclarée, en ratio. Absente → le moteur retient 50 % et le signale. */
      partEnergetique: (num('cout') > 0 && num('cout-energie') > 0)
        ? Math.min(1, num('cout-energie') / num('cout')) : undefined,
      dpeAvant: val('dpe-avant') || 'unknown',
      dpeApres: val('dpe-apres') || 'unknown',
      // « Je ne sais pas » → hypothèse prudente : moyennement dégradé
      etatLogement: (state.etat === 'inconnu' ? 'moyennement_degrade' : state.etat),
      arretePolice: state.etat === 'arrete_police' && !!val('arrete-type'),
      arreteType: val('arrete-type') || null,
      nbLotsCopro: num('lots'),
      partResidencePrincipale: num('part-rp'),
      immatriculation: state.immat,
      // Enrichit le profil stocké dans le dossier. computeMprLogementDecent()
      // ignore proprement les champs qu'il n'utilise pas.
      logement: {
        adresse:    state.logement.adresse || null,
        codePostal: state.logement.codePostal || null,
        ville:      state.logement.ville || null,
        dept:       state.logement.dept || null,
        codeInsee:  state.logement.codeInsee || null,
        region:     state.logement.region || null,
        surface:    num('surface') || null,
        annee:      num('annee') || num('annee-copro') || null,
        type:       state.logement.type || null,
        dpeAvant:   val('dpe-avant') || null,
        dpeApres:   val('dpe-apres') || null,
      },
      // Adresse de la copropriété, saisie séparément au variant copro
      coproAdresse: (state.copro && state.copro.adresse) || null,
      coproCodePostal: (state.copro && state.copro.codePostal) || null,
      coproVille: (state.copro && state.copro.ville) || null,
      conventionLocAvantages: state.variant === 'bailleur' ? (state.convention !== 'non') : undefined,
      conventionReponse: state.convention,
      // Gain énergétique déduit du saut de classes visé (2 classes ≈ 35 %)
      gainEnergetiquePct: (function(){
        var O = ['A','B','C','D','E','F','G'];
        var ia = O.indexOf(val('dpe-avant')), ib = O.indexOf(val('dpe-apres'));
        if (ia < 0 || ib < 0) return 0;
        var saut = ia - ib;
        return saut >= 3 ? 50 : (saut === 2 ? 35 : 0);
      })(),
    };
    var result = C.computeMprLogementDecent(payload);
    lastResult = result;
    lastPayload = payload;
    try { if (window.rfUpdateCheckoutAmount) window.rfUpdateCheckoutAmount(); } catch(e){}
    try {
      localStorage.setItem('junglerenov.indigne.result', JSON.stringify({
        input: payload, result: result, computedAt: new Date().toISOString(),
      }));
    } catch(e){}
    return result;
  }


  /* ── Transmission (même écran que le tunnel énergétique) ───────
     Le brouillon est créé à l'arrivée sur l'étape (assurerBrouillon) ; il passe
     à l'état « créé » au clic sur « Créer mon dossier ». */
  function updateLhiCheckoutAmount(){
    var amountEl = document.getElementById('lhi-roi-amount');
    if (!amountEl || !lastResult) return;
    var total = (lastResult.aide && (lastResult.aide.totalApresEcretement || lastResult.aide.total)) || 0;
    amountEl.textContent = Math.round(Number(total) || 0).toLocaleString('fr-FR') + ' €';
    try { if (window.__rfLeadMagnet_lhi) window.__rfLeadMagnet_lhi(total); } catch(e){}
  }
  window.rfUpdateCheckoutAmount = updateLhiCheckoutAmount;

  /* Récapitulatif de transmission : aucun montant relatif à JungleRenov. */
  function updateRecapTransmission(){
    var setTxt = function(id, v){ var e = document.getElementById(id); if (e) e.textContent = v; };
    var lg = (lastPayload && lastPayload.logement) || {};
    setTxt('tx-adresse', lg.adresse || '—');
    var total = (lastResult && lastResult.aide && (lastResult.aide.totalApresEcretement || lastResult.aide.total)) || 0;
    setTxt('tx-aides', total ? Math.round(total).toLocaleString('fr-FR') + ' €' : '—');
    if (window.RFTransmission){
      RFTransmission.injectStyles();
      var dept = lg.dept || (lg.codePostal ? String(lg.codePostal).slice(0, 2) : '')
              || RFTransmission.deptFromDossier({ profile: { logement: lg } });
      var pro = RFTransmission.renderProfessionnel(document.getElementById('rf-tx-pro'), 'indigne', dept);
      window.__rfPro = pro;
      var dest = document.getElementById('tx-destinataire');
      if (dest && pro) dest.textContent = pro.designe
        ? pro.nom + ' (' + pro.role + ')'
        : "l'accompagnateur agréé " + pro.role + ' désigné pour mon département';
    }
    assurerBrouillon();
  }
  window.rfUpdateRecapTransmission = updateRecapTransmission;

  /* Transmission : le bouton n'est actif qu'avec le consentement explicite à
     la transmission des données et l'acceptation des CGU. Jamais pré-coché. */
  var lhiTos = document.getElementById('lhi-tos');
  var lhiConsent = document.getElementById('lhi-transmission');
  var lhiSubmit = document.getElementById('lhi-submit');

  function validateLHI(){
    if (!lhiSubmit) return;
    var fn = (document.getElementById('lhi-firstname') || {}).value || '';
    var ln = (document.getElementById('lhi-lastname') || {}).value || '';
    var em = (document.getElementById('lhi-email') || {}).value || '';
    var ok = fn.trim().length >= 2
          && ln.trim().length >= 2
          && /^\S+@\S+\.\S+$/.test(em.trim())
          && !!(lhiTos && lhiTos.checked)
          && !!(lhiConsent && lhiConsent.checked);
    lhiSubmit.disabled = !ok;
    lhiSubmit.style.opacity = ok ? '1' : '.55';
    lhiSubmit.style.cursor = ok ? 'pointer' : 'not-allowed';
  }
  ['lhi-firstname','lhi-lastname','lhi-email','lhi-tos','lhi-transmission'].forEach(function(id){
    var el2 = document.getElementById(id);
    if (!el2) return;
    el2.addEventListener('input', validateLHI);
    el2.addEventListener('change', validateLHI);
  });
  validateLHI();

  if (lhiSubmit) lhiSubmit.addEventListener('click', function(){
    if (lhiSubmit.disabled) return;
    var label = lhiSubmit.textContent;
    lhiSubmit.disabled = true;
    lhiSubmit.textContent = 'Transmission…';

    /* Garde : un dossier n'est jamais transmis sans résultat calculé. Cascade —
       dernier calcul en mémoire, puis estimation stockée, puis rejeu du moteur. */
    var resoudreResultat = function(){
      var ok = function(r){ return !!(r && r.aide && (r.aide.totalApresEcretement > 0 || r.aide.total > 0)); };
      if (ok(lastResult)) return lastResult;
      try {
        var stored = JSON.parse(localStorage.getItem('junglerenov.indigne.result') || 'null');
        if (stored && ok(stored.result)) return stored.result;
      } catch(e){}
      try {
        var C2 = window.RFCompute;
        if (C2 && C2.computeMpld && lastPayload){
          var r = C2.computeMpld(lastPayload);
          if (ok(r)) return r;
        }
      } catch(e){ console.warn('[Transmission habitat dégradé] rejeu du moteur impossible :', e); }
      return null;
    };

    var resultatValide = resoudreResultat();
    if (!resultatValide){
      console.error('[Transmission habitat dégradé] résultat vide — création du dossier abandonnée');
      lhiSubmit.disabled = false;
      lhiSubmit.textContent = label;
      var box = document.createElement('div');
      box.setAttribute('role', 'alert');
      box.style.cssText = 'position:fixed;top:20px;left:50%;transform:translateX(-50%);z-index:2147483001;background:#FEE2E2;border:2px solid #991B1B;color:#991B1B;padding:16px 24px;border-radius:6px;max-width:420px;font:17px/1.5 "Komet","Red Hat Display",system-ui,sans-serif;box-shadow:none';
      box.innerHTML = '<strong>Impossible de transmettre votre dossier</strong><br />' +
        "Votre aide Ma Prime Logement Décent n'a pas pu être calculée. Reprenez le parcours depuis la première étape. " +
        '<a href="parcours-indigne.dc.html?fresh=1" style="color:#1F6B3F;font-weight:600">Reprendre</a>';
      document.body.appendChild(box);
      setTimeout(function(){ if (box.parentNode) box.parentNode.removeChild(box); }, 15000);
      return;
    }

    try {
      /* Identité : le compte sert au suivi du dossier, jamais à facturer. */
      var prof = {};
      try { prof = JSON.parse(localStorage.getItem('junglerenov.profile') || '{}'); } catch(e){}
      prof.firstname = (document.getElementById('lhi-firstname') || {}).value || prof.firstname;
      prof.lastname  = (document.getElementById('lhi-lastname') || {}).value || prof.lastname;
      prof.email     = (document.getElementById('lhi-email') || {}).value || prof.email;
      prof.telephone = (document.getElementById('lhi-tel') || {}).value || prof.telephone;
      localStorage.setItem('junglerenov.profile', JSON.stringify(prof));

      var dossierId = localStorage.getItem('junglerenov.dossierEnAttente');
      if (!dossierId && window.RFDossiers){
        var d = (RFDossiers.getOrCreateDraft || RFDossiers.createDraft)('indigne', lastPayload || {}, resultatValide);
        dossierId = d && d.id;
      }
      // Le brouillon a pu être créé avant le dernier recalcul : on le réaligne.
      if (window.RFDossiers && dossierId && RFDossiers.updateResult) RFDossiers.updateResult(dossierId, resultatValide);

      var pro = window.__rfPro || null;
      if (window.RFTransmission && dossierId){
        RFTransmission.transmettre(dossierId, {
          consentement: true,
          partenaireNom: pro && pro.nom,
          partenaireRole: pro && pro.role,
          departement: pro && pro.departement,
        });
      }
      localStorage.removeItem('junglerenov.dossierEnAttente');

      var succ = document.getElementById('lhi-success');
      if (succ){
        document.getElementById('lhi-signup').style.display = 'none';
        var partEl = document.getElementById('lhi-succ-partenaire');
        if (partEl) partEl.textContent = (pro && pro.nom) || 'Un accompagnateur agréé de votre département';
        succ.classList.add('show');
        jrScrollTo(succ);
      }
      setTimeout(function(){
        /* Le tableau de bord est la seule page qui traite ?transmis=1, et ces
           tunnels ne créent ni client ni session : « Mes aides » renverrait
           l'utilisateur sur un mur de connexion juste après son succès. */
        location.href = 'dashboard.dc.html?transmis=1' + (dossierId ? '&dossier=' + encodeURIComponent(dossierId) : '');
      }, 2200);
    } catch(err){ console.warn('Transmission habitat dégradé :', err); location.href = 'dashboard.dc.html'; }
  });

  bindStepperClicks();
  goTo(1);
})();

