/* Lead magnet LHI — capture email contre PDF récap.
   Même comportement que le tunnel énergétique : validation email + consentement,
   feedback d'erreur, succès simulé, stockage local en attendant le backend. */
(function(){
  'use strict';
  var block   = document.getElementById('lead-magnet-lhi');
  var amountE = document.getElementById('lead-magnet-lhi-amount');
  var submit  = document.getElementById('lead-magnet-lhi-submit');
  var email   = document.getElementById('lead-magnet-lhi-email');
  var consent = document.getElementById('lead-magnet-lhi-consent');
  var errBox  = document.getElementById('lead-magnet-lhi-error');
  var form    = document.getElementById('lead-magnet-lhi-form');
  var success = document.getElementById('lead-magnet-lhi-success');
  if (!block || !submit) return;
  var currentTotal = 0;

  function show(total){
    total = Math.round(Number(total) || 0);
    if (total <= 0) return;
    currentTotal = total;
    amountE.textContent = total.toLocaleString('fr-FR') + ' €';
    block.style.display = 'block';
  }
  window.__rfLeadMagnet_lhi = show;

  /* Le montant suit la carte ROI : dès qu'elle est peuplée, le bloc s'affiche. */
  var roi = document.getElementById('lhi-roi-amount');
  if (roi){
    var sync = function(){ show(parseInt((roi.textContent || '').replace(/[^0-9]/g, ''), 10)); };
    sync();
    new MutationObserver(sync).observe(roi, {childList:true, characterData:true, subtree:true});
  }

  submit.addEventListener('click', function(){
    errBox.style.display = 'none';
    var v = (email.value || '').trim();
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v) || !consent.checked){ errBox.style.display = 'block'; return; }
    submit.disabled = true;
    submit.textContent = 'Envoi…';
    setTimeout(function(){
      form.style.display = 'none';
      success.style.display = 'block';
      /* TODO : brancher au vrai endpoint email/PDF quand le backend sera prêt. */
      try {
        var leads = JSON.parse(localStorage.getItem('junglerenov.leads.lhi') || '[]');
        leads.push({ email: v, timestamp: new Date().toISOString(), aide: currentTotal });
        localStorage.setItem('junglerenov.leads.lhi', JSON.stringify(leads));
      } catch(e){}
    }, 800);
  });
})();

