    if (!badge) return;
    const now = new Date();
    const n = (window.RFDossiers ? RFDossiers.getAll() : []).filter(d => {
      if (!d.transmisLe) return false;
      const t = new Date(d.transmisLe);
      return t.getMonth() === now.getMonth() && t.getFullYear() === now.getFullYear();
    }).length;
